window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["办法"] = {"fapiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强发票管理和财务监督，保障国家税收收入，维护经济秩序，根据《中华人民共和国税收征收管理法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内印制、领用、开具、取得、保管、缴销发票的单位和个人（以下称印制、使用发票的单位和个人），必须遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称发票，是指在购销商品、提供或者接受服务以及从事其他经营活动中，开具、收取的收付款凭证。"},{"i":4,"n":"第四条","txt":"发票管理工作应当坚持和加强党的领导，为经济社会发展服务。"},{"i":5,"n":"第五条","txt":"发票的种类、联次、内容、编码规则、数据标准、使用范围等具体管理办法由国务院税务主管部门规定。"},{"i":6,"n":"第六条","txt":"对违反发票管理法规的行为，任何单位和个人可以举报。税务机关应当为检举人保密，并酌情给予奖励。"},{"i":7,"n":"第七条","txt":"增值税专用发票由国务院税务主管部门确定的企业印制；其他发票，按照国务院税务主管部门的规定，由省、自治区、直辖市税务机关确定的企业印制。禁止私自印制、伪造、变造发票。"},{"i":8,"n":"第八条","txt":"印制发票的企业应当具备下列条件："},{"i":9,"n":"第九条","txt":"印制发票应当使用国务院税务主管部门确定的全国统一的发票防伪专用品。禁止非法制造发票防伪专用品。"},{"i":10,"n":"第十条","txt":"发票应当套印全国统一发票监制章。全国统一发票监制章的式样和发票版面印刷的要求，由国务院税务主管部门规定。发票监制章由省、自治区、直辖市税务机关制作。禁止伪造发票监制章。"},{"i":11,"n":"第十一条","txt":"印制发票的企业按照税务机关的统一规定，建立发票印制管理制度和保管措施。"},{"i":12,"n":"第十二条","txt":"印制发票的企业必须按照税务机关确定的式样和数量印制发票。"},{"i":13,"n":"第十三条","txt":"发票应当使用中文印制。民族自治地方的发票，可以加印当地一种通用的民族文字。有实际需要的，也可以同时使用中外两种文字印制。"},{"i":14,"n":"第十四条","txt":"各省、自治区、直辖市内的单位和个人使用的发票，除增值税专用发票外，应当在本省、自治区、直辖市内印制；确有必要到外省、自治区、直辖市印制的，应当由省、自治区、直辖市税务机关商印制地省、自治区、直辖市税务机关同意后确定印制发票的企业。"},{"i":15,"n":"第十五条","txt":"需要领用发票的单位和个人，应当持设立登记证件或者税务登记证件，以及经办人身份证明，向主管税务机关办理发票领用手续。领用纸质发票的，还应当提供按照国务院税务主管部门规定式样制作的发票专用章的印模。主管税务机关根据领用单位和个人的经营范围、规模和风险等级，在5个工作日内确认领用发票的种类、数量以及领用方式。"},{"i":16,"n":"第十六条","txt":"需要临时使用发票的单位和个人，可以凭购销商品、提供或者接受服务以及从事其他经营活动的书面证明、经办人身份证明，直接向经营地税务机关申请代开发票。依照税收法律、行政法规规定应当缴纳税款的，税务机关应当先征收税款，再开具发票。税务机关根据发票管理的需要，可以按照国务院税务主管部门的规定委托其他单位代开发票。"},{"i":17,"n":"第十七条","txt":"临时到本省、自治区、直辖市以外从事经营活动的单位或者个人，应当凭所在地税务机关的证明，向经营地税务机关领用经营地的发票。"},{"i":18,"n":"第十八条","txt":"销售商品、提供服务以及从事其他经营活动的单位和个人，对外发生经营业务收取款项，收款方应当向付款方开具发票；特殊情况下，由付款方向收款方开具发票。"},{"i":19,"n":"第十九条","txt":"所有单位和从事生产、经营活动的个人在购买商品、接受服务以及从事其他经营活动支付款项，应当向收款方取得发票。取得发票时，不得要求变更品名和金额。"},{"i":20,"n":"第二十条","txt":"不符合规定的发票，不得作为财务报销凭证，任何单位和个人有权拒收。"},{"i":21,"n":"第二十一条","txt":"开具发票应当按照规定的时限、顺序、栏目，全部联次一次性如实开具，开具纸质发票应当加盖发票专用章。"},{"i":22,"n":"第二十二条","txt":"安装税控装置的单位和个人，应当按照规定使用税控装置开具发票，并按期向主管税务机关报送开具发票的数据。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人应当按照发票管理规定使用发票，不得有下列行为："},{"i":24,"n":"第二十四条","txt":"除国务院税务主管部门规定的特殊情形外，纸质发票限于领用单位和个人在本省、自治区、直辖市内开具。"},{"i":25,"n":"第二十五条","txt":"除国务院税务主管部门规定的特殊情形外，任何单位和个人不得跨规定的使用区域携带、邮寄、运输空白发票。"},{"i":26,"n":"第二十六条","txt":"开具发票的单位和个人应当建立发票使用登记制度，配合税务机关进行身份验证，并定期向主管税务机关报告发票使用情况。"},{"i":27,"n":"第二十七条","txt":"开具发票的单位和个人应当在办理变更或者注销税务登记的同时，办理发票的变更、缴销手续。"},{"i":28,"n":"第二十八条","txt":"开具发票的单位和个人应当按照国家有关规定存放和保管发票，不得擅自损毁。已经开具的发票存根联，应当保存5年。"},{"i":29,"n":"第二十九条","txt":"税务机关在发票管理中有权进行下列检查："},{"i":30,"n":"第三十条","txt":"印制、使用发票的单位和个人，必须接受税务机关依法检查，如实反映情况，提供有关资料，不得拒绝、隐瞒。"},{"i":31,"n":"第三十一条","txt":"税务机关需要将已开具的发票调出查验时，应当向被查验的单位和个人开具发票换票证。发票换票证与所调出查验的发票有同等的效力。被调出查验发票的单位和个人不得拒绝接受。"},{"i":32,"n":"第三十二条","txt":"单位和个人从中国境外取得的与纳税有关的发票或者凭证，税务机关在纳税审查时有疑义的，可以要求其提供境外公证机构或者注册会计师的确认证明，经税务机关审核认可后，方可作为记账核算的凭证。"},{"i":33,"n":"第三十三条","txt":"违反本办法的规定，有下列情形之一的，由税务机关责令改正，可以处1万元以下的罚款；有违法所得的予以没收："},{"i":34,"n":"第三十四条","txt":"跨规定的使用区域携带、邮寄、运输空白发票，以及携带、邮寄或者运输空白发票出入境的，由税务机关责令改正，可以处1万元以下的罚款；情节严重的，处1万元以上3万元以下的罚款；有违法所得的予以没收。"},{"i":35,"n":"第三十五条","txt":"违反本办法的规定虚开发票的，由税务机关没收违法所得；虚开金额在1万元以下的，可以并处5万元以下的罚款；虚开金额超过1万元的，并处5万元以上50万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"私自印制、伪造、变造发票，非法制造发票防伪专用品，伪造发票监制章，窃取、截留、篡改、出售、泄露发票数据的，由税务机关没收违法所得，没收、销毁作案工具和非法物品，并处1万元以上5万元以下的罚款；情节严重的，并处5万元以上50万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，由税务机关处1万元以上5万元以下的罚款；情节严重的，处5万元以上50万元以下的罚款；有违法所得的予以没收："},{"i":38,"n":"第三十八条","txt":"对违反发票管理规定2次以上或者情节严重的单位和个人，税务机关可以向社会公告。"},{"i":39,"n":"第三十九条","txt":"违反发票管理法规，导致其他单位或者个人未缴、少缴或者骗取税款的，由税务机关没收违法所得，可以并处未缴、少缴或者骗取的税款1倍以下的罚款。"},{"i":40,"n":"第四十条","txt":"当事人对税务机关的处罚决定不服的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":41,"n":"第四十一条","txt":"税务人员利用职权之便，故意刁难印制、使用发票的单位和个人，或者有违反发票管理法规行为的，依照国家有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"国务院税务主管部门可以根据有关行业特殊的经营方式和业务需求，会同国务院有关主管部门制定该行业的发票管理办法。"},{"i":43,"n":"第四十三条","txt":"本办法自发布之日起施行。财政部1986年发布的《全国发票管理暂行办法》和原国家税务局1991年发布的《关于对外商投资企业和外国企业发票管理的暂行规定》同时废止。"}],"guojingkouanweishengjiandubanfa":[{"i":1,"n":"第一条","txt":"为了加强国境口岸和国际航行交通工具的卫生监督工作，改善国境口岸和交通工具的卫生面貌，控制和消灭传染源，切断传播途径，防止传染病由国外传入和由国内传出，保障人民身体健康，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于对外开放的港口、机场、车站、关口（下称国境口岸）和停留在这些处所的国际航行的船舶、飞机和车辆（下称交通工具）。"},{"i":3,"n":"第三条","txt":"国境口岸应当建立卫生清扫制度，消灭蚊蝇孳生场所，设置污物箱，定期进行清理，保持环境整洁。"},{"i":4,"n":"第四条","txt":"国境口岸的生活垃圾应当日产日清，设置的固定垃圾场，应当定期清除；生活污水不得任意排放，应当做到无害化处理，以防止污染环境和水源。"},{"i":5,"n":"第五条","txt":"对国境口岸的建筑物，有关部门应当采取切实可行的措施，控制病媒昆虫、啮齿动物，使其数量降低到不足为害的程度。"},{"i":6,"n":"第六条","txt":"候船室、候机室、候车室、候检室应当做到地面整洁、墙壁无尘土、窗明几净、通风良好，并备有必要的卫生设施。"},{"i":7,"n":"第七条","txt":"国境口岸的餐厅、食堂、厨房、小卖部应当建立和健全卫生制度，经常保持整洁，做到墙壁、天花板、桌椅清洁无尘土；应当有防蚊、防蝇、防鼠和冷藏设备，做到室内无蚊、无蝇、无鼠、无蟑螂。"},{"i":8,"n":"第八条","txt":"国境口岸的厕所和浴室应当有专人管理，及时打扫，保持整洁，做到无蝇、无臭味。"},{"i":9,"n":"第九条","txt":"国境口岸的仓库、货场应当保持清洁、整齐；发现鼠类有反常死亡时，应当及时向卫生检疫机关或地方卫生防疫部门报告。"},{"i":10,"n":"第十条","txt":"做好国境口岸水源保护，在水源周围直径30米内，不得修建厕所、渗井等污染水源设施。"},{"i":11,"n":"第十一条","txt":"交通工具上必须备有急救药物、急救设备及消毒、杀虫、灭鼠药物。必要时，船舶上还需安排临时隔离室。"},{"i":12,"n":"第十二条","txt":"交通工具上的病媒昆虫和啮齿动物的防除："},{"i":13,"n":"第十三条","txt":"交通工具上的厕所、浴室必须保持整洁，无臭味。"},{"i":14,"n":"第十四条","txt":"交通工具上的粪便、垃圾、污水处理的卫生要求："},{"i":15,"n":"第十五条","txt":"交通工具的货舱、行李车、邮政车和货车的卫生要求："},{"i":16,"n":"第十六条","txt":"交通工具上的客舱、宿舱、客车的卫生要求："},{"i":17,"n":"第十七条","txt":"供应国境口岸和交通工具上的食品必须符合《中华人民共和国食品安全法》的规定和食品安全标准。"},{"i":18,"n":"第十八条","txt":"凡供应国境口岸和交通工具上的饮用水必须符合我国规定的“生活饮用水卫生标准”。供应饮用水的运输工具、储存容器及输水管道等设备都应当经常冲洗干净，保持清洁。"},{"i":19,"n":"第十九条","txt":"供应食品、饮用水的从业人员的卫生要求："},{"i":20,"n":"第二十条","txt":"国境口岸和交通工具的负责人在卫生工作方面的责任是："},{"i":21,"n":"第二十一条","txt":"国境口岸卫生检疫机关对国境口岸和交通工具进行卫生监督，其主要职责是："},{"i":22,"n":"第二十二条","txt":"国境口岸卫生检疫机关设国境口岸卫生监督员1至5名，执行卫生监督任务，发给统一式样的执法证件。"},{"i":23,"n":"第二十三条","txt":"国境口岸卫生监督员持其证件，有权对国境口岸和交通工具的负责人，进行卫生监督、检查和技术指导；配合有关部门，对卫生工作情况不良或引起传染病传播的单位或个人，提出改进意见，协同有关部门采取必要措施，进行处理。"},{"i":24,"n":"第二十四条","txt":"国境口岸卫生检疫机关，对贯彻执行本办法和国家有关卫生法令、条例、规定，做出显著成绩的单位和个人，应当给予表扬和奖励。"},{"i":25,"n":"第二十五条","txt":"国境口岸卫生检疫机关，对违犯本办法和有关卫生法令、条例、规定的单位和个人，应当根据不同情况，给予警告、罚款，直至提请司法机关依法惩处。"},{"i":26,"n":"第二十六条","txt":"本办法自发布之日起施行。"}],"guojiahuobichurujingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强国家货币出入境管理，维护国家金融秩序，适应改革开放的需要，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国家货币，是指中国人民银行发行的人民币。"},{"i":3,"n":"第三条","txt":"国家对货币出入境实行限额管理制度。"},{"i":4,"n":"第四条","txt":"携带国家货币出入境的，应当按照国家规定向海关如实申报。"},{"i":5,"n":"第五条","txt":"不得在邮件中夹带国家货币出入境。不得擅自运输国家货币出入境。"},{"i":6,"n":"第六条","txt":"违反国家规定运输、携带、在邮件中夹带国家货币出入境的，由国家有关部门依法处理；情节严重，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":7,"n":"第七条","txt":"本办法由中国人民银行负责解释。"},{"i":8,"n":"第八条","txt":"本办法自一九九三年三月一日起施行。一九五一年三月六日中央人民政府政务院公布的《中华人民共和国禁止国家货币出入国境办法》同时废止。"}],"qiangzhijiandingdegongzuojiliangqijujiandingguanli682150":[{"i":1,"n":"第一条","txt":"为适应社会主义现代化建设需要，维护国家和消费者的利益，保护人民健康和生命、财产的安全，加强对强制检定的工作计量器具的管理，根据《中华人民共和国计量法》第九条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"强制检定是指由县级以上人民政府计量行政部门所属或者授权的计量检定机构，对用于贸易结算、安全防护、医疗卫生、环境监测方面，并列入本办法所附《中华人民共和国强制检定的工作计量器具目录》的计量器具实行定点定期检定。"},{"i":3,"n":"第三条","txt":"县级以上人民政府计量行政部门对本行政区域内的强制检定工作统一实施监督管理，并按照经济合理、就地就近的原则，指定所属或者授权的计量检定机构执行强制检定任务。"},{"i":4,"n":"第四条","txt":"县级以上人民政府计量行政部门所属计量检定机构，为实施国家强制检定所需要的计量标准和检定设施由当地人民政府负责配备。"},{"i":5,"n":"第五条","txt":"使用强制检定的工作计量器具的单位或者个人，必须按照规定将其使用的强制检定的工作计量器具登记造册，报当地县（市）级人民政府计量行政部门备案，并向其指定的计量检定机构申请周期检定。当地不能检定的，向上一级人民政府计量行政部门指定的计量检定机构申请周期检定。"},{"i":6,"n":"第六条","txt":"强制检定的周期，由执行强制检定的计量检定机构根据计量检定规程确定。"},{"i":7,"n":"第七条","txt":"属于强制检定的工作计量器具，未按照本办法规定申请检定或者经检定不合格的，任何单位或者个人不得使用。"},{"i":8,"n":"第八条","txt":"国务院计量行政部门和各省、自治区、直辖市人民政府计量行政部门应当对各种强制检定的工作计量器具作出检定期限的规定。执行强制检定工作的机构应当在规定期限内按时完成检定。"},{"i":9,"n":"第九条","txt":"执行强制检定的机构对检定合格的计量器具，发给国家统一规定的检定证书、检定合格证或者在计量器具上加盖检定合格印；对检定不合格的，发给检定结果通知书或者注销原检定合格印、证。"},{"i":10,"n":"第十条","txt":"县级以上人民政府计量行政部门按照有利于管理、方便生产和使用的原则，结合本地区的实际情况，可以授权有关单位的计量检定机构在规定的范围内执行强制检定工作。"},{"i":11,"n":"第十一条","txt":"被授权执行强制检定任务的机构，其相应的计量标准，应当接受计量基准或者社会公用计量标准的检定；执行强制检定的人员，必须经授权单位考核合格；授权单位应当对其检定工作进行监督。"},{"i":12,"n":"第十二条","txt":"被授权执行强制检定任务的机构成为计量纠纷中当事人一方时，按照《中华人民共和国计量法实施细则》的有关规定处理。"},{"i":13,"n":"第十三条","txt":"企业、事业单位应当对强制检定的工作计量器具的使用加强管理，制定相应的规章制度，保证按照周期进行检定。"},{"i":14,"n":"第十四条","txt":"使用强制检定的工作计量器具的任何单位或者个人，计量监督、管理人员和执行强制检定工作的计量检定人员，违反本办法规定的，按照《中华人民共和国计量法实施细则》的有关规定，追究法律责任。"},{"i":15,"n":"第十五条","txt":"执行强制检定工作的机构，违反本办法第八条规定拖延检定期限的，应当按照送检单位的要求，及时安排检定，并免收检定费。"},{"i":16,"n":"第十六条","txt":"国务院计量行政部门可以根据本办法和《中华人民共和国强制检定的工作计量器具目录》，制定强制检定的工作计量器具的明细目录。"},{"i":17,"n":"第十七条","txt":"本办法由国务院计量行政部门负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自1987年7月1日起施行。"}],"dalaochenchuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为保证航行安全，加强沉船的打捞和管理工作，制定本办法。"},{"i":2,"n":"第二条","txt":"除军事舰艇和木帆船外，在中华人民共和国领海和内河的沉船，包括沉船本体、船上器物以及货物都适用本办法。"},{"i":3,"n":"第三条","txt":"下列沉船应当进行打捞："},{"i":4,"n":"第四条","txt":"严重危害船舶安全航行的沉船，有关港（航）务主管机关有权立即进行打捞或者解体清除，但是所采取措施应即通知沉船所有人，如果沉船所有人不明或者无法通知时，应当在当地和中央报纸上公告。"},{"i":5,"n":"第五条","txt":"妨碍船舶航行、航道整治或者工程建筑的沉船，有关港（航）务主管机关应当根据具体情况规定申请期限和打捞期限，通知或公告沉船所有人。"},{"i":6,"n":"第六条","txt":"其他不属于第五条规定范围的沉船，沉船所有人应当自船舶沉没之日起一年以内提出打捞计划和完工期限，经有关港（航）务主管机关批准后进行打捞。"},{"i":7,"n":"第七条","txt":"沉船所有人除遇有特殊情况向有关港（航）务主管机关申请延期并经核准外，在下列情况下即丧失各该沉船的所有权："},{"i":8,"n":"第八条","txt":"有关港（航）务主管机关根据第四条规定所捞起的船体、船用器物、货物或者解体所得的钢材、机件等，在无法或者不易保管的情况下，可以作价处理。"},{"i":9,"n":"第九条","txt":"打捞和解体清除沉船必须经过批准，批准权限如下："},{"i":10,"n":"第十条","txt":"未经过批准，任何人都不得擅自打捞或拆除沉船。偶然捞获的沉没物资应当送当地港（航）务主管机关处理，由各该机关酌情给予奖励。"},{"i":11,"n":"第十一条","txt":"有修复价值而不严重妨碍航行安全的沉船，不得解体。申请解体沉船必须提出该沉船确无修复价值的可靠勘测资料。解体打捞或者清除机动船舶，不得在水下破坏主副机、锅炉等物，应当尽量完整捞起，并经有关港（航）务主管机关鉴定后，才可以处理。"},{"i":12,"n":"第十二条","txt":"全国各地沉船勘测工作，由交通部打捞专业机构负责进行，但是有关港（航）务主管机关因业务上的需要，也可以自行勘测。其他机关、企业、个人必须经有关港（航）务主管机关批准才可以进行沉船勘测工作，并应将勘测结果抄送原批准机关。"},{"i":13,"n":"第十三条","txt":"本办法经国务院批准由交通部发布施行。"}],"haiguanduichukoujiagongqujianguandezanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强与完善加工贸易管理，规范海关对出口加工区的监管，促进出口加工区的健康发展，鼓励扩大外贸出口，根据《中华人民共和国海关法》和国家有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"为防止重复建设，在中华人民共和国境内设立出口加工区（以下简称加工区），只能设在已经国务院批准的现有经济技术开发区内，并由省（自治区、直辖市）人民政府报国务院批准。"},{"i":3,"n":"第三条","txt":"加工区是海关监管的特定区域。海关在加工区内设立机构，并依照本办法，对进、出加工区的货物及区内相关场所实行24小时监管。"},{"i":4,"n":"第四条","txt":"加工区与中华人民共和国境内的其他地区（以下简称区外）之间，须设置符合海关监管要求的隔离设施及闭路电视监控系统。经海关总署对加工区的隔离设施验收合格后，方可开展加工区有关业务。"},{"i":5,"n":"第五条","txt":"区内设置加工区管理委员会和出口加工企业、专为出口加工企业生产提供服务的仓储企业以及经海关核准专门从事加工区内货物进、出的运输企业。"},{"i":6,"n":"第六条","txt":"区内不得经营商业零售、一般贸易、转口贸易及其他与加工区无关的业务。"},{"i":7,"n":"第七条","txt":"在加工区内设立的企业（以下简称区内企业），应向海关办理注册手续。"},{"i":8,"n":"第八条","txt":"区内企业应当依据《中华人民共和国会计法》及国家有关法律、法规的规定，设置符合海关监管要求的账簿、报表。凭合法、有效凭证记账并进行核算，记录本企业有关进、出加工区货物和物品的库存、转让、转移、销售、加工、使用和损耗等情况。"},{"i":9,"n":"第九条","txt":"加工区实行计算机联网管理和海关稽查制度。"},{"i":10,"n":"第十条","txt":"区内企业开展加工贸易业务不实行加工贸易银行保证金台账制度，海关不实行《加工贸易登记手册》管理。"},{"i":11,"n":"第十一条","txt":"海关对进、出加工区的货物、物品、运输工具、人员及区内有关场所，有权依照《中华人民共和国海关法》的规定进行检查、查验。"},{"i":12,"n":"第十二条","txt":"国家对区内加工产品不征收增值税。"},{"i":13,"n":"第十三条","txt":"国家禁止进、出口的货物、物品，不得进、出加工区。"},{"i":14,"n":"第十四条","txt":"加工区与境外之间进、出的货物，由货主或其代理人根据加工区管理委员会的批件，填写进、出境货物备案清单，向主管海关备案。备案清单由海关总署统一制发。"},{"i":15,"n":"第十五条","txt":"海关对加工区与境外之间进、出的货物，按照直通式或转关运输的办法进行监管。"},{"i":16,"n":"第十六条","txt":"加工区与境外之间进、出的货物，除实行出口被动配额管理的外，不实行进出口配额、许可证件管理。"},{"i":17,"n":"第十七条","txt":"从境外进入加工区的货物，其进口关税和进口环节税，除法律、法规另有规定外，按照下列规定办理："},{"i":18,"n":"第十八条","txt":"除法律、法规另有规定外，区内企业加工的制成品及其在加工生产过程中产生的边角料、余料、残次品、废品等销往境外的，免征出口关税。"},{"i":19,"n":"第十九条","txt":"对加工区运往区外的货物，海关按照对进口货物的有关规定办理报关手续，并按照制成品征税。如属许可证件管理商品，还应向海关出具有效的进口许可证件。"},{"i":20,"n":"第二十条","txt":"区内企业的加工产品和在加工生产过程中产生的边角料、残次品、废品等应复运出境。因特殊情况需要运往区外时，由企业申请，经主管海关核准后，按内销时的状态确定归类并征税。如属进口许可证件管理商品，免领进口许可证件。如属《限制进口类可用作原料的废物目录》所列商品，应按现行规定向环保部门申领进口许可证件。对无商业价值的边角料和废品，需运往区外销毁的，应凭加工区管理委员会和环保部门的批件，向主管海关办理出区手续，海关予以免进口许可证件、免税。"},{"i":21,"n":"第二十一条","txt":"区内企业在确有需要时，可将有关模具、半成品等运往区外进行加工。经加工区主管海关关长批准，由接受委托的区外企业向加工区主管海关缴纳货物应征关税和进口环节增值税等值保证金或保函后办理出区手续。"},{"i":22,"n":"第二十二条","txt":"区内企业销往区外的机器、设备、模具等，按照国家现行进口政策及有关规定办理。"},{"i":23,"n":"第二十三条","txt":"区内企业经主管海关批准，可在区外进行产品的测试、检验和展示活动。测试、检验和展示的产品，应比照海关对暂时进口货物的管理规定办理出区手续。"},{"i":24,"n":"第二十四条","txt":"区内使用的机器、设备、模具和办公用品等，须运往区外进行维修、测试或检验时，区内企业或管理机构应填写《出口加工区货物运往区外维修查验联系单》，向主管海关提出申请，并经主管海关核准、登记、查验后，方可将机器、设备、模具和办公用品等运往区外维修、测试或检验。"},{"i":25,"n":"第二十五条","txt":"运往区外维修、测试或检验的机器、设备、模具和办公用品等，应自运出之日起2个月内运回加工区。因特殊情况不能如期运回的，区内企业应于期限届满前7天内，向主管海关说明情况，并申请延期。申请延期以1次为限，延长期限不得超过1个月。"},{"i":26,"n":"第二十六条","txt":"运往区外维修的机器、设备、模具和办公用品等，运回区内时，要以海关能辨认其为原物或同一规格的新零件、配件或附件为限，但更换新零件、配件或附件的，原零件、配件或附件应一并运回区内。"},{"i":27,"n":"第二十七条","txt":"从区外进入加工区的货物视同出口，办理出口报关手续。其出口退税，除法律、法规另有规定外，按照以下规定办理："},{"i":28,"n":"第二十八条","txt":"从区外进入加工区的货物、物品，应运入加工区内海关指定仓库或地点，区外企业填写出口报关单，并持境内购货发票、装箱单，向加工区的主管海关办理报关手续。"},{"i":29,"n":"第二十九条","txt":"从区外进入加工区的货物，须经区内企业进行实质性加工后，方可运出境外。"},{"i":30,"n":"第三十条","txt":"区内企业进、出加工区的货物须向其主管海关如实申报，海关依据备案清单及有关单证，对区内企业进、出加工区的货物进行查验、放行和核销。"},{"i":31,"n":"第三十一条","txt":"加工区内的货物可在区内企业之间转让、转移，双方当事人须事先将转让、转移货物的具体品名、数量、金额等有关事项向海关备案。"},{"i":32,"n":"第三十二条","txt":"区内加工企业，不得将未经实质性加工的进口原材料、零部件销往区外。区内从事仓储服务的企业，不得将仓储的原材料、零部件提供给区外企业。"},{"i":33,"n":"第三十三条","txt":"区内企业自开展出口加工业务或仓储业务之日起，每半年持本企业账册和有关单据，向其主管海关办理一次核销手续。"},{"i":34,"n":"第三十四条","txt":"进入加工区的货物，在加工、储存期间，因不可抗力造成短少、损毁的，区内加工企业或仓储企业应自发现之日起10日内报告主管海关，并说明理由。经海关核实确认后，准其在账册内减除。"},{"i":35,"n":"第三十五条","txt":"加工区之间货物的往来，应由收、发货物双方联名向转出区主管海关提出申请。经海关核准后，按照转关运输的有关规定办理。"},{"i":36,"n":"第三十六条","txt":"货物转关至其他加工区时，转入区主管海关在核对封志完整及单货相符后，即予放行入厂或入库。"},{"i":37,"n":"第三十七条","txt":"加工区之间往来的货物不能按照转关运输办理的，转入区主管海关应向收货企业收取货物等值的担保金。货物运抵转入区并经海关核对无误后，主管海关应在10个工作日内，将担保金退还企业。"},{"i":38,"n":"第三十八条","txt":"运输工具和人员应经海关指定的专用通道进、出加工区。"},{"i":39,"n":"第三十九条","txt":"从加工区运往境外的加工产品及由加工区运往区外的货物，经海关查验放行后，应交由经海关核准、并由设立于区内的专营运输企业承运。下列货物经主管海关查验后，可由企业指派专人携带或自行运输："},{"i":40,"n":"第四十条","txt":"进、出加工区货物的运输工具的负责人，应持企业法人营业执照和运输工具的名称、数量、牌照号码及驾驶员姓名等清单，向海关办理登记备案手续。"},{"i":41,"n":"第四十一条","txt":"未经海关批准，从加工区到区外的运输工具和人员不得运输、携带加工区内货物出区。"},{"i":42,"n":"第四十二条","txt":"从境外运入加工区的货物和从加工区运出境外的货物列入进、出口统计。从区外运入加工区和从加工区运往区外的货物，实施单项统计。统计办法由海关总署另行制定。"},{"i":43,"n":"第四十三条","txt":"违反本办法规定的，由海关依照《中华人民共和国海关法》及《中华人民共和国海关行政处罚实施条例》的有关规定进行处理。"},{"i":44,"n":"第四十四条","txt":"本办法自2000年5月24日起施行。"}],"xiaofangjiuyuanxianbiaozhishiyanghepeidaibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国消防救援衔条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"消防救援人员佩带的消防救援衔标志必须与所授予的消防救援衔相符。"},{"i":3,"n":"第三条","txt":"消防救援人员的消防救援衔标志：总监、副总监、助理总监衔标志由金黄色橄榄枝环绕金黄色徽标组成，徽标由五角星、雄鹰翅膀、消防斧和消防水带构成；指挥长、指挥员衔标志由金黄色横杠和金黄色六角星花组成；高级消防员、中级消防员和初级消防员中的三级消防士、四级消防士衔标志由金黄色横杠和金黄色徽标组成，徽标由交叉斧头、水枪、紧握手腕和雄鹰翅膀构成，预备消防士衔标志为金黄色横杠。"},{"i":4,"n":"第四条","txt":"消防救援衔标志佩带在肩章和领章上，肩章分为硬肩章、软肩章和套式肩章，硬肩章、软肩章为剑形，套式肩章、领章为四边形；肩章、领章版面为深火焰蓝色。消防救援人员着春秋常服、冬常服和常服大衣时，佩带硬肩章；着夏常服、棉大衣和作训大衣时，管理指挥人员、专业技术人员佩带软肩章，消防员佩带套式肩章；着作训服时，佩带领章。"},{"i":5,"n":"第五条","txt":"总监衔标志缀钉一枚橄榄枝环绕一周徽标，副总监衔标志缀钉一枚橄榄枝环绕多半周徽标，助理总监衔标志缀钉一枚橄榄枝环绕小半周徽标。"},{"i":6,"n":"第六条","txt":"消防救援人员晋升或者降低消防救援衔时，由批准机关更换其消防救援衔标志；取消消防救援衔的，由批准机关收回其消防救援衔标志。"},{"i":7,"n":"第七条","txt":"消防救援人员的消防救援衔标志由国务院应急管理部门负责制作和管理。其他单位和个人不得制作、仿造、伪造、变造和买卖、使用消防救援衔标志，也不得使用与消防救援衔标志相类似的标志。"},{"i":8,"n":"第八条","txt":"本办法自公布之日起施行。"}],"chuqinyichuanziyuanjinchujingheduiwaihezuoyanjiuli75b94f":[{"i":1,"n":"第一条","txt":"为了加强对畜禽遗传资源进出境和对外合作研究利用的管理，保护和合理利用畜禽遗传资源，防止畜禽遗传资源流失，促进畜牧业持续健康发展，根据《中华人民共和国畜牧法》，制定本办法。"},{"i":2,"n":"第二条","txt":"从境外引进畜禽遗传资源，向境外输出或者在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源，应当遵守《中华人民共和国畜牧法》，并依照本办法的规定办理审批手续。"},{"i":3,"n":"第三条","txt":"本办法所称畜禽，是指列入依照《中华人民共和国畜牧法》第十一条规定公布的畜禽遗传资源目录的畜禽。"},{"i":4,"n":"第四条","txt":"从境外引进畜禽遗传资源，应当具备下列条件："},{"i":5,"n":"第五条","txt":"拟从境外引进畜禽遗传资源的单位，应当向其所在地的省、自治区、直辖市人民政府畜牧兽医行政主管部门提出申请，并提交畜禽遗传资源买卖合同或者赠与协议。"},{"i":6,"n":"第六条","txt":"向境外输出列入畜禽遗传资源保护名录的畜禽遗传资源，应当具备下列条件："},{"i":7,"n":"第七条","txt":"拟向境外输出列入畜禽遗传资源保护名录的畜禽遗传资源的单位，应当向其所在地的省、自治区、直辖市人民政府畜牧兽医行政主管部门提出申请，并提交下列资料："},{"i":8,"n":"第八条","txt":"在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源，应当具备下列条件："},{"i":9,"n":"第九条","txt":"拟在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源的单位，应当向其所在地的省、自治区、直辖市人民政府畜牧兽医行政主管部门提出申请，并提交下列资料："},{"i":10,"n":"第十条","txt":"禁止向境外输出或者在境内与境外机构、个人合作研究利用我国特有的、新发现未经鉴定的畜禽遗传资源以及国务院畜牧兽医行政主管部门禁止出口的其他畜禽遗传资源。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市人民政府畜牧兽医行政主管部门，应当自收到畜禽遗传资源引进、输出或者对外合作研究利用申请之日起20个工作日内完成审核工作，并将审核意见和申请资料报国务院畜牧兽医行政主管部门审批。"},{"i":12,"n":"第十二条","txt":"国务院畜牧兽医行政主管部门，应当自收到畜禽遗传资源引进、输出或者对外合作研究利用审核意见和申请资料之日起20个工作日内，对具备本办法第四条、第六条、第八条规定条件的，签发审批表；对不具备条件的，书面通知申请人，并说明理由。其中，对输出或者在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源，或者首次引进畜禽遗传资源的，国务院畜牧兽医行政主管部门应当自收到审核意见和申请资料之日起3个工作日内，将审核意见和申请资料送国家畜禽遗传资源委员会评估或者评审。评估或者评审时间不计入审批期限。"},{"i":13,"n":"第十三条","txt":"国务院畜牧兽医行政主管部门在20个工作日内不能做出审批决定的，经本部门负责人批准，可以延长10个工作日。延长期限的理由应当告知申请人。"},{"i":14,"n":"第十四条","txt":"畜禽遗传资源引进、输出审批表的有效期为6个月；需要延续的，申请人应当在有效期届满10个工作日前向原审批机关申请延续。延续期不得超过3个月。"},{"i":15,"n":"第十五条","txt":"从境外引进畜禽遗传资源、向境外输出列入畜禽遗传资源保护名录的畜禽遗传资源的单位，凭审批表办理检疫手续。海关凭出入境检验检疫部门出具的进出境货物通关单办理验放手续。从境外引进畜禽遗传资源、向境外输出列入畜禽遗传资源保护名录的畜禽遗传资源的单位，应当自海关放行之日起10个工作日内，将实际引进、输出畜禽遗传资源的数量报国务院畜牧兽医行政主管部门备案。国务院畜牧兽医行政主管部门应当定期将有关资料抄送国务院环境保护行政主管部门。"},{"i":16,"n":"第十六条","txt":"在对外合作研究利用过程中需要更改研究目的和范围、合作期限、知识产权归属、研究成果共享方案或者国家共享惠益方案的，在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源的单位，应当按照原申请程序重新办理审批手续。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市人民政府畜牧兽医行政主管部门应当对引进的畜禽遗传资源进行跟踪评价，组织专家对引进的畜禽遗传资源的生产性能、健康状况、适应性以及对生态环境和本地畜禽遗传资源的影响等进行测定、评估，并及时将测定、评估结果报国务院畜牧兽医行政主管部门。"},{"i":18,"n":"第十八条","txt":"在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源的单位，应当于每年12月31日前，将合作研究利用畜禽遗传资源的情况报所在地的省、自治区、直辖市人民政府畜牧兽医行政主管部门。省、自治区、直辖市人民政府畜牧兽医行政主管部门应当对合作研究利用情况提出审核意见，一并报国务院畜牧兽医行政主管部门备案。"},{"i":19,"n":"第十九条","txt":"与畜禽遗传资源引进、输出和对外合作研究利用的单位以及与境外机构或者个人有利害关系的人员，不得参与对有关申请的评估、评审以及对进境畜禽遗传资源的测定、评估工作。"},{"i":20,"n":"第二十条","txt":"我国的畜禽遗传资源信息，包括重要的畜禽遗传家系和特定地区遗传资源及其数据、资料、样本等，未经国务院畜牧兽医行政主管部门许可，任何单位或者个人不得向境外机构和个人转让。"},{"i":21,"n":"第二十一条","txt":"畜牧兽医行政主管部门工作人员在畜禽遗传资源引进、输出和对外合作研究利用审批过程中玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"依照本办法的规定参与评估、评审、测定的专家，利用职务上的便利收取他人财物或者谋取其他利益，或者出具虚假意见的，没收违法所得，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"申请从境外引进畜禽遗传资源，向境外输出或者在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源的单位，隐瞒有关情况或者提供虚假资料的，由省、自治区、直辖市人民政府畜牧兽医行政主管部门给予警告，3年内不再受理该单位的同类申请。"},{"i":24,"n":"第二十四条","txt":"以欺骗、贿赂等不正当手段取得批准从境外引进畜禽遗传资源，向境外输出或者在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源的，由国务院畜牧兽医行政主管部门撤销批准决定，没收有关畜禽遗传资源和违法所得，并处以1万元以上5万元以下罚款，10年内不再受理该单位的同类申请；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"未经审核批准，从境外引进畜禽遗传资源，或者在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源，或者在境内与境外机构、个人合作研究利用未经国家畜禽遗传资源委员会鉴定的新发现的畜禽遗传资源的，依照《中华人民共和国畜牧法》的有关规定追究法律责任。"},{"i":26,"n":"第二十六条","txt":"未经审核批准，向境外输出列入畜禽遗传资源保护名录的畜禽遗传资源的，依照《中华人民共和国海关法》的有关规定追究法律责任。海关应当将扣留的畜禽遗传资源移送省、自治区、直辖市人民政府畜牧兽医行政主管部门处理。"},{"i":27,"n":"第二十七条","txt":"向境外输出或者在境内与境外机构、个人合作研究利用列入畜禽遗传资源保护名录的畜禽遗传资源，违反国家保密规定的，依照《中华人民共和国保守国家秘密法》的有关规定追究法律责任。"},{"i":28,"n":"第二十八条","txt":"本办法自2008年10月1日起施行。"}],"hongshizibiaozhishiyongbanfa":[{"i":1,"n":"第一条","txt":"为了维护红十字标志的严肃性，正确使用红十字标志，依照红十字会法的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"红十字标志是白底红十字。"},{"i":3,"n":"第三条","txt":"红十字标志是国际人道主义保护标志，是武装力量医疗机构的特定标志，是红十字会的专用标志。"},{"i":4,"n":"第四条","txt":"红十字标志具有保护作用和标明作用，二者不得混淆使用。"},{"i":5,"n":"第五条","txt":"地方各级人民政府依照本办法对本行政区域内红十字标志的使用实施监督管理。"},{"i":6,"n":"第六条","txt":"红十字标志的保护性使用，是指在武装冲突中，冲突各方对依照本办法的规定佩带红十字标志的人员和标有红十字标志的处所及其物品、医务运输工具，必须予以保护和尊重。"},{"i":7,"n":"第七条","txt":"红十字作为保护性标志使用时，不得在标志上添加任何内容。"},{"i":8,"n":"第八条","txt":"在武装冲突中，下列人员可以使用保护性红十字标志："},{"i":9,"n":"第九条","txt":"在武装冲突中，下列机构或者组织及其处所、物品、医务运输工具可以使用保护性红十字标志："},{"i":10,"n":"第十条","txt":"使用保护性红十字标志的人员，必须随身携带由国务院或者中央军事委员会授权的部门签发的身份证明。"},{"i":11,"n":"第十一条","txt":"武装力量医疗机构的人员、处所及其物品、医务运输工具，和平时期可以使用保护性红十字标志作为标记。"},{"i":12,"n":"第十二条","txt":"红十字标志的标明性使用，是指对与红十字活动有关的人或者物的标示。"},{"i":13,"n":"第十三条","txt":"红十字作为标明性标志使用时，在红十字下方必须伴以红十字会的名称或者名称缩写，并不得将红十字置于建筑物顶部。"},{"i":14,"n":"第十四条","txt":"下列人员可以使用标明性红十字标志："},{"i":15,"n":"第十五条","txt":"下列场所可以使用标明性红十字标志："},{"i":16,"n":"第十六条","txt":"下列物品、运输工具可以使用标明性红十字标志："},{"i":17,"n":"第十七条","txt":"在本办法规定的范围以外需要使用标明性红十字标志的，由红十字会总会批准。"},{"i":18,"n":"第十八条","txt":"红十字标志不得用于："},{"i":19,"n":"第十九条","txt":"对违反本办法的规定，有下列情形之一的，红十字会有权予以劝阻，并要求其停止使用；拒绝停止使用的，红十字会可以提请人民政府责令停止使用："},{"i":20,"n":"第二十条","txt":"违反本办法第十八条的规定，擅自使用红十字标志的，由县级以上人民政府责令停止使用，没收非法所得，并处1万元以下的罚款。"},{"i":21,"n":"第二十一条","txt":"阻碍红十字会工作人员依法履行职责的，依法给予治安管理处罚或者追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"武装力量中的组织和人员有违反本办法规定行为的，由军队有关部门处理。"},{"i":23,"n":"第二十三条","txt":"本办法有关红十字标志保护性使用的规定未尽事宜，依照日内瓦公约及其附加议定书的有关规定执行。"},{"i":24,"n":"第二十四条","txt":"本办法自发布之日起施行。"}],"kaogushewaigongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强考古涉外工作管理，保护我国的古代文化遗产，促进我国与外国的考古学术交流，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中国境内陆地、内水和领海以及由中国管辖的其他海域，中国有关单位（以下简称中方）同外国组织和国际组织（以下简称外方）所进行的考古调查、勘探、发掘和与之有关的研究、科技保护及其他活动。"},{"i":3,"n":"第三条","txt":"任何外国组织、国际组织在中国境内进行考古调查、勘探、发掘，都应当采取与中国合作的形式。"},{"i":4,"n":"第四条","txt":"国家文物局统一管理全国考古涉外工作。"},{"i":5,"n":"第五条","txt":"本办法下列用语的含义是："},{"i":6,"n":"第六条","txt":"中外合作进行考古调查、勘探、发掘活动，应当遵守下列原则："},{"i":7,"n":"第七条","txt":"外方申请与中方合作进行考古调查、勘探、发掘时，应当按照下列规定向国家文物局提出书面申请："},{"i":8,"n":"第八条","txt":"申请合作考古调查、勘探、发掘的项目应当同时具备下列条件："},{"i":9,"n":"第九条","txt":"国家文物局会同中国社会科学院对外方的申请进行初步审查后，由国家文物局按照国家有关规定送请国防、外交、公安、国家安全等有关部门审查，经审查合格的，由国家文物局报请国务院特别许可。"},{"i":10,"n":"第十条","txt":"合作考古调查、勘探、发掘项目获得国务院特别许可的，合作双方应当就批准的合作项目的具体事宜签订协议书。"},{"i":11,"n":"第十一条","txt":"合作考古调查、勘探、发掘的文物或者自然标本需要送到中国境外进行分析化验或者技术鉴定的，应当报经国家文物局批准。化验、鉴定完毕后，除测试损耗外，原标本应当全部运回中国境内。"},{"i":12,"n":"第十二条","txt":"外国留学人员（含本科生、研究生和进修生）以及外国研究学者在中国学习、研究考古学的批准期限在1年以上者，可以随同学习所在单位参加中方单独或者中外合作进行的考古调查、勘探、发掘活动。但须由其学习、研究所在单位征得考古调查、勘探、发掘单位的同意后，报国家文物局批准。"},{"i":13,"n":"第十三条","txt":"外国公民、外国组织和国际组织在中国境内参观尚未公开接待参观者的文物点，在开放地区的，需由文物点所在地的管理单位或者接待参观者的中央国家机关及其直属单位，在参观一个月以前向文物点所在地的省、自治区、直辖市人民政府文物行政管理部门申报参观计划，经批准后方可进行；在未开放地区的，需由文物点所在地的管理单位或者接待参观者的中央国家机关及其直属单位，在参观一个月以前向文物点所在地的省、自治区、直辖市人民政府文物行政管理部门申报参观计划，经批准并按照有关涉外工作管理规定向有关部门办理手续后方可进行。"},{"i":14,"n":"第十四条","txt":"国家文物局可以对合作考古调查、勘探、发掘工作实施检查，对工作质量达不到《田野考古工作规程》或者其他有关技术规范的要求的，责令暂停作业，限期改正。"},{"i":15,"n":"第十五条","txt":"违反本办法第六条、第七条、第八条、第十条、第十一条的规定，根据情节轻重，由国家文物局给予警告、暂停作业、撤销项目、罚款1000元至1万元、没收其非法所得文物或者责令赔偿损失。"},{"i":16,"n":"第十六条","txt":"违反本办法第十二条的规定，擅自接收外国留学人员、研究学者参加考古调查、勘探、发掘活动或者延长其工作期限的，国家文物局可以给予警告或者暂停该接收单位的团体考古发掘资格。"},{"i":17,"n":"第十七条","txt":"外国公民、外国组织和国际组织违反本办法第十三条的规定，擅自参观文物点或者擅自收集文物、自然标本、进行考古记录的，文物行政管理部门可以停止其参观，没收其收集的文物、自然标本和考古记录。"},{"i":18,"n":"第十八条","txt":"违反本办法的规定，构成违反治安管理的，依照《中华人民共和国治安管理处罚法》的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"台湾、香港、澳门地区的考古团体与大陆合作进行考古调查、勘探、发掘，可以参照本办法执行。"},{"i":20,"n":"第二十条","txt":"文物研究、科技保护涉外工作的管理办法，由国家文物局根据本办法的原则制定。"},{"i":21,"n":"第二十一条","txt":"本办法由国家文物局负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自发布之日起施行。"}],"jinkoujiliangqijujianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强进口计量器具的监督管理，根据《中华人民共和国计量法》和《中华人民共和国计量法实施细则》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"任何单位和个人进口计量器具，以及外商（含外国制造商、经销商，下同）或其代理人在中国销售计量器具，都必须遵守本办法。"},{"i":3,"n":"第三条","txt":"进口计量器具的监督管理，由国务院计量行政部门主管，具体实施由国务院和地方有关部门分工负责。"},{"i":4,"n":"第四条","txt":"凡进口或外商在中国境内销售列入本办法所附《中华人民共和国进口计量器具型式审查目录》内的计量器具的，应向国务院计量行政部门申请办理型式批准。"},{"i":5,"n":"第五条","txt":"外商或其代理人申请型式批准，须向国务院计量行政部门递交型式批准申请书、计量器具样机照片和必要的技术资料。"},{"i":6,"n":"第六条","txt":"国务院计量行政部门接受申请后，负责安排授权的技术机构进行定型鉴定，并通知外商或其代理人向承担定型鉴定的技术机构提供样机和以下技术资料："},{"i":7,"n":"第七条","txt":"定型鉴定按鉴定大纲进行。鉴定大纲由承担鉴定的技术机构，根据国务院计量行政部门发布的《计量器具定型鉴定技术规范》的要求制定。主要内容包括：外观检查、计量性能考核以及安全性、环境适应性、可靠性和寿命试验等。"},{"i":8,"n":"第八条","txt":"定型鉴定的结果由承担鉴定的技术机构报国务院计量行政部门审核。经审核合格的，由国务院计量行政部门向申请人颁发《中华人民共和国进口计量器具型式批准证书》，并准予在相应的计量器具和包装上使用中华人民共和国进口计量器具型式批准的标志和编号。"},{"i":9,"n":"第九条","txt":"承担定型鉴定的技术机构及其工作人员，对申请人提供的技术资料必须保密。"},{"i":10,"n":"第十条","txt":"有下列情况之一的，经国务院计量行政部门同意，可申请办理临时型式批准，具体办法由国务院计量行政部门规定："},{"i":11,"n":"第十一条","txt":"外国制造的计量器具经我国型式批准后，由国务院计量行政部门予以公布。"},{"i":12,"n":"第十二条","txt":"申请进口计量器具，按国家关于进口商品的规定程序进行审批。"},{"i":13,"n":"第十三条","txt":"因特殊需要，申请进口非法定计量单位的计量器具和国务院禁止使用的其他计量器具，须经省、自治区、直辖市人民政府计量行政部门批准。"},{"i":14,"n":"第十四条","txt":"申请进口非法定计量单位的计量器具和国务院禁止使用的其他计量器具的单位，应向省、自治区、直辖市人民政府计量行政部门提供以下材料和文件："},{"i":15,"n":"第十五条","txt":"违反本办法规定，进口非法定计量单位的计量器具或国务院禁止使用的其他计量器具的，按照《中华人民共和国计量法实施细则》第四十四条规定追究法律责任。"},{"i":16,"n":"第十六条","txt":"违反本办法第四条规定，进口或销售未经国务院计量行政部门型式批准的计量器具的，计量行政部门有权封存其计量器具，责令其补办型式批准手续，并可处以相当于进口或销售额百分之三十以下的罚款。"},{"i":17,"n":"第十七条","txt":"承担进口计量器具定型鉴定的技术机构违反本办法第九条规定的，按照《中华人民共和国计量法实施细则》第五十八条规定追究法律责任。"},{"i":18,"n":"第十八条","txt":"引进成套设备中配套的计量器具以及不以销售为目的的计量器具的监督管理，按国家有关规定办理。"},{"i":19,"n":"第十九条","txt":"与本办法有关的申请书、证书和标志式样，由国务院计量行政部门统一制定。"},{"i":20,"n":"第二十条","txt":"申请进口计量器具的型式批准和定型鉴定，应按国家有关规定缴纳费用。"},{"i":21,"n":"第二十一条","txt":"进口用于统一量值的标准物质的监督管理，可参照本办法执行。"},{"i":22,"n":"第二十二条","txt":"本办法由国务院计量行政部门负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自发布之日起施行。"}],"zhongguorenminwuzhuangjingchabuduishixingjingguanj22bdff":[],"zhongguogongminchuguolvyouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范旅行社组织中国公民出国旅游活动，保障出国旅游者和出国旅游经营者的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"出国旅游的目的地国家，由国务院旅游行政部门会同国务院有关部门提出，报国务院批准后，由国务院旅游行政部门公布。"},{"i":3,"n":"第三条","txt":"旅行社经营出国旅游业务，应当具备下列条件："},{"i":4,"n":"第四条","txt":"申请经营出国旅游业务的旅行社，应当向省、自治区、直辖市旅游行政部门提出申请。省、自治区、直辖市旅游行政部门应当自受理申请之日起30个工作日内，依据本办法第三条规定的条件对申请审查完毕，经审查同意的，报国务院旅游行政部门批准；经审查不同意的，应当书面通知申请人并说明理由。"},{"i":5,"n":"第五条","txt":"国务院旅游行政部门应当将取得出国旅游业务经营资格的旅行社（以下简称组团社）名单予以公布，并通报国务院有关部门。"},{"i":6,"n":"第六条","txt":"国务院旅游行政部门根据上年度全国入境旅游的业绩、出国旅游目的地的增加情况和出国旅游的发展趋势，在每年的2月底以前确定本年度组织出国旅游的人数安排总量，并下达省、自治区、直辖市旅游行政部门。"},{"i":7,"n":"第七条","txt":"国务院旅游行政部门统一印制《中国公民出国旅游团队名单表》（以下简称《名单表》），在下达本年度出国旅游人数安排时编号发放给省、自治区、直辖市旅游行政部门，由省、自治区、直辖市旅游行政部门核发给组团社。"},{"i":8,"n":"第八条","txt":"《名单表》一式四联，分为：出境边防检查专用联、入境边防检查专用联、旅游行政部门审验专用联、旅行社自留专用联。"},{"i":9,"n":"第九条","txt":"旅游者持有有效普通护照的，可以直接到组团社办理出国旅游手续；没有有效普通护照的，应当依照《中华人民共和国公民出境入境管理法》的有关规定办理护照后再办理出国旅游手续。"},{"i":10,"n":"第十条","txt":"组团社应当为旅游团队安排专职领队。"},{"i":11,"n":"第十一条","txt":"旅游团队应当从国家开放口岸整团出入境。"},{"i":12,"n":"第十二条","txt":"组团社应当维护旅游者的合法权益。"},{"i":13,"n":"第十三条","txt":"组团社经营出国旅游业务，应当与旅游者订立书面旅游合同。"},{"i":14,"n":"第十四条","txt":"组团社应当按照旅游合同约定的条件，为旅游者提供服务。"},{"i":15,"n":"第十五条","txt":"组团社组织旅游者出国旅游，应当选择在目的地国家依法设立并具有良好信誉的旅行社（以下简称境外接待社），并与之订立书面合同后，方可委托其承担接待工作。"},{"i":16,"n":"第十六条","txt":"组团社及其旅游团队领队应当要求境外接待社按照约定的团队活动计划安排旅游活动，并要求其不得组织旅游者参与涉及色情、赌博、毒品内容的活动或者危险性活动，不得擅自改变行程、减少旅游项目，不得强迫或者变相强迫旅游者参加额外付费项目。"},{"i":17,"n":"第十七条","txt":"旅游团队领队应当向旅游者介绍旅游目的地国家的相关法律、风俗习惯以及其他有关注意事项，并尊重旅游者的人格尊严、宗教信仰、民族风俗和生活习惯。"},{"i":18,"n":"第十八条","txt":"旅游团队领队在带领旅游者旅行、游览过程中，应当就可能危及旅游者人身安全的情况，向旅游者作出真实说明和明确警示，并按照组团社的要求采取有效措施，防止危害的发生。"},{"i":19,"n":"第十九条","txt":"旅游团队在境外遇到特殊困难和安全问题时，领队应当及时向组团社和中国驻所在国家使领馆报告；组团社应当及时向旅游行政部门和公安机关报告。"},{"i":20,"n":"第二十条","txt":"旅游团队领队不得与境外接待社、导游及为旅游者提供商品或者服务的其他经营者串通欺骗、胁迫旅游者消费，不得向境外接待社、导游及其他为旅游者提供商品或者服务的经营者索要回扣、提成或者收受其财物。"},{"i":21,"n":"第二十一条","txt":"旅游者应当遵守旅游目的地国家的法律，尊重当地的风俗习惯，并服从旅游团队领队的统一管理。"},{"i":22,"n":"第二十二条","txt":"严禁旅游者在境外滞留不归。"},{"i":23,"n":"第二十三条","txt":"旅游者对组团社或者旅游团队领队违反本办法规定的行为，有权向旅游行政部门投诉。"},{"i":24,"n":"第二十四条","txt":"因组团社或者其委托的境外接待社违约，使旅游者合法权益受到损害的，组团社应当依法对旅游者承担赔偿责任。"},{"i":25,"n":"第二十五条","txt":"组团社有下列情形之一的，旅游行政部门可以暂停其经营出国旅游业务；情节严重的，取消其出国旅游业务经营资格："},{"i":26,"n":"第二十六条","txt":"任何单位和个人违反本办法第四条的规定，未经批准擅自经营或者以商务、考察、培训等方式变相经营出国旅游业务的，由旅游行政部门责令停止非法经营，没收违法所得，并处违法所得2倍以上5倍以下的罚款。"},{"i":27,"n":"第二十七条","txt":"组团社违反本办法第十条的规定，不为旅游团队安排专职领队的，由旅游行政部门责令改正，并处5000元以上2万元以下的罚款，可以暂停其出国旅游业务经营资格；多次不安排专职领队的，并取消其出国旅游业务经营资格。"},{"i":28,"n":"第二十八条","txt":"组团社违反本办法第十二条的规定，向旅游者提供虚假服务信息或者低于成本报价的，由工商行政管理部门依照《中华人民共和国消费者权益保护法》、《中华人民共和国反不正当竞争法》的有关规定给予处罚。"},{"i":29,"n":"第二十九条","txt":"组团社或者旅游团队领队违反本办法第十四条第二款、第十八条的规定，对可能危及人身安全的情况未向旅游者作出真实说明和明确警示，或者未采取防止危害发生的措施的，由旅游行政部门责令改正，给予警告；情节严重的，对组团社暂停其出国旅游业务经营资格，并处5000元以上2万元以下的罚款，对旅游团队领队可以暂扣直至吊销其导游证；造成人身伤亡事故的，依法追究刑事责任，并承担赔偿责任。"},{"i":30,"n":"第三十条","txt":"组团社或者旅游团队领队违反本办法第十六条的规定，未要求境外接待社不得组织旅游者参与涉及色情、赌博、毒品内容的活动或者危险性活动，未要求其不得擅自改变行程、减少旅游项目、强迫或者变相强迫旅游者参加额外付费项目，或者在境外接待社违反前述要求时未制止的，由旅游行政部门对组团社处组织该旅游团队所收取费用2倍以上5倍以下的罚款，并暂停其出国旅游业务经营资格，对旅游团队领队暂扣其导游证；造成恶劣影响的，对组团社取消其出国旅游业务经营资格，对旅游团队领队吊销其导游证。"},{"i":31,"n":"第三十一条","txt":"旅游团队领队违反本办法第二十条的规定，与境外接待社、导游及为旅游者提供商品或者服务的其他经营者串通欺骗、胁迫旅游者消费或者向境外接待社、导游和其他为旅游者提供商品或者服务的经营者索要回扣、提成或者收受其财物的，由旅游行政部门责令改正，没收索要的回扣、提成或者收受的财物，并处索要的回扣、提成或者收受的财物价值2倍以上5倍以下的罚款；情节严重的，并吊销其导游证。"},{"i":32,"n":"第三十二条","txt":"违反本办法第二十二条的规定，旅游者在境外滞留不归，旅游团队领队不及时向组团社和中国驻所在国家使领馆报告，或者组团社不及时向有关部门报告的，由旅游行政部门给予警告，对旅游团队领队可以暂扣其导游证，对组团社可以暂停其出国旅游业务经营资格。"},{"i":33,"n":"第三十三条","txt":"本办法自2002年7月1日起施行。国务院1997年3月17日批准，国家旅游局、公安部1997年7月1日发布的《中国公民自费出国旅游管理暂行办法》同时废止。"}],"zhongguogongminyinsishiwanglaixianggangdiquhuozheaa22338":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国公民出境入境管理法》第十七条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于内地公民因私事往来香港地区（下称香港）或者澳门地区（下称澳门）以及港澳同胞来往内地。"},{"i":3,"n":"第三条","txt":"内地公民因私事前往香港、澳门，凭我国公安机关签发的前往港澳通行证或者往来港澳通行证从指定的口岸通行；返回内地也可以从其他对外开放的口岸通行。"},{"i":4,"n":"第四条","txt":"港澳同胞来往于香港、澳门与内地之间，凭我国公安机关签发的港澳同胞回乡证或者入出境通行证，从中国对外开放的口岸通行。"},{"i":5,"n":"第五条","txt":"内地公民因私事前往香港、澳门定居，实行定额审批的办法，以利于维护和保持香港和澳门的经济繁荣和社会稳定。"},{"i":6,"n":"第六条","txt":"内地公民因私事前往香港、澳门，须向户口所在地的市、县公安局出入境管理部门提出申请。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，可以申请前往香港、澳门定居："},{"i":8,"n":"第八条","txt":"有下列情形之一的，可以申请短期前往香港、澳门："},{"i":9,"n":"第九条","txt":"内地公民因私事申请前往香港、澳门，须回答有关的询问并履行下列手续："},{"i":10,"n":"第十条","txt":"本办法第九条第四项所称的证明是指："},{"i":11,"n":"第十一条","txt":"公安机关出入境管理部门受理的前往香港、澳门的申请，应当在六十天内作出批准或者不批准的决定，通知申请人。"},{"i":12,"n":"第十二条","txt":"经批准前往香港、澳门定居的内地公民，由公安机关出入境管理部门发给前往港澳通行证。持证人应当在前往香港、澳门之前，到所在地公安派出所注销户口，并在规定的时间内前往香港、澳门。"},{"i":13,"n":"第十三条","txt":"内地公民申请去香港、澳门，有下列情形之一的，不予批准："},{"i":14,"n":"第十四条","txt":"港澳同胞来内地，须申请领取港澳同胞回乡证。港澳同胞回乡证由广东省公安厅签发。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不发给港澳同胞回乡证或者入出境通行证："},{"i":16,"n":"第十六条","txt":"港澳同胞驾驶机动车辆来内地，应当按照广东省人民政府有关规定申请行车执照，驾驶人员还须向广东省公安厅出入境管理处申请驾驶港澳机动车辆来往内地的许可。"},{"i":17,"n":"第十七条","txt":"港澳同胞短期来内地，要按照户口管理规定，办理暂住登记。在宾馆、饭店、旅店、招待所、学校等企业、事业单位或者机关、团体及其他机构内住宿的，应当填写临时住宿登记表；住在亲友家的，由本人或者亲友在二十四小时内（农村可在七十二小时内）到住地公安派出所或者户籍办公室办理暂住登记。"},{"i":18,"n":"第十八条","txt":"港澳同胞要求回内地定居的，应当事先向拟定居地的市、县公安局提出申请，获准后，持注有回乡定居签注的港澳同胞回乡证，至定居地办理常住户口手续。"},{"i":19,"n":"第十九条","txt":"内地公民往来香港、澳门以及港澳同胞来往内地，须向对外开放口岸或者指定口岸的边防检查站出示出入境证件，填交出境、入境登记卡，接受查验。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，边防检查站有权阻止出境、入境："},{"i":21,"n":"第二十一条","txt":"港澳同胞回乡证由持证人保存，有效期十年，在有效期内可以多次使用。超过有效期或者查验页用完的，可以换领新证。申请新证按照本办法第十四条规定办理。"},{"i":22,"n":"第二十二条","txt":"前往港澳通行证在有效期内一次使用有效。往来港澳通行证有效期五年，可以延期二次，每次不超过五年，证件由持证人保存、使用，每次前往香港、澳门均须按照本办法第六条、第八条、第十条的规定办理申请手续，经批准的作一次往返签注。经公安部特别授权的公安机关可以作多次往返签注。"},{"i":23,"n":"第二十三条","txt":"港澳同胞来内地后遗失港澳同胞回乡证，应向遗失地的市、县或者交通运输部门的公安机关报失，经公安机关调查属实，出具证明，由公安机关出入境管理部门签发一次有效的入出境通行证，凭证返回香港、澳门。港澳同胞无论在香港、澳门或者内地遗失港澳同胞回乡证，均可以按照本办法第十四条规定重新申请领取港澳同胞回乡证。"},{"i":24,"n":"第二十四条","txt":"内地公民在前往香港、澳门之前遗失前往港澳通行证、往来港澳通行证的，应立即报告原发证机关，并由本人登报声明，经调查属实的，重新发给证件。"},{"i":25,"n":"第二十五条","txt":"港澳同胞回乡证持证人有本办法第十五条规定情形之一的，证件应予以吊销。"},{"i":26,"n":"第二十六条","txt":"持用伪造、涂改等无效的或者冒用他人的前往港澳通行证、往来港澳通行证、港澳同胞回乡证、入出境通行证的，除可以没收证件外，并视情节轻重，处以警告或五日以下拘留。"},{"i":27,"n":"第二十七条","txt":"伪造、涂改、转让前往港澳通行证、往来港澳通行证、港澳同胞回乡证、入出境通行证的，处十日以下拘留；情节严重，构成犯罪的，依照《中华人民共和国刑法》的有关条款的规定追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"编造情况，提供假证明，或者以行贿等手段，获取前往港澳通行证、往来港澳通行证、港澳同胞回乡证、入出境通行证，情节较轻的，处以警告或五日以下拘留；情节严重，构成犯罪的，依照《中华人民共和国刑法》的有关条款的规定追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"公安机关的工作人员在执行本办法时，如有利用职权索取、收受贿赂或者有其他违法失职行为，情节轻微的，可以由主管部门酌情予以行政处分；情节严重，构成犯罪的，依照《中华人民共和国刑法》的有关条款的规定追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本办法由公安部组织实施，负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自公布之日起施行。"}],"zhongguogongminwanglaitaiwandiquguanlibanfa":[{"i":1,"n":"第一条","txt":"为保障台湾海峡两岸人员往来，促进各方交流，维护社会秩序，制定本办法。"},{"i":2,"n":"第二条","txt":"居住在大陆的中国公民（以下简称大陆居民）往来台湾地区（以下简称台湾）以及居住在台湾地区的中国公民（以下简称台湾居民）来往大陆，适用本办法。"},{"i":3,"n":"第三条","txt":"大陆居民前往台湾，凭公安机关出入境管理部门签发的旅行证件，从开放的或者指定的出入境口岸通行。"},{"i":4,"n":"第四条","txt":"台湾居民来大陆，凭国家主管机关签发的旅行证件，从开放的或者指定的入出境口岸通行。"},{"i":5,"n":"第五条","txt":"中国公民往来台湾与大陆之间，不得有危害国家安全、荣誉和利益的行为。"},{"i":6,"n":"第六条","txt":"大陆居民前往台湾定居、探亲、访友、旅游、接受和处理财产、处理婚丧事宜或者参加经济、科技、文化、教育、体育、学术等活动，须向户口所在地的市、县公安局提出申请。"},{"i":7,"n":"第七条","txt":"大陆居民申请前往台湾，须履行下列手续："},{"i":8,"n":"第八条","txt":"本办法第七条第四项所称的证明是指："},{"i":9,"n":"第九条","txt":"公安机关受理大陆居民前往台湾的申请，应当在30日内，地处偏僻、交通不便的应当在60日内，作出批准或者不予批准的决定，通知申请人。紧急的申请，应当随时办理。"},{"i":10,"n":"第十条","txt":"经批准前往台湾的大陆居民，由公安机关签发或者签注旅行证件。"},{"i":11,"n":"第十一条","txt":"经批准前往台湾的大陆居民，应当在所持旅行证件签注的有效期内前往，除定居的以外，应当按期返回。"},{"i":12,"n":"第十二条","txt":"申请前往台湾的大陆居民有下列情形之一的，不予批准："},{"i":13,"n":"第十三条","txt":"台湾居民要求来大陆的，向下列有关机关申请办理旅行证件："},{"i":14,"n":"第十四条","txt":"台湾居民申请来大陆，须履行下列手续："},{"i":15,"n":"第十五条","txt":"对批准来大陆的台湾居民，由国家主管机关签发旅行证件。"},{"i":16,"n":"第十六条","txt":"台湾居民来大陆，应当按照户口管理规定，办理暂住登记。在宾馆、饭店、招待所、旅店、学校等企业、事业单位或者机关、团体和其他机构内住宿的，应当填写临时住宿登记表；住在亲友家的，由本人或者亲友在24小时（农村72小时）内到当地公安派出所或者户籍办公室办理暂住登记手续。"},{"i":17,"n":"第十七条","txt":"台湾居民要求来大陆定居的，应当在入境前向公安部出入境管理局派出的或者委托的有关机构提出申请，或者经由大陆亲属向拟定居地的市、县公安局提出申请。批准定居的，公安机关发给定居证明。"},{"i":18,"n":"第十八条","txt":"台湾居民来大陆后，应当在所持旅行证件有效期之内按期离境。所持证件有效期即将届满需要继续居留的，应当向市、县公安局申请换发。"},{"i":19,"n":"第十九条","txt":"申请来大陆的台湾居民有下列情形之一的，不予批准："},{"i":20,"n":"第二十条","txt":"大陆居民往来台湾，台湾居民来往大陆，须向开放的或者指定的出入境口岸边防检查站出示证件，填交出境、入境登记卡，接受查验。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，边防检查站有权阻止出境、入境："},{"i":22,"n":"第二十二条","txt":"大陆居民往来台湾的旅行证件系指大陆居民往来台湾通行证和其他有效旅行证件。"},{"i":23,"n":"第二十三条","txt":"台湾居民来往大陆的旅行证件系指台湾居民来往大陆通行证和其他有效旅行证件。"},{"i":24,"n":"第二十四条","txt":"大陆居民往来台湾通行证有效期为10年；台湾居民来往大陆通行证分为5年有效和3个月一次有效两种。"},{"i":25,"n":"第二十五条","txt":"大陆居民往来台湾通行证实行逐次签注。签注分一次往返有效和多次往返有效。"},{"i":26,"n":"第二十六条","txt":"大陆居民遗失旅行证件，应当向原发证的公安机关报失；经调查属实的，可补发给相应的旅行证件。"},{"i":27,"n":"第二十七条","txt":"台湾居民在大陆遗失旅行证件，应当向当地的市、县公安机关报失；经调查属实的，可以允许重新申请领取相应的旅行证件，或者发给一次有效的出境通行证件。"},{"i":28,"n":"第二十八条","txt":"大陆居民前往台湾和台湾居民来大陆旅行证件的持有人，有本办法第十二条、第十九条规定情形之一的，其证件应当予以吊销或者宣布作废。"},{"i":29,"n":"第二十九条","txt":"审批签发旅行证件的机关，对已发出的旅行证件有权吊销或者宣布作废。公安部在必要时，可以变更签注、吊销旅行证件或者宣布作废。"},{"i":30,"n":"第三十条","txt":"持用伪造、涂改等无效的旅行证件或者冒用他人的旅行证件出境、入境的，除依照《中华人民共和国公民出境入境管理法实施细则》第二十三条的规定处罚外，可以单处或者并处100元以上、500元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"伪造、涂改、转让、倒卖旅行证件的，除依照《中华人民共和国公民出境入境管理法实施细则》第二十四条的规定处罚外，可以单处或者并处500元以上、3000元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"编造情况，提供假证明，或者以行贿等手段获取旅行证件的，除依照《中华人民共和国公民出境入境管理法实施细则》第二十五条的规定处罚外，可以单处或者并处100元以上、500元以下的罚款。"},{"i":33,"n":"第三十三条","txt":"机关、团体、企业、事业单位编造情况、出具假证明为申请人获取旅行证件的，暂停其出证权的行使；情节严重的，取消其出证资格；对直接责任人员，除依照《中华人民共和国公民出境入境管理法实施细则》第二十五条的规定处罚外，可以单处或者并处500元以上、1000元以下的罚款。"},{"i":34,"n":"第三十四条","txt":"违反本办法第十六条的规定，不办理暂住登记的，处以警告或者100元以上、500元以下的罚款。"},{"i":35,"n":"第三十五条","txt":"违反本办法第十八条的规定，逾期非法居留的，处以警告，可以单处或者并处每逾期1日100元的罚款。"},{"i":36,"n":"第三十六条","txt":"被处罚人对公安机关处罚不服的，可以在接到处罚通知之日起15日内，向上一级公安机关申请复议，由上一级公安机关作出最后的裁决；也可以直接向人民法院提起诉讼。"},{"i":37,"n":"第三十七条","txt":"来大陆的台湾居民违反本办法的规定或者有其他违法犯罪行为的，除依照本办法和其他有关法律、法规的规定处罚外，公安机关可以缩短其停留期限，限期离境，或者遣送出境。"},{"i":38,"n":"第三十八条","txt":"执行本办法的国家工作人员，利用职权索取、收受贿赂或者有其他违法失职行为，情节轻微的，由主管部门予以行政处分；情节严重，构成犯罪的，依照《中华人民共和国刑法》的有关规定追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"对违反本办法所得的财物，应当予以追缴或者责令退赔；用于犯罪的本人财物应当没收。"},{"i":40,"n":"第四十条","txt":"本办法由公安部负责解释。"},{"i":41,"n":"第四十一条","txt":"本办法自1992年5月1日起施行。"}],"zhongguogongminshouyangzinvdengjibanfa":[{"i":1,"n":"第一条","txt":"为了规范收养登记行为，根据《中华人民共和国民法典》（以下简称民法典），制定本办法。"},{"i":2,"n":"第二条","txt":"中国公民在中国境内收养子女或者协议解除收养关系的，应当依照本办法的规定办理登记。"},{"i":3,"n":"第三条","txt":"收养登记工作应当坚持中国共产党的领导，遵循最有利于被收养人的原则，保障被收养人和收养人的合法权益。"},{"i":4,"n":"第四条","txt":"收养社会福利机构抚养的查找不到生父母的弃婴、儿童和孤儿的，在社会福利机构所在地的收养登记机关办理登记。"},{"i":5,"n":"第五条","txt":"收养关系当事人应当亲自到收养登记机关办理成立收养关系的登记手续。"},{"i":6,"n":"第六条","txt":"收养人应当向收养登记机关提交收养申请书和下列证件、证明材料："},{"i":7,"n":"第七条","txt":"送养人应当向收养登记机关提交下列证件和证明材料："},{"i":8,"n":"第八条","txt":"收养登记机关收到收养登记申请书及有关材料后，应当自次日起30日内进行审查。对符合民法典规定条件的，为当事人办理收养登记，发给收养登记证，收养关系自登记之日起成立；对不符合民法典规定条件的，不予登记，并对当事人说明理由。"},{"i":9,"n":"第九条","txt":"收养关系成立后，需要为被收养人办理户口登记或者迁移手续的，由收养人持收养登记证到户口登记机关按照国家有关规定办理。"},{"i":10,"n":"第十条","txt":"收养关系当事人协议解除收养关系的，应当持居民户口簿、居民身份证、收养登记证和解除收养关系的书面协议，共同到被收养人常住户口所在地的收养登记机关办理解除收养关系登记。"},{"i":11,"n":"第十一条","txt":"收养登记机关收到解除收养关系登记申请书及有关材料后，应当自次日起30日内进行审查；对符合民法典规定的，为当事人办理解除收养关系的登记，收回收养登记证，发给解除收养关系证明。"},{"i":12,"n":"第十二条","txt":"为收养关系当事人出具证明材料的组织，应当如实出具有关证明材料。出具虚假证明材料的，由收养登记机关没收虚假证明材料，并建议有关组织对直接责任人员给予批评教育，或者依法给予行政处分、纪律处分。"},{"i":13,"n":"第十三条","txt":"收养关系当事人弄虚作假骗取收养登记的，收养关系无效，由收养登记机关撤销登记，收缴收养登记证。"},{"i":14,"n":"第十四条","txt":"本办法规定的收养登记证、解除收养关系证明的式样，由国务院民政部门制订。"},{"i":15,"n":"第十五条","txt":"华侨以及居住在香港、澳门、台湾地区的中国公民在内地收养子女的，申请办理收养登记的管辖以及所需要出具的证件和证明材料，按照国务院民政部门的有关规定执行。"},{"i":16,"n":"第十六条","txt":"本办法自发布之日起施行。"}],"hulianwangxinxifuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范互联网信息服务活动，促进互联网信息服务健康有序发展，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事互联网信息服务活动，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"互联网信息服务分为经营性和非经营性两类。"},{"i":4,"n":"第四条","txt":"国家对经营性互联网信息服务实行许可制度；对非经营性互联网信息服务实行备案制度。"},{"i":5,"n":"第五条","txt":"从事新闻、出版、教育等互联网信息服务，依照法律、行政法规以及国家有关规定须经有关主管部门审核同意的，在申请经营许可或者履行备案手续前，应当依法经有关主管部门审核同意。"},{"i":6,"n":"第六条","txt":"从事经营性互联网信息服务，除应当符合《中华人民共和国电信条例》规定的要求外，还应当具备下列条件："},{"i":7,"n":"第七条","txt":"从事经营性互联网信息服务，应当向省、自治区、直辖市电信管理机构或者国务院信息产业主管部门申请办理互联网信息服务增值电信业务经营许可证（以下简称经营许可证）。"},{"i":8,"n":"第八条","txt":"从事非经营性互联网信息服务，应当向省、自治区、直辖市电信管理机构或者国务院信息产业主管部门办理备案手续。办理备案时，应当提交下列材料："},{"i":9,"n":"第九条","txt":"从事互联网信息服务，拟开办电子公告服务的，应当在申请经营性互联网信息服务许可或者办理非经营性互联网信息服务备案时，按照国家有关规定提出专项申请或者专项备案。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市电信管理机构和国务院信息产业主管部门应当公布取得经营许可证或者已履行备案手续的互联网信息服务提供者名单。"},{"i":11,"n":"第十一条","txt":"互联网信息服务提供者应当按照经许可或者备案的项目提供服务，不得超出经许可或者备案的项目提供服务。"},{"i":12,"n":"第十二条","txt":"互联网信息服务提供者应当在其网站主页的显著位置标明其经营许可证编号或者备案编号。"},{"i":13,"n":"第十三条","txt":"互联网信息服务提供者应当向上网用户提供良好的服务，并保证所提供的信息内容合法。"},{"i":14,"n":"第十四条","txt":"从事新闻、出版以及电子公告等服务项目的互联网信息服务提供者，应当记录提供的信息内容及其发布时间、互联网地址或者域名；互联网接入服务提供者应当记录上网用户的上网时间、用户账号、互联网地址或者域名、主叫电话号码等信息。"},{"i":15,"n":"第十五条","txt":"互联网信息服务提供者不得制作、复制、发布、传播含有下列内容的信息："},{"i":16,"n":"第十六条","txt":"互联网信息服务提供者发现其网站传输的信息明显属于本办法第十五条所列内容之一的，应当立即停止传输，保存有关记录，并向国家有关机关报告。"},{"i":17,"n":"第十七条","txt":"经营性互联网信息服务提供者申请在境内境外上市或者同外商合资、合作，应当事先经国务院信息产业主管部门审查同意；其中，外商投资的比例应当符合有关法律、行政法规的规定。"},{"i":18,"n":"第十八条","txt":"国务院信息产业主管部门和省、自治区、直辖市电信管理机构，依法对互联网信息服务实施监督管理。"},{"i":19,"n":"第十九条","txt":"违反本办法的规定，未取得经营许可证，擅自从事经营性互联网信息服务，或者超出许可的项目提供服务的，由省、自治区、直辖市电信管理机构责令限期改正，有违法所得的，没收违法所得，处违法所得3倍以上5倍以下的罚款；没有违法所得或者违法所得不足5万元的，处10万元以上100万元以下的罚款；情节严重的，责令关闭网站。"},{"i":20,"n":"第二十条","txt":"制作、复制、发布、传播本办法第十五条所列内容之一的信息，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关、国家安全机关依照《中华人民共和国治安管理处罚法》、《计算机信息网络国际联网安全保护管理办法》等有关法律、行政法规的规定予以处罚；对经营性互联网信息服务提供者，并由发证机关责令停业整顿直至吊销经营许可证，通知企业登记机关；对非经营性互联网信息服务提供者，并由备案机关责令暂时关闭网站直至关闭网站。"},{"i":21,"n":"第二十一条","txt":"未履行本办法第十四条规定的义务的，由省、自治区、直辖市电信管理机构责令改正；情节严重的，责令停业整顿或者暂时关闭网站。"},{"i":22,"n":"第二十二条","txt":"违反本办法的规定，未在其网站主页上标明其经营许可证编号或者备案编号的，由省、自治区、直辖市电信管理机构责令改正，处5000元以上5万元以下的罚款。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十六条规定的义务的，由省、自治区、直辖市电信管理机构责令改正；情节严重的，对经营性互联网信息服务提供者，并由发证机关吊销经营许可证，对非经营性互联网信息服务提供者，并由备案机关责令关闭网站。"},{"i":24,"n":"第二十四条","txt":"互联网信息服务提供者在其业务活动中，违反其他法律、法规的，由新闻、出版、教育、卫生、药品监督管理和工商行政管理等有关主管部门依照有关法律、法规的规定处罚。"},{"i":25,"n":"第二十五条","txt":"电信管理机构和其他有关主管部门及其工作人员，玩忽职守、滥用职权、徇私舞弊，疏于对互联网信息服务的监督管理，造成严重后果，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对直接负责的主管人员和其他直接责任人员依法给予降级、撤职直至开除的行政处分。"},{"i":26,"n":"第二十六条","txt":"在本办法公布前从事互联网信息服务的，应当自本办法公布之日起60日内依照本办法的有关规定补办有关手续。"},{"i":27,"n":"第二十七条","txt":"本办法自公布之日起施行。"}],"renminjingchajingxianbiaozhishiyanghepeidaibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国人民警察警衔条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"人民警察佩带的警衔标志必须与所授予的警衔相符。"},{"i":3,"n":"第三条","txt":"人民警察的警衔标志：总警监、副总警监警衔标志由银色橄榄枝环绕银色国徽组成，警监警衔标志由银色橄榄枝和银色四角星花组成，警督、警司警衔标志由银色横杠和银色四角星花组成，警员警衔标志由银色四角星花组成。"},{"i":4,"n":"第四条","txt":"警衔标志佩带在肩章上，肩章为剑形，分为硬肩章和软肩章。担任行政职务的人民警察的肩章版面为藏蓝色，担任专业技术职务的人民警察的肩章版面为蓝灰色。"},{"i":5,"n":"第五条","txt":"总警监警衔标志缀钉一枚橄榄枝环绕一周的国徽，副总警监警衔标志缀钉一枚橄榄枝环绕半周的国徽。"},{"i":6,"n":"第六条","txt":"担任专业技术职务的人民警察警衔标志的缀钉、佩带办法与担任行政职务的相同衔级的人民警察相同。"},{"i":7,"n":"第七条","txt":"人民警察晋升或者降低警衔时，由批准机关更换其警衔标志；取消警衔的，由批准机关收回其警衔标志。"},{"i":8,"n":"第八条","txt":"人民警察的警衔标志由公安部负责制作和管理。其他单位和个人不得制作、仿造、伪造和买卖、使用警衔标志，也不得使用与警衔标志相类似的标志。"},{"i":9,"n":"第九条","txt":"本办法由公安部负责解释。"},{"i":10,"n":"第十条","txt":"本办法自2000年10月1日起施行。"}],"zhongcaiweiyuanhuizhongcaishoufeibanfa":[{"i":1,"n":"第一条","txt":"为了规范仲裁委员会的仲裁收费，制定本办法。"},{"i":2,"n":"第二条","txt":"当事人申请仲裁，应当按照本办法的规定向仲裁委员会交纳仲裁费用，仲裁费用包括案件受理费和案件处理费。"},{"i":3,"n":"第三条","txt":"案件受理费用于给付仲裁员报酬、维持仲裁委员会正常运转的必要开支。"},{"i":4,"n":"第四条","txt":"申请人应当自收到仲裁委员会受理通知书之日起15日内，按照仲裁案件受理费表的规定预交案件受理费。被申请人在提出反请求的同时，应当按照仲裁案件受理费表的规定预交案件受理费。"},{"i":5,"n":"第五条","txt":"仲裁案件受理费表中的争议金额，以申请人请求的数额为准；请求的数额与实际争议金额不一致的，以实际争议金额为准。"},{"i":6,"n":"第六条","txt":"当事人预交案件受理费确有困难的，由当事人提出申请，经仲裁委员会批准，可以缓交。"},{"i":7,"n":"第七条","txt":"案件处理费包括："},{"i":8,"n":"第八条","txt":"案件处理费的收费标准按照国家有关规定执行；国家没有规定的，按照合理的实际支出收取。"},{"i":9,"n":"第九条","txt":"仲裁费用原则上由败诉的当事人承担；当事人部分胜诉、部分败诉的，由仲裁庭根据当事人各方责任大小确定其各自应当承担的仲裁费用的比例。当事人自行和解或者经仲裁庭调解结案的，当事人可以协商确定各自承担的仲裁费用的比例。"},{"i":10,"n":"第十条","txt":"依照仲裁法第六十一条的规定，仲裁庭同意重新仲裁的，仲裁委员会不得再行收取案件受理费。"},{"i":11,"n":"第十一条","txt":"申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭，可以视为撤回仲裁申请，案件受理费、处理费不予退回。"},{"i":12,"n":"第十二条","txt":"仲裁委员会受理仲裁申请后，仲裁庭组成前，申请人撤回仲裁申请，或者当事人自行达成和解协议并撤回仲裁申请的，案件受理费应当全部退回。"},{"i":13,"n":"第十三条","txt":"本办法第五条、第十二条的规定同样适用于被申请人提出反请求的情形。"},{"i":14,"n":"第十四条","txt":"仲裁委员会收取仲裁案件受理费，应当使用省、自治区、直辖市人民政府财政部门统一印制的收费票据，并按照国家有关规定，建立、健全财务核算制度，加强财务、收支管理，接受财政、审计、税务、物价等部门的监督。"},{"i":15,"n":"第十五条","txt":"本办法自1995年9月1日起施行。"}],"zhongcaiweiyuanhuidengjizanxingbanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国仲裁法》（以下简称仲裁法），制定本办法。"},{"i":2,"n":"第二条","txt":"仲裁委员会的登记机关是省、自治区、直辖市的司法行政部门。"},{"i":3,"n":"第三条","txt":"仲裁委员会可以在直辖市和省、自治区人民政府所在地的市设立，也可以根据需要在其他设区的市设立，不按行政区划层层设立。"},{"i":4,"n":"第四条","txt":"登记机关应当在收到本办法第三条第三款规定的文件之日起10日内，对符合设立条件的仲裁委员会予以设立登记，并发给登记证书；对符合设立条件，但所提供的文件不符合本办法第三条第三款规定的，在要求补正后予以登记；对不符合本办法第三条第一款规定的，不予登记。"},{"i":5,"n":"第五条","txt":"仲裁委员会变更住所、组成人员，应当在变更后的10日内向登记机关备案，并向登记机关提交与变更事项有关的文件。"},{"i":6,"n":"第六条","txt":"仲裁委员会决议终止的，应当向登记机关办理注销登记。"},{"i":7,"n":"第七条","txt":"登记机关应当自收到本办法第六条第二款规定的文件、证书之日起10日内，对符合终止条件的仲裁委员会予以注销登记，收回仲裁委员会登记证书。"},{"i":8,"n":"第八条","txt":"登记机关对仲裁委员会的设立登记、注销登记，自作出登记之日起生效，予以公告，并报国务院司法行政部门备案。"},{"i":9,"n":"第九条","txt":"仲裁法施行前在直辖市和省、自治区人民政府所在地的市以及其他设区的市设立的仲裁机构，应当依照仲裁法和国务院的有关规定重新组建，并依照本办法申请设立登记；未重新组建的，自仲裁法施行之日起届满1年时终止。"},{"i":10,"n":"第十条","txt":"本办法自1995年9月1日起施行。"}],"qiyeguoyouzichanchanquandengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强企业国有资产产权登记管理，健全国有资产基础管理制度，防止国有资产流失，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称企业国有资产产权登记（以下简称产权登记），是指国有资产管理部门代表政府对占有国有资产的各类企业的资产、负债、所有者权益等产权状况进行登记，依法确认产权归属关系的行为。"},{"i":3,"n":"第三条","txt":"国有企业、国有独资公司、持有国家股权的单位以及以其他形式占有国有资产的企业（以下统称企业），应当依照本办法的规定办理产权登记。"},{"i":4,"n":"第四条","txt":"企业产权归属关系不清楚或者发生产权纠纷的，可以申请暂缓办理产权登记。"},{"i":5,"n":"第五条","txt":"县级以上各级人民政府国有资产管理部门，按照产权归属关系办理产权登记。"},{"i":6,"n":"第六条","txt":"产权登记分为占有产权登记、变动产权登记和注销产权登记。"},{"i":7,"n":"第七条","txt":"企业应当依照本办法向国有资产管理部门办理占有产权登记。"},{"i":8,"n":"第八条","txt":"企业发生下列变动情形之一的，应当自变动之日起30日内办理变动产权登记："},{"i":9,"n":"第九条","txt":"企业发生下列情形之一的，应当自各该情形发生之日起30日内办理注销产权登记："},{"i":10,"n":"第十条","txt":"企业办理产权登记，应当按照规定填报国有资产产权登记表并提交有关文件、凭证、报表等。填报的内容或者提交的文件、凭证、报表等不符合规定的，国有资产管理部门有权要求企业补正。"},{"i":11,"n":"第十一条","txt":"产权登记实行年度检查制度。"},{"i":12,"n":"第十二条","txt":"国有资产产权登记表由国务院国有资产管理部门统一制定。"},{"i":13,"n":"第十三条","txt":"国有资产管理部门应当建立健全产权登记档案制度，并定期分析和报告国有资产产权状况。"},{"i":14,"n":"第十四条","txt":"企业违反本办法规定，有下列行为之一的，由国有资产管理部门责令改正、通报批评，可以处以10万元以下的罚款，并提请政府有关部门对企业领导人员和直接责任人员按照规定给予纪律处分："},{"i":15,"n":"第十五条","txt":"国有资产管理部门工作人员在办理产权登记中玩忽职守、徇私舞弊、滥用职权、谋取私利，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":16,"n":"第十六条","txt":"军队企业的国有资产产权登记管理办法，由中国人民解放军总后勤部会同国务院国有资产管理部门参照本办法制定。"},{"i":17,"n":"第十七条","txt":"本办法自发布之日起施行。国家国有资产管理局、财政部、国家工商行政管理局1992年5月11日发布的《国有资产产权登记管理试行办法》同时废止。"}],"baoshuiquhaiguanjianguanbanfa":[{"i":1,"n":"第一条","txt":"为了加强与完善海关对保税区的监管，促进保税区的健康发展，根据海关法和其他有关法律的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立保税区，必须经国务院批准。"},{"i":3,"n":"第三条","txt":"保税区是海关监管的特定区域。海关依照本办法对进出保税区的货物、运输工具、个人携带物品实施监管。"},{"i":4,"n":"第四条","txt":"保税区内仅设置保税区行政管理机构和企业。除安全保卫人员外，其他人员不得在保税区内居住。"},{"i":5,"n":"第五条","txt":"在保税区内设立的企业（以下简称区内企业），应当向海关办理注册手续。"},{"i":6,"n":"第六条","txt":"保税区实行海关稽查制度。"},{"i":7,"n":"第七条","txt":"海关对进出保税区的货物、物品、运输工具、人员及区内有关场所，有权依照海关法的规定进行检查、查验。"},{"i":8,"n":"第八条","txt":"国家禁止进出口的货物、物品，不得进出保税区。"},{"i":9,"n":"第九条","txt":"海关对保税区与境外之间进出的货物，实施简便、有效的监管。"},{"i":10,"n":"第十条","txt":"保税区与境外之间进出的货物，由货物的收货人、发货人或其代理人向海关备案。"},{"i":11,"n":"第十一条","txt":"对保税区与境外之间进出的货物，除实行出口被动配额管理的外，不实行进出口配额、许可证管理。"},{"i":12,"n":"第十二条","txt":"从境外进入保税区的货物，其进口关税和进口环节税收，除法律、行政法规另有规定外，按照下列规定办理："},{"i":13,"n":"第十三条","txt":"从保税区进入非保税区的货物，按照进口货物办理手续；从非保税区进入保税区的货物，按照出口货物办理手续，出口退税按照国家有关规定办理。"},{"i":14,"n":"第十四条","txt":"从非保税区进入保税区供区内使用的机器、设备、基建物资和物品，使用单位应当向海关提供上述货物或者物品的清单，经海关查验后放行。"},{"i":15,"n":"第十五条","txt":"保税区的货物需从非保税区口岸进出口或者保税区内的货物运往另一保税区的，应当事先向海关提出书面申请，经海关批准后，按照海关转关运输及有关规定办理。"},{"i":16,"n":"第十六条","txt":"保税区内的货物可以在区内企业之间转让、转移；双方当事人应当就转让、转移事项向海关备案。"},{"i":17,"n":"第十七条","txt":"保税区内的转口货物可以在区内仓库或者区内其他场所进行分级、挑选、刷贴标志、改换包装形式等简单加工。"},{"i":18,"n":"第十八条","txt":"区内企业在保税区内举办境外商品和非保税区商品的展示活动，展示的商品应当接受海关监管。"},{"i":19,"n":"第十九条","txt":"区内加工企业应当向海关办理所需料、件进出保税区备案手续。"},{"i":20,"n":"第二十条","txt":"区内加工企业生产属于被动配额管理的出口产品，应当事先经国务院有关主管部门批准。"},{"i":21,"n":"第二十一条","txt":"区内加工企业加工的制成品及其在加工过程中产生的边角余料运往境外时，应当按照国家有关规定向海关办理手续；除法律、行政法规另有规定外，免征出口关税。"},{"i":22,"n":"第二十二条","txt":"区内加工企业全部用境外运入料、件加工的制成品销往非保税区时，海关按照进口制成品征税。"},{"i":23,"n":"第二十三条","txt":"区内加工企业委托非保税区企业或者接受非保税区企业委托进行加工业务，应当事先经海关批准，并符合下列条件："},{"i":24,"n":"第二十四条","txt":"海关对区内加工企业进料加工、来料加工业务，不实行加工贸易银行保证金台账制度。"},{"i":25,"n":"第二十五条","txt":"运输工具和人员进出保税区，应当经由海关指定的专用通道，并接受海关检查。"},{"i":26,"n":"第二十六条","txt":"进出保税区的运输工具的负责人，应当持保税区主管机关批准的证件连同运输工具的名称、数量、牌照号码及驾驶员姓名等清单，向海关办理登记备案手续。"},{"i":27,"n":"第二十七条","txt":"未经海关批准，从保税区到非保税区的运输工具和人员不得运输、携带保税区内的免税货物、物品，保税货物，以及用保税料、件生产的产品。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定的，由海关依照《中华人民共和国海关法》及《中华人民共和国海关行政处罚实施条例》的规定处理；情节严重的，海关可以取消区内企业在海关的注册资格。"},{"i":29,"n":"第二十九条","txt":"本办法规定的有关备案的具体办法，由海关总署制定。"},{"i":30,"n":"第三十条","txt":"本办法自发布之日起施行。《中华人民共和国海关对进出上海外高桥保税区货物、运输工具和个人携带物品的管理办法》同时废止。"}],"quanguonianjiejijinianrifangjiabanfa":[{"i":1,"n":"第一条","txt":"为统一全国年节及纪念日的假期，制定本办法。"},{"i":2,"n":"第二条","txt":"全体公民放假的节日："},{"i":3,"n":"第三条","txt":"部分公民放假的节日及纪念日："},{"i":4,"n":"第四条","txt":"少数民族习惯的节日，由各少数民族聚居地区的地方人民政府，按照各该民族习惯，规定放假日期。"},{"i":5,"n":"第五条","txt":"二七纪念日、五卅纪念日、七七抗战纪念日、九三抗战胜利纪念日、九一八纪念日、教师节、护士节、记者节、植树节等其他节日、纪念日，均不放假。"},{"i":6,"n":"第六条","txt":"全体公民放假的假日，如果适逢周六、周日，应当在工作日补假。部分公民放假的假日，如果适逢周六、周日，则不补假。"},{"i":7,"n":"第七条","txt":"全体公民放假的假日，可合理安排统一放假调休，结合落实带薪年休假等制度，实际形成较长假期。除个别特殊情形外，法定节假日假期前后连续工作一般不超过6天。"},{"i":8,"n":"第八条","txt":"本办法自公布之日起施行。"}],"guanyuwaishangcanyudalaozhongguoyanhaishuiyuchench6fcc28":[{"i":1,"n":"第一条","txt":"为加强对外商参与打捞中国沿海水域沉船沉物活动的管理，保障有关各方的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于外商参与打捞中国沿海水域具有商业价值的沉船沉物活动。"},{"i":3,"n":"第三条","txt":"本办法下列用语的定义："},{"i":4,"n":"第四条","txt":"中国政府依法保护参与打捞中国沿海水域沉船沉物的中外双方（以下简称参与打捞的中外双方）的应得收益和其他合法权益。"},{"i":5,"n":"第五条","txt":"国务院交通运输主管部门主管有关外商参与打捞中国沿海水域沉船沉物的事宜。"},{"i":6,"n":"第六条","txt":"外商参与打捞中国沿海水域沉船沉物，可以采取下列方式："},{"i":7,"n":"第七条","txt":"共同打捞合同和打捞企业合同必须有明确的打捞标的。参与打捞的中外双方在打捞过程中发现的不属于合同标的的其他沉船沉物，不得擅自实施打捞。"},{"i":8,"n":"第八条","txt":"国务院交通运输主管部门负责统一组织与外商洽谈打捞中国沿海水域沉船沉物的事宜，确立打捞项目，并组织中方打捞人与外商依法签订共同打捞合同或者打捞企业合同；涉及军事禁区、军事管理区的，应当符合《中华人民共和国军事设施保护法》的有关规定。"},{"i":9,"n":"第九条","txt":"外商与中方打捞人签订共同打捞合同，应当符合《中华人民共和国合同法》的有关规定。共同打捞合同签订后，外商应当按照规定向市场监督管理部门申请营业登记，并向当地税务机关办理税务登记手续。"},{"i":10,"n":"第十条","txt":"外商参与在中华人民共和国内海或者领海内打捞沉船沉物，应当承担打捞作业期间的全部费用和经济风险。中方打捞人负责与有关部门的协调，办理必要的手续及打捞作业期间的监护。"},{"i":11,"n":"第十一条","txt":"外商为履行共同打捞合同所需船舶、设备及劳务，在同等条件下应当优先向中方打捞人租用和雇佣。"},{"i":12,"n":"第十二条","txt":"外商参与打捞中国沿海水域沉船沉物的捞获物（以下简称捞获物）应当按照下列方式处理："},{"i":13,"n":"第十三条","txt":"外商依法取得的捞获物可以按照国际市场价格由中国政府有关部门收购或者由外商依法纳税并办理海关手续后运往国外。"},{"i":14,"n":"第十四条","txt":"打捞作业者在实施打捞作业前，应当按照《中华人民共和国海上交通安全法》的有关规定申请发布航行警告。"},{"i":15,"n":"第十五条","txt":"实施打捞作业应当自始至终有参与打捞的中外双方的有关人员参加，双方共同负责捞获物的登记和保管工作。"},{"i":16,"n":"第十六条","txt":"所有捞获物应当在中国政府主管部门指定的地点接受有关部门的检查。"},{"i":17,"n":"第十七条","txt":"违反本办法打捞中国沿海水域沉船沉物的，港务监督有权责令其停止打捞作业，并可给予警告、罚款的处罚，其中已给国家和他人造成损失的，应当承担赔偿责任。"},{"i":18,"n":"第十八条","txt":"香港、澳门、台湾的企业、个人及其他经济组织参与打捞中国沿海水域的沉船沉物，参照本办法执行。"},{"i":19,"n":"第十九条","txt":"本办法自发布之日起施行。"}],"junyongbiaozhunhuaguanlibanfa":[{"i":1,"n":"第一条","txt":"军用标准化是国防现代化建设中一项综合性的技术基础工作，对促进国防科学技术进步，加速发展军事技术装备，增强部队战斗力，具有重要的战略意义。为了加强军用标准化的管理，根据国务院、中央军委有关国防现代化建设的方针、原则和《中华人民共和国标准化管理条例》，特制订本办法。"},{"i":2,"n":"第二条","txt":"军用标准化工作应当认真贯彻“质量第一”的方针，坚持科研、生产、使用相结合的原则。"},{"i":3,"n":"第三条","txt":"军用技术标准（简称军用标准，下同）是为满足军用要求而制订的技术标准，是从事国防科研、生产和使用、维修活动的共同技术依据。"},{"i":4,"n":"第四条","txt":"国家标准凡能满足军用要求的，应当贯彻执行；各部门制订的专业标准（部标准，下同），凡能满足军用要求的，可以直接采用。"},{"i":5,"n":"第五条","txt":"对国际标准和国外先进标准，必须结合我国的国情，认真研究，区别对待，积极采用。"},{"i":6,"n":"第六条","txt":"军用标准化规划、计划应当纳入各部门的军事技术装备发展和国防科研、生产规划、计划。"},{"i":7,"n":"第七条","txt":"制订、修订军用标准，应当充分考虑军事技术装备的发展和使用要求，密切结合我国的实际情况，做到技术先进，安全可靠，经济合理。"},{"i":8,"n":"第八条","txt":"军用标准包括国家军用标准和各部门、各单位为军事技术装备制定的专业标准和企业标准。专业标准和企业标准不得与国家军用标准相抵触；企业标准不得与专业标准相抵触。"},{"i":9,"n":"第九条","txt":"国家军用标准是指对国防科学技术和军事技术装备发展有重大意义而必须在国防科研、生产、使用范围内统一的标准。"},{"i":10,"n":"第十条","txt":"制订、修订国家军用标准，应当采取科研、生产、使用相结合的形式，按照标准的不同对象和部门的业务分工，由主管部门与有关部门协商确定主办部门和参加单位。"},{"i":11,"n":"第十一条","txt":"国家军用标准，由主办部门提出草案，属于通用后勤技术装备（包括后勤专用车辆，下同）和军队医药卫生方面的，报总后勤部审批和发布；其余的报国防科学技术工业委员会（以下简称国防科工委）审批和发布；特别重大的，由国防科工委或总后勤部报国务院、中央军委审批后发布。"},{"i":12,"n":"第十二条","txt":"军用标准应当根据国民经济和国防科学技术的发展，及时进行修订。"},{"i":13,"n":"第十三条","txt":"制订军用标准所需的经费和物资，应当列入各部门、各单位的科研计划。"},{"i":14,"n":"第十四条","txt":"军用标准一经发布，各有关部门都必须严格贯彻执行。各级标准化管理部门负责督促检查。"},{"i":15,"n":"第十五条","txt":"研制军用新产品，必须认真执行标准化的要求。"},{"i":16,"n":"第十六条","txt":"已鉴定定型的产品，如因改用标准而影响产品的基本战术技术性能，应当由设计单位和同级标准化机构提出报告，征得使用部门同意，报有关军工产品定型委员会审批；如属改进或改型，其更改部分应当按研制新产品的要求进行标准化审查。"},{"i":17,"n":"第十七条","txt":"引进军事装备技术，必须进行标准化审查。一般的项目，由各国防工业部、军兵种和总部有关部（局）组织审查；重大的项目，由国防科工委或总后勤部组织审查。"},{"i":18,"n":"第十八条","txt":"军用产品的原料、材料、协作件、外购件、半成品和自制件，均应由检验部门严格按照有关标准或图样和技术文件的规定进行验收或复验合格后，才能投产或参加整机的装配、测试和各种试验。"},{"i":19,"n":"第十九条","txt":"贯彻标准所需的经费和物资，应当列入各部门、各单位的技术改造和技术措施计划。"},{"i":20,"n":"第二十条","txt":"国防科工委、总后勤部、各国防工业部、军兵种、总部有关部（局）和承担军品任务的有关部门，应当建立或健全相应的标准化管理机构，配备专职人员，开展标准化工作。"},{"i":21,"n":"第二十一条","txt":"国防科工委标准化管理机构是在国家标准局的业务指导下，管理军用标准化工作的职能部门。其主要任务是："},{"i":22,"n":"第二十二条","txt":"各国防工业部、军兵种、总部有关部（局）和承担军品任务的有关部门的标准化管理机构，负责管理本部门的标准化工作。其主要任务是："},{"i":23,"n":"第二十三条","txt":"各国防工业部、军兵种、总部有关部（局）和承担军品任务的有关部门所属企事业单位的标准化管理机构或专职人员，负责管理本单位的标准化工作和承办上级机关交给的标准化任务。"},{"i":24,"n":"第二十四条","txt":"各部门标准化研究机构的主要任务是："},{"i":25,"n":"第二十五条","txt":"根据军事技术装备的不同类别和各专业的特点，设立若干个由科研、生产、使用部门的代表组成的专业军用标准化技术组织。其章程和管理办法另行制订。"},{"i":26,"n":"第二十六条","txt":"从事标准化工作的科技人员，要具有与其所任工作相适应的技术水平、政策水平、组织能力和实践经验，并应保持相对的稳定。"},{"i":27,"n":"第二十七条","txt":"对在标准化工作中做出显著成绩或有重大贡献的人员，各部门、各单位应当给予奖励。"},{"i":28,"n":"第二十八条","txt":"对违反本办法的单位或个人，各主管部门应当根据情节与后果的严重程度，按国家或军队的有关规定严肃处理。"},{"i":29,"n":"第二十九条","txt":"本办法仅限于对军用技术标准的管理，属于装备的体制和系列、使用、管理等，按中央军委有关规定，分别由总参谋部、总后勤部负责归口管理。"},{"i":30,"n":"第三十条","txt":"各国防工业部、军兵种、总部有关部（局）和承担军品任务的有关部门，可根据本办法的精神制订本部门的实施细则。"},{"i":31,"n":"第三十一条","txt":"本办法由国防科工委负责解释。"},{"i":32,"n":"第三十二条","txt":"本办法自发布之日起施行。"}],"junyongyinshigongyingzhangongshuizhanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强军用饮食供应站、军用供水站（以下统称军供站）的管理，保障军队平时、战时在运输途中的饮食饮水供应，制定本办法。"},{"i":2,"n":"第二条","txt":"军供站是人民政府支援过往部队的组织机构和战备设施，在人民政府领导下，由退役军人事务部门负责管理。"},{"i":3,"n":"第三条","txt":"军供站的任务是保障成批过往的部队、入伍的新兵、退伍的老兵和支前民兵、民工等在运输途中的饮食饮水的供应以及军运马匹的草料和饮水的供应。"},{"i":4,"n":"第四条","txt":"军供站由省、自治区、直辖市人民政府根据军区的要求，在铁路、公路、水路沿线设置。"},{"i":5,"n":"第五条","txt":"军供站分为常设站和临时站。常设站设置在主要铁路和公路干线的大站、水路的重要港口等军事运输繁忙地方；临时站设置在大批或者紧急军事运输任务需要的地方，任务完成后即行撤销。"},{"i":6,"n":"第六条","txt":"常设军用饮食供应站的基本建设项目应当有厨房、餐厅、仓库、锅炉房、办公室、宿舍、厕所、汽车库、平场、盥洗设施，并根据需要设置遛马场和饮马设备。常设军用供水站的基本建设项目应当有锅炉房、办公室、宿舍、厕所、盥洗设施。"},{"i":7,"n":"第七条","txt":"军供站的基本建设、设施维修、设备购置和用于过往部队接待工作的经费，军供站固定编制人员的工资、福利费和公用经费，按照国家规定的开支渠道，由地方财政安排解决。"},{"i":8,"n":"第八条","txt":"常设军供站应当有少量固定编制的人员，其名额由省、自治区、直辖市人民政府根据军供站的军供任务和所处战略位置的需要确定，并在省、自治区、直辖市的行政编制总额中解决。"},{"i":9,"n":"第九条","txt":"国家在新建、改建车站和港口时，铁路、交通部门应当根据总后勤部军事交通部的要求，将军供站列入工程计划之内一并修建。工程竣工后，铁路、交通部门应当将军供站移交给人民政府的退役军人事务部门。退役军人事务部门对军供站的房屋和设备负责维修。"},{"i":10,"n":"第十条","txt":"中国人民解放军派驻铁路、交通部门的军事代表办事处负责对军供站的业务指导。在有大批军供任务时，军事交通部门应当向军供站预先通报供应任务和注意事项，并指定专人与军供站保持联系。必要时，应当派遣军事代表常驻军供站协助工作。"},{"i":11,"n":"第十一条","txt":"军供站应当根据有关法律、法规，经常对工作人员进行保卫和保密教育，建立、健全保卫和保密工作制度。"},{"i":12,"n":"第十二条","txt":"军供站按照正规化建设要求，实现工作制度化、程序化、标准化，加强对工作人员的思想教育和业务培训，不断提高应变能力和快速保障能力，做好军供工作。"},{"i":13,"n":"第十三条","txt":"对军供站供应工作的基本要求："},{"i":14,"n":"第十四条","txt":"军供站所在地人民政府的有关部门负责做好下列工作："},{"i":15,"n":"第十五条","txt":"部队应当尊重地方工作人员，遵守军供站的供应制度和规定，凭供应通报就餐，并如数交付伙食费和粮票。使用马草马料，应如数交付马料票、马草用款。损坏餐具等物品应当照价赔偿。"},{"i":16,"n":"第十六条","txt":"军供站在保证完成军供任务的前提下，实行平战结合，可以利用现有设施，为部队服务，为社会服务。"},{"i":17,"n":"第十七条","txt":"本办法由退役军人事务部和总后勤部共同解释。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起施行。一九六五年四月七日国务院批转总参谋部、内务部制定的《军用饮食供应站、供水站组织管理暂行办法》同时废止。"}],"yiliaoyongduxingyaopinguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强医疗用毒性药品的管理，防止中毒或死亡事故的发生，根据《中华人民共和国药品管理法》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"医疗用毒性药品（以下简称毒性药品），系指毒性剧烈、治疗剂量与中毒剂量相近，使用不当会致人中毒或死亡的药品。"},{"i":3,"n":"第三条","txt":"毒性药品年度生产、收购、供应和配制计划，由省、自治区、直辖市医药管理部门根据医疗需要制定，经省、自治区、直辖市卫生行政部门审核后，由医药管理部门下达给指定的毒性药品生产、收购、供应单位，并抄报卫生部、国家医药管理局和国家中医药管理局。生产单位不得擅自改变生产计划自行销售。"},{"i":4,"n":"第四条","txt":"药厂必须由医药专业人员负责生产、配制和质量检验，并建立严格的管理制度。严防与其他药品混杂。每次配料，必须经二人以上复核无误，并详细记录每次生产所用原料和成品数。经手人要签字备查。所有工具、容器要处理干净，以防污染其他药品。标示量要准确无误，包装容器要有毒药标志。"},{"i":5,"n":"第五条","txt":"毒性药品的收购、经营，由各级医药管理部门指定的药品经营单位负责；配方用药由国营药店、医疗单位负责。其他任何单位或者个人均不得从事毒性药品的收购、经营和配方业务。"},{"i":6,"n":"第六条","txt":"收购、经营、加工、使用毒性药品的单位必须建立健全保管、验收、领发、核对等制度，严防收假、发错，严禁与其他药品混杂，做到划定仓间或仓位，专柜加锁并由专人保管。"},{"i":7,"n":"第七条","txt":"凡加工炮制毒性中药，必须按照《中华人民共和国药典》或者省、自治区、直辖市卫生行政部门制定的《炮制规范》的规定进行。药材符合药用要求的，方可供应、配方和用于中成药生产。"},{"i":8,"n":"第八条","txt":"生产毒性药品及其制剂，必须严格执行生产工艺操作规程，在本单位药品检验人员的监督下准确投料，并建立完整的生产记录，保存五年备查。"},{"i":9,"n":"第九条","txt":"医疗单位供应和调配毒性药品，凭医生签名的正式处方。国营药店供应和调配毒性药品，凭盖有医生所在的医疗单位公章的正式处方。每次处方剂量不得超过二日极量。"},{"i":10,"n":"第十条","txt":"科研和教学单位所需的毒性药品，必须持本单位的证明信，经单位所在地县以上卫生行政部门批准后，供应部门方能发售。"},{"i":11,"n":"第十一条","txt":"对违反本办法的规定，擅自生产、收购、经营毒性药品的单位或者个人，由县以上卫生行政部门没收其全部毒性药品，并处以警告或按非法所得的五至十倍罚款。情节严重、致人伤残或死亡，构成犯罪的，由司法机关依法追究其刑事责任。"},{"i":12,"n":"第十二条","txt":"当事人对处罚不服的，可在接到处罚通知之日起十五日内，向作出处理的机关的上级机关申请复议。但申请复议期间仍应执行原处罚决定。上级机关应在接到申请之日起十日内作出答复。对答复不服的，可在接到答复之日起十五日内，向人民法院起诉。"},{"i":13,"n":"第十三条","txt":"本办法由卫生部负责解释。"},{"i":14,"n":"第十四条","txt":"本办法自发布之日起施行。1964年4月20日卫生部、商业部、化工部发布的《管理毒药、限制性剧药暂行规定》，1964年12月7日卫生部、商业部发布的《管理毒性中药的暂行办法》，1979年6月30日卫生部、国家医药管理总局发布的《医疗用毒药、限制性剧药管理规定》，同时废止。"}],"weixingdimianjieshousheshijieshouwaiguoweixingchuaeeb76e":[{"i":1,"n":"第一条","txt":"为了加强对卫星地面接收设施接收外国卫星传送的电视节目的管理，保障对外经济、科技和文化交流，促进社会主义物质文明和精神文明建设，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称卫星地面接收设施接收外国卫星传送的电视节目，是指单位利用已有的卫星地面接收设施或者设置专门的卫星地面接收设施接收与本单位业务工作有直接关系的外国卫星传送的电视节目。"},{"i":3,"n":"第三条","txt":"国务院广播电视行政管理部门负责全国卫星地面接收设施接收外国卫星传送的电视节目的管理工作。"},{"i":4,"n":"第四条","txt":"教育、科研、新闻、金融、经贸以及其他确因业务工作需要的单位，可以按照本办法的规定，申请利用已有的卫星地面接收设施或者设置专门的卫星地面接收设施接收外国卫星传送的电视节目。"},{"i":5,"n":"第五条","txt":"申请利用已有的卫星地面接收设施或者申请设置专门的卫星地面接收设施接收外国卫星传送的电视节目，应当具备下列条件："},{"i":6,"n":"第六条","txt":"利用已有的或者设置专门的卫星地面接收设施接收外国卫星传送的电视节目的单位，应当向省级以上主管部门提出书面申请，经审查同意的，由申请单位报所在省、自治区、直辖市人民政府广播电视行政管理部门审批。省、自治区、直辖市人民政府广播电视行政管理部门批准的，发给《卫星地面接收设施接收外国卫星传送的电视节目许可证》（以下简称《许可证》），并由审批机关报国务院广播电视行政管理部门、公安部门、国家安全部门备案。"},{"i":7,"n":"第七条","txt":"已有卫星地面接收设施的单位，未持有《许可证》的，不得接收外国卫星传送的电视节目；其他单位，未持有《许可证》的，不得设置卫星地面接收设施接收外国卫星传送的电视节目。"},{"i":8,"n":"第八条","txt":"持有《许可证》的单位，必须严格按照《许可证》载明的接收外国卫星传送的电视节目的接收目的、接收内容、接收方位、接收方式和收视对象的范围等要求，接收和使用外国电视节目。"},{"i":9,"n":"第九条","txt":"持有《许可证》的单位，接收外国卫星传送的电视节目，只允许在本单位业务工作中使用。除本单位领导批准外，一律不得录制。严禁将所接收的外国卫星传送的电视节目在国内电视台、有线电视台、录像放映点播放或者以其他方式进行传播。"},{"i":10,"n":"第十条","txt":"广播电视行政管理部门、公安机关、国家安全机关负责监督检查卫星地面接收设施接收外国卫星传送的电视节目的管理工作，对违反本办法接收、录制、传播外国卫星传送的电视节目的行为有权予以制止。"},{"i":11,"n":"第十一条","txt":"违反本办法第八条、第九条规定的单位，由省、自治区、直辖市人民政府广播电视行政管理部门会同公安机关、国家安全机关视情节轻重，给予警告、二万元以下的罚款、直至吊销《许可证》的处罚。吊销《许可证》的，可以同时没收其使用的卫星地面接收设施。对单位的直接负责的主管人员和其他直接责任人员，省、自治区、直辖市人民政府广播电视行政管理部门、公安机关、国家安全机关可以建议其主管部门给予行政处分；情节严重构成犯罪的，由司法机关依法追究刑事责任。"},{"i":12,"n":"第十二条","txt":"违反本办法第七条的规定，未持有《许可证》而擅自设置卫星地面接收设施或者接收外国卫星传送的电视节目的单位，省、自治区、直辖市人民政府广播电视行政管理部门会同公安机关、国家安全机关可以没收其卫星地面接收设施，并处以五万元以下的罚款。对单位的直接负责的主管人员和其他直接责任人员可以建议其主管部门给予行政处分；有私自录制、传播行为，情节严重构成犯罪的，由司法机关依法追究刑事责任。"},{"i":13,"n":"第十三条","txt":"当事人对罚款或者吊销《许可证》的处罚不服的，可以在收到处罚决定书之日起十五日内，向同级人民政府申请复议，也可以向人民法院起诉；对行政复议不服的，可以在收到复议决定书之日起十五日内向人民法院起诉。逾期不申请复议或者不起诉的，吊销许可证的处罚生效；逾期不申请复议或者不起诉又不交纳罚款的，罚款的处罚由作出处罚决定的机关申请人民法院强制执行。"},{"i":14,"n":"第十四条","txt":"军队以及公安机关、国家安全机关因国防、公安和国家安全工作需要利用已有的或者专门设置的卫星地面接收设施接收外国卫星传送的电视节目，由军队有关部门、国务院公安部门、国务院国家安全部门分别制定措施进行管理。"},{"i":15,"n":"第十五条","txt":"本办法由国务院广播电视行政管理部门解释。"},{"i":16,"n":"第十六条","txt":"本办法自发布之日起施行。"}],"weixianfeiwujingyingxukezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对危险废物收集、贮存和处置经营活动的监督管理，防治危险废物污染环境，根据《中华人民共和国固体废物污染环境防治法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事危险废物收集、贮存、处置经营活动的单位，应当依照本办法的规定，领取危险废物经营许可证。"},{"i":3,"n":"第三条","txt":"危险废物经营许可证按照经营方式，分为危险废物收集、贮存、处置综合经营许可证和危险废物收集经营许可证。"},{"i":4,"n":"第四条","txt":"县级以上人民政府环境保护主管部门依照本办法的规定，负责危险废物经营许可证的审批颁发与监督管理工作。"},{"i":5,"n":"第五条","txt":"申请领取危险废物收集、贮存、处置综合经营许可证，应当具备下列条件："},{"i":6,"n":"第六条","txt":"申请领取危险废物收集经营许可证，应当具备下列条件："},{"i":7,"n":"第七条","txt":"国家对危险废物经营许可证实行分级审批颁发。"},{"i":8,"n":"第八条","txt":"申请领取危险废物经营许可证的单位，应当在从事危险废物经营活动前向发证机关提出申请，并附具本办法第五条或者第六条规定条件的证明材料。"},{"i":9,"n":"第九条","txt":"发证机关应当自受理申请之日起20个工作日内，对申请单位提交的证明材料进行审查，并对申请单位的经营设施进行现场核查。符合条件的，颁发危险废物经营许可证，并予以公告；不符合条件的，书面通知申请单位并说明理由。"},{"i":10,"n":"第十条","txt":"危险废物经营许可证包括下列主要内容："},{"i":11,"n":"第十一条","txt":"危险废物经营单位变更法人名称、法定代表人和住所的，应当自工商变更登记之日起15个工作日内，向原发证机关申请办理危险废物经营许可证变更手续。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，危险废物经营单位应当按照原申请程序，重新申请领取危险废物经营许可证："},{"i":13,"n":"第十三条","txt":"危险废物综合经营许可证有效期为5年；危险废物收集经营许可证有效期为3年。"},{"i":14,"n":"第十四条","txt":"危险废物经营单位终止从事收集、贮存、处置危险废物经营活动的，应当对经营设施、场所采取污染防治措施，并对未处置的危险废物作出妥善处理。"},{"i":15,"n":"第十五条","txt":"禁止无经营许可证或者不按照经营许可证规定从事危险废物收集、贮存、处置经营活动。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府环境保护主管部门应当于每年3月31日前将上一年度危险废物经营许可证颁发情况报上一级人民政府环境保护主管部门备案。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府环境保护主管部门应当通过书面核查和实地检查等方式，加强对危险废物经营单位的监督检查，并将监督检查情况和处理结果予以记录，由监督检查人员签字后归档。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府环境保护主管部门有权要求危险废物经营单位定期报告危险废物经营活动情况。危险废物经营单位应当建立危险废物经营情况记录簿，如实记载收集、贮存、处置危险废物的类别、来源、去向和有无事故等事项。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府环境保护主管部门应当建立、健全危险废物经营许可证的档案管理制度，并定期向社会公布审批颁发危险废物经营许可证的情况。"},{"i":20,"n":"第二十条","txt":"领取危险废物收集经营许可证的单位，应当与处置单位签订接收合同，并将收集的废矿物油和废镉镍电池在90个工作日内提供或者委托给处置单位进行处置。"},{"i":21,"n":"第二十一条","txt":"危险废物的经营设施在废弃或者改作其他用途前，应当进行无害化处理。"},{"i":22,"n":"第二十二条","txt":"违反本办法第十一条规定的，由县级以上地方人民政府环境保护主管部门责令限期改正，给予警告；逾期不改正的，由原发证机关暂扣危险废物经营许可证。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十二条、第十三条第二款规定的，由县级以上地方人民政府环境保护主管部门责令停止违法行为；有违法所得的，没收违法所得；违法所得超过10万元的，并处违法所得1倍以上2倍以下的罚款；没有违法所得或者违法所得不足10万元的，处5万元以上10万元以下的罚款。"},{"i":24,"n":"第二十四条","txt":"违反本办法第十四条第一款、第二十一条规定的，由县级以上地方人民政府环境保护主管部门责令限期改正；逾期不改正的，处5万元以上10万元以下的罚款；造成污染事故，构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"违反本办法第十五条第一款、第二款、第三款规定的，依照《中华人民共和国固体废物污染环境防治法》的规定予以处罚。"},{"i":26,"n":"第二十六条","txt":"违反本办法第十八条规定的，由县级以上地方人民政府环境保护主管部门责令限期改正，给予警告；逾期不改正的，由原发证机关暂扣或者吊销危险废物经营许可证。"},{"i":27,"n":"第二十七条","txt":"违反本办法第二十条规定的，由县级以上地方人民政府环境保护主管部门责令限期改正，给予警告；逾期不改正的，处1万元以上5万元以下的罚款，并可以由原发证机关暂扣或者吊销危险废物经营许可证。"},{"i":28,"n":"第二十八条","txt":"危险废物经营单位被责令限期整改，逾期不整改或者经整改仍不符合原发证条件的，由原发证机关暂扣或者吊销危险废物经营许可证。"},{"i":29,"n":"第二十九条","txt":"被依法吊销或者收缴危险废物经营许可证的单位，5年内不得再申请领取危险废物经营许可证。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府环境保护主管部门的工作人员，有下列行为之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":31,"n":"第三十一条","txt":"本办法下列用语的含义："},{"i":32,"n":"第三十二条","txt":"本办法施行前，依照地方性法规、规章或者其他文件的规定已经取得危险废物经营许可证的单位，应当在原危险废物经营许可证有效期届满30个工作日前，依照本办法的规定重新申请领取危险废物经营许可证。逾期不办理的，不得继续从事危险废物经营活动。"},{"i":33,"n":"第三十三条","txt":"本办法自2004年7月1日起施行。"}],"guowuyuanguanyukaizhanquanminyiwuzhishuyundongdeshded1fc":[],"guojingheliuwaiguojichuanboguanlibanfa":[{"i":1,"n":"第一条","txt":"为了维护中华人民共和国主权，便利外国籍船舶进出我国同邻国互为边界的国境河流港口（以下简称国境河流港口）和我国同邻国相通的河流（以下简称同邻国相通河流），保障外国籍船舶航行安全，特制订本办法。"},{"i":2,"n":"第二条","txt":"进出国境河流港口和同邻国相通河流的所有外国籍船舶，都应当遵守本办法。"},{"i":3,"n":"第三条","txt":"在国境河流港口和同邻国相通河流的港口，设立中华人民共和国港务监督。"},{"i":4,"n":"第四条","txt":"外国籍船舶，只有根据其所属国家政府同我国政府签订的有关商船通航协定，或者获得我国政府的许可，才可以进出国境河流港口和同邻国相通河流；每次进出口，还必须依照本办法第五条和第九条第二款的规定，报请港务监督批准。"},{"i":5,"n":"第五条","txt":"外国籍船舶要求进入国境河流港口和同邻国相通河流，船长应当在船舶从出发港开航前，将船名、船队艘数、最大吃水、载货名称和数量、载客人数、预定到达国境河流港口和同邻国相通河流联合检查（引水）锚地的时间，通过其在港代理人，报请预定到达的国境河流港口或同邻国相通河流的第一港口的港务监督审批。外国籍船舶的出发港在国境河流预定到达港对岸的，可以简化手续，用港务监督规定的信号报请审批。"},{"i":6,"n":"第六条","txt":"外国籍船舶进出国境河流港口和在同邻国相通河流航行，应当悬挂各项规定号帜，白昼还应当悬挂其所属国籍的国旗；在同邻国相通河流航行，还应当在前桅顶部悬挂中华人民共和国国旗。"},{"i":7,"n":"第七条","txt":"外国籍船舶进出国境河流港口和同邻国相通河流，必须向港务监督申请引水员引航。外国籍船舶在港口停泊期间，非经引水员引航不得擅自移泊。如果国境河流港口因特殊情况未划定引水锚地，港务监督可以免除进出口外国籍船舶的引水申请。"},{"i":8,"n":"第八条","txt":"外国籍船舶进入引水锚地，船长应将船上所有武器、弹药、无线电发报机、无线电话发射机、雷达、火箭信号、信号炮等的名称、数量向港务监督申报，并遵守下列规定："},{"i":9,"n":"第九条","txt":"外国籍船舶进入引水锚地，船长应当填报港务监督规定的表报，呈验有关船舶文书，并接受港务监督和有关部门的联合检查。"},{"i":10,"n":"第十条","txt":"外国籍船舶在同邻国相通河流内航行时，港务监督或其他有关检查机关可派员随船工作，船长应给予方便。"},{"i":11,"n":"第十一条","txt":"外国籍船舶及其船员、旅客进入国境河流港口和同邻国相通河流，禁止下列行为："},{"i":12,"n":"第十二条","txt":"外国籍船舶，禁止在国境河流我方沿岸未经指定的地点和同邻国相通河流未经指定的地点停靠、锚泊、上下人员和装卸货物。在发生海损事故或遇有不可抗力情况时，可以例外，但船长应立即向港务监督或当地人民委员会报告。"},{"i":13,"n":"第十三条","txt":"外国籍船舶在国境河流港口和同邻国相通河流发生海损事故时，船长应当迅速向港务监督提出海损事故报告书，听候港务监督进行调查处理。"},{"i":14,"n":"第十四条","txt":"外国籍船舶有下列情况之一时，港务监督可以禁止其出航："},{"i":15,"n":"第十五条","txt":"外国籍船舶及其船员、旅客违反本办法和有关航务法令、规章的，港务监督应当根据情节，予以处理。"},{"i":16,"n":"第十六条","txt":"外国籍船舶所属国家政府已经同我国政府签订有商船通航协定的，可以仍按协定执行；协定中未规定的，按照本办法执行。"},{"i":17,"n":"第十七条","txt":"各有关省、自治区、直辖市人民委员会，可以根据本办法，结合当地具体情况，制订实施细则。"},{"i":18,"n":"第十八条","txt":"本办法经国务院批准，由交通部发布施行。"}],"guojiazhongdianjianshexiangmuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强国家重点建设项目的管理，保证国家重点建设项目的工程质量和按期竣工，提高投资效益，促进国民经济持续、快速、健康发展，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国家重点建设项目，是指从下列国家大中型基本建设项目中确定的对国民经济和社会发展有重大影响的骨干项目："},{"i":3,"n":"第三条","txt":"国家重点建设项目的确定，根据国家产业政策、国民经济和社会发展的需要和可能，实行突出重点、量力而行、留有余地、防止资金分散、保证投资落实和资金供应的原则。"},{"i":4,"n":"第四条","txt":"国家重点建设项目由国务院计划主管部门商国务院有关主管部门确定。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市以及计划单列市的人民政府计划主管部门和国务院有关主管部门（公司），按照本办法第二条规定的范围和第三条规定的原则，对本地区、本部门的基本建设项目进行平衡后，每年可以向国务院计划主管部门提出列为国家重点建设项目的申请。"},{"i":6,"n":"第六条","txt":"国务院计划主管部门和有关地方人民政府计划主管部门，应当按照国家重点建设项目的建设工期，安排国家重点建设项目的年度投资计划。"},{"i":7,"n":"第七条","txt":"国家重点建设项目，实行建设项目法人责任制；国家另有规定的，从其规定。"},{"i":8,"n":"第八条","txt":"根据国家重点建设项目的年度投资计划和合同，负有拨付建设资金责任的国务院有关主管部门、有关地方人民政府、银行和企业事业单位，应当按照项目的建设进度，保证拨付建设资金。"},{"i":9,"n":"第九条","txt":"国家重点建设项目的设备储备资金，各有关银行和部门应当优先安排。"},{"i":10,"n":"第十条","txt":"国务院计划主管部门和有关地方人民政府计划主管部门，在安排国家重点建设项目的年度投资计划时，应当预留一定比例的资金，用于国家重点建设项目建设过程中的特殊需要。"},{"i":11,"n":"第十一条","txt":"任何单位和个人不得挪用、截留国家重点建设项目的建设资金以及设备储备资金。"},{"i":12,"n":"第十二条","txt":"地方人民政府负责与国家重点建设项目征地有关的协调工作，并提供必要的便利条件。土地管理部门应当依法保证国家重点建设项目的建设用地。"},{"i":13,"n":"第十三条","txt":"国家重点建设项目主体工程的设计、施工、监理、设备采购，由建设项目法人依法公开进行招标，择优选定中标单位；但是，按照规定经批准可以议标、邀请招标的除外。"},{"i":14,"n":"第十四条","txt":"电力、交通、邮电、供水、供热等单位，应当优先保证国家重点建设项目对施工和生产用电、物资运输、邮电通信和用水、用热等方面的需要，按照合同的约定履行义务。"},{"i":15,"n":"第十五条","txt":"有关企业事业单位应当优先供应国家重点建设项目所需的设备、材料，按照合同的约定履行义务。"},{"i":16,"n":"第十六条","txt":"任何单位和个人不得向国家重点建设项目收取费用；但是，法律或者国务院另有规定的，从其规定。"},{"i":17,"n":"第十七条","txt":"建设项目法人应当按照国家有关规定，向国务院计划主管部门报送国家重点建设项目的建设情况和资料，并抄报有关主管部门和银行。"},{"i":18,"n":"第十八条","txt":"为国家重点建设项目直接配套的项目，应当按照国家重点建设项目的建设进度，同步进行建设。为配套的项目提供建设资金的部门和单位，应当保证按照项目的建设进度拨付建设资金。"},{"i":19,"n":"第十九条","txt":"国家重点建设项目建成并经过试运营，应当按照批准的设计文件和其他有关文件，由建设项目法人及时组织设计、施工等单位进行初步验收。"},{"i":20,"n":"第二十条","txt":"国家重点建设项目竣工验收合格的，经过运营，应当按照国家有关规定进行项目后评价。"},{"i":21,"n":"第二十一条","txt":"国务院计划主管部门会同国务院有关主管部门、有关地方人民政府，对国家重点建设项目的建设进行协调、指导和监督。"},{"i":22,"n":"第二十二条","txt":"未按照规定拨付国家重点建设项目资金的，由国务院计划主管部门予以通报批评，并提请有关主管部门对负有直接责任的主管人员和其他责任人员依法给予行政处分；地方投资的部分连续两年未按照规定拨付的，国务院计划主管部门有权停止审批该地方下一年度的新开工项目。"},{"i":23,"n":"第二十三条","txt":"挪用、截留国家重点建设项目资金的，由审计机关、财政机关追还被挪用、截留的资金，予以通报批评，并提请有关主管部门对负有直接责任的主管人员和其他责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"扰乱国家重点建设项目建设、生产经营秩序，致使其不能正常进行的，依照《中华人民共和国治安管理处罚法》的规定给予处罚；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"国家重点建设项目工程因管理不善、弄虚作假，造成严重超概算、质量低劣、损失浪费或者责任事故的，由国务院计划主管部门予以通报批评，并提请有关主管部门对负有直接责任的主管人员和其他责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"本办法自发布之日起施行。"}],"guoyouzichanpingguguanlibanfa":[{"i":1,"n":"第一条","txt":"为了正确体现国有资产的价值量，保护国有资产所有者和经营者、使用者的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"国有资产评估，除法律、法规另有规定外，适用本办法。"},{"i":3,"n":"第三条","txt":"国有资产占有单位（以下简称占有单位）有下列情形之一的，应当进行资产评估："},{"i":4,"n":"第四条","txt":"占有单位有下列情形之一，当事人认为需要的，可以进行资产评估："},{"i":5,"n":"第五条","txt":"全国或者特定行业的国有资产评估，由国务院决定。"},{"i":6,"n":"第六条","txt":"国有资产评估范围包括：固定资产、流动资产、无形资产和其他资产。"},{"i":7,"n":"第七条","txt":"国有资产评估应当遵循真实性、科学性、可行性原则，依照国家规定的标准、程序和方法进行评定和估算。"},{"i":8,"n":"第八条","txt":"国有资产评估工作，按照国有资产管理权限，由国有资产管理行政主管部门负责管理和监督。"},{"i":9,"n":"第九条","txt":"持有国务院或者省、自治区、直辖市人民政府国有资产管理行政主管部门颁发的国有资产评估资格证书的资产评估公司、会计师事务所、审计事务所、财务咨询公司，经国务院或者省、自治区、直辖市人民政府国有资产管理行政主管部门认可的临时评估机构（以下统称资产评估机构），可以接受占有单位的委托，从事国有资产评估业务。"},{"i":10,"n":"第十条","txt":"占有单位委托资产评估机构进行资产评估时，应当如实提供有关情况和资料。资产评估机构应当对占有单位提供的有关情况和资料保守秘密。"},{"i":11,"n":"第十一条","txt":"资产评估机构进行资产评估，实行有偿服务。资产评估收费办法，由国务院国有资产管理行政主管部门会同财政部门、物价主管部门制定。"},{"i":12,"n":"第十二条","txt":"国有资产评估按照下列程序进行："},{"i":13,"n":"第十三条","txt":"依照本办法第三条、第四条规定进行资产评估的占有单位，经其主管部门审查同意后，应当向同级国有资产管理行政主管部门提交资产评估立项申请书，并附财产目录和有关会计报表等资料。"},{"i":14,"n":"第十四条","txt":"国有资产管理行政主管部门应当自收到资产评估立项申请书之日起十日内进行审核，并作出是否准予资产评估立项的决定，通知申请单位及其主管部门。"},{"i":15,"n":"第十五条","txt":"国务院决定对全国或者特定行业进行国有资产评估的，视为已经准予资产评估立项。"},{"i":16,"n":"第十六条","txt":"申请单位收到准予资产评估立项通知书后，可以委托资产评估机构评估资产。"},{"i":17,"n":"第十七条","txt":"受占有单位委托的资产评估机构应当在对委托单位的资产、债权、债务进行全面清查的基础上，核实资产账面与实际是否相符，经营成果是否真实，据以作出鉴定。"},{"i":18,"n":"第十八条","txt":"受占有单位委托的资产评估机构应当根据本办法的规定，对委托单位被评估资产的价值进行评定和估算，并向委托单位提出资产评估结果报告书。"},{"i":19,"n":"第十九条","txt":"国有资产管理行政主管部门应当自收到占有单位报送的资产评估结果报告书之日起四十五日内组织审核、验证、协商，确认资产评估结果，并下达确认通知书。"},{"i":20,"n":"第二十条","txt":"占有单位对确认通知书有异议的，可以自收到通知书之日起十五日内向上一级国有资产管理行政主管部门申请复核。上一级国有资产管理行政主管部门应当自收到复核申请之日起三十日内作出裁定，并下达裁定通知书。"},{"i":21,"n":"第二十一条","txt":"占有单位收到确认通知书或者裁定通知书后，应当根据国家有关财务、会计制度进行账务处理。"},{"i":22,"n":"第二十二条","txt":"国有资产重估价值，根据资产原值、净值、新旧程度、重置成本、获利能力等因素和本办法规定的资产评估方法评定。"},{"i":23,"n":"第二十三条","txt":"国有资产评估方法包括："},{"i":24,"n":"第二十四条","txt":"用收益现值法进行资产评估的，应当根据被评估资产合理的预期获利能力和适当的折现率，计算出资产的现值，并以此评定重估价值。"},{"i":25,"n":"第二十五条","txt":"用重置成本法进行资产评估的，应当根据该项资产在全新情况下的重置成本，减去按重置成本计算的已使用年限的累积折旧额，考虑资产功能变化、成新率等因素，评定重估价值；或者根据资产的使用期限，考虑资产功能变化等因素重新确定成新率，评定重估价值。"},{"i":26,"n":"第二十六条","txt":"用现行市价法进行资产评估的，应当参照相同或者类似资产的市场价格，评定重估价值。"},{"i":27,"n":"第二十七条","txt":"用清算价格法进行资产评估的，应当根据企业清算时其资产可变现的价值，评定重估价值。"},{"i":28,"n":"第二十八条","txt":"对流动资产中的原材料、在制品、协作件、库存商品、低值易耗品等进行评估时，应当根据该项资产的现行市场价格、计划价格，考虑购置费用、产品完工程度、损耗等因素，评定重估价值。"},{"i":29,"n":"第二十九条","txt":"对有价证券的评估，参照市场价格评定重估价值；没有市场价格的，考虑票面价值、预期收益等因素，评定重估价值。"},{"i":30,"n":"第三十条","txt":"对占有单位的无形资产，区别下列情况评定重估价值："},{"i":31,"n":"第三十一条","txt":"占有单位违反本办法的规定，提供虚假情况和资料，或者与资产评估机构串通作弊，致使资产评估结果失实的，国有资产管理行政主管部门可以宣布资产评估结果无效，并可以根据情节轻重，单处或者并处下列处罚："},{"i":32,"n":"第三十二条","txt":"资产评估机构作弊或者玩忽职守，致使资产评估结果失实的，国有资产管理行政主管部门可以宣布资产评估结果无效，并可以根据情节轻重，对该资产评估机构给予下列处罚："},{"i":33,"n":"第三十三条","txt":"被处罚的单位和个人对依照本办法第三十一条、第三十二条规定作出的处罚决定不服的，可以在收到处罚通知之日起十五日内，向上一级国有资产管理行政主管部门申请复议。上一级国有资产管理行政主管部门应当自收到复议申请之日起六十日内作出复议决定。申请人对复议决定不服的，可以自收到复议通知之日起十五日内，向人民法院提起诉讼。"},{"i":34,"n":"第三十四条","txt":"国有资产管理行政主管部门或者行业主管部门工作人员违反本办法，利用职权谋取私利，或者玩忽职守，造成国有资产损失的，国有资产管理行政主管部门或者行业主管部门可以按照干部管理权限，给予行政处分，并可以处以相当于本人三个月基本工资以下的罚款。"},{"i":35,"n":"第三十五条","txt":"违反本办法，情节严重，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"境外国有资产的评估，不适用本办法。"},{"i":37,"n":"第三十七条","txt":"有关国有自然资源有偿使用、开采的评估办法，由国务院另行规定。"},{"i":38,"n":"第三十八条","txt":"本办法由国务院国有资产管理行政主管部门负责解释。本办法的施行细则由国务院国有资产管理行政主管部门制定。"},{"i":39,"n":"第三十九条","txt":"本办法自发布之日起施行。"}],"guojishouzhitongjishenbaobanfa":[{"i":1,"n":"第一条","txt":"为完善国际收支统计，根据《中华人民共和国统计法》，制定本办法。"},{"i":2,"n":"第二条","txt":"国际收支统计申报范围为中国居民与非中国居民之间发生的一切经济交易以及中国居民对外金融资产、负债状况。"},{"i":3,"n":"第三条","txt":"本办法所称中国居民，是指："},{"i":4,"n":"第四条","txt":"本办法适用于中国境内所有地区，包括在中国境内设立的保税区和保税仓库等。"},{"i":5,"n":"第五条","txt":"国家外汇管理局按照《中华人民共和国统计法》规定的程序，负责组织实施国际收支统计申报，并进行监督、检查；统计、汇总并公布国际收支状况和国际投资状况；制定、修改本办法的实施细则；制发国际收支统计申报单及报表。政府有关部门应当协助国际收支统计申报工作。"},{"i":6,"n":"第六条","txt":"国际收支统计申报实行交易主体申报的原则，采取间接申报与直接申报、逐笔申报与定期申报相结合的办法。"},{"i":7,"n":"第七条","txt":"中国居民和在中国境内发生经济交易的非中国居民应当按照规定及时、准确、完整地申报国际收支信息。"},{"i":8,"n":"第八条","txt":"中国居民通过境内金融机构与非中国居民进行交易的，应当通过该金融机构向国家外汇管理局或其分支局申报交易内容。"},{"i":9,"n":"第九条","txt":"中国境内提供登记结算、托管等服务的机构和自营或者代理客户进行对外证券、期货、期权等交易的交易商，应当向国家外汇管理局或其分支局申报对外交易及相应的收支和分红派息情况。"},{"i":10,"n":"第十条","txt":"中国境内各类金融机构应当直接向国家外汇管理局或其分支局申报其自营对外业务情况，包括其对外金融资产、负债及其变动情况，相应的利润、利息收支情况，以及对外金融服务收支和其他收支情况；并履行与中国居民和非中国居民通过其进行国际收支统计申报活动有关的义务。"},{"i":11,"n":"第十一条","txt":"在中国境外开立账户的中国非金融机构，应当直接向国家外汇管理局或其分支局申报其通过境外账户与非中国居民发生的交易及账户余额。"},{"i":12,"n":"第十二条","txt":"中国境内的外商投资企业、在境外有直接投资的企业及其他有对外金融资产、负债的非金融机构，必须直接向国家外汇管理局或其分支局申报其对外金融资产、负债及其变动情况和相应的利润、股息、利息收支情况。"},{"i":13,"n":"第十三条","txt":"拥有对外金融资产、负债的中国居民个人，应当按照国家外汇管理局的规定申报其对外金融资产、负债的有关情况。"},{"i":14,"n":"第十四条","txt":"国家外汇管理局或其分支局可以就国际收支情况进行抽样调查或者普查。"},{"i":15,"n":"第十五条","txt":"国家外汇管理局或其分支局有权对中国居民和非中国居民申报的内容进行检查、核对，申报人及有关机构和个人应当提供检查、核对所需的资料和便利。"},{"i":16,"n":"第十六条","txt":"国家外汇管理局及其分支局应当对申报者申报的具体数据严格保密，只将其用于国际收支统计。除法律另有规定外，国际收支统计人员不得以任何形式向任何机构和个人提供申报者申报的具体数据。"},{"i":17,"n":"第十七条","txt":"中国居民、非中国居民未按照规定进行国际收支统计申报的，由国家外汇管理局或其分支局依照《中华人民共和国外汇管理条例》第四十八条的规定给予处罚。"},{"i":18,"n":"第十八条","txt":"国际收支统计人员违反本办法第十六条规定的，依法给予处分。"},{"i":19,"n":"第十九条","txt":"国家外汇管理局根据本办法制定《国际收支统计申报办法实施细则》。"},{"i":20,"n":"第二十条","txt":"本办法自1996年1月1日起施行。"}],"guojihangxingchuanbojinchukouanjianchabanfa":[{"i":1,"n":"第一条","txt":"为了加强对国际航行船舶进出中华人民共和国口岸的管理，便利船舶进出口岸，提高口岸效能，制定本办法。"},{"i":2,"n":"第二条","txt":"进出中华人民共和国口岸的国际航行船舶（以下简称船舶）及其所载船员、旅客、货物和其他物品，由本办法第三条规定的机关依照本办法实施检查；但是，法律另有特别规定的，或者国务院另有特别规定的，从其规定。"},{"i":3,"n":"第三条","txt":"中华人民共和国港务监督机构（以下简称港务监督机构）、中华人民共和国海关（以下简称海关）、中华人民共和国出入境边防检查机关是负责对船舶进出中华人民共和国口岸实施检查的机关（以下统称检查机关）。"},{"i":4,"n":"第四条","txt":"检查机关依照有关法律、行政法规的规定实施检查并对违法行为进行处理。"},{"i":5,"n":"第五条","txt":"船舶进出中华人民共和国口岸，由船方或其代理人依照本办法有关规定办理进出口岸手续。除本办法第十条第二款、第十一条规定的情形或者其他特殊情形外，检查机关不登船检查。"},{"i":6,"n":"第六条","txt":"船方或其代理人应当在船舶预计抵达口岸7日前（航程不足7日的，在驶离上一口岸时），填写《国际航行船舶进口岸申请书》，报请抵达口岸的港务监督机构审批。"},{"i":7,"n":"第七条","txt":"船方或其代理人应当在船舶预计抵达口岸24小时前（航程不足24小时的，在驶离上一口岸时），将抵达时间、停泊地点、靠泊移泊计划及船员、旅客的有关情况报告检查机关。"},{"i":8,"n":"第八条","txt":"船方或其代理人在船舶抵达口岸前未办妥进口岸手续的，须在船舶抵达口岸24小时内到检查机关办理进口岸手续。"},{"i":9,"n":"第九条","txt":"船方或其代理人在船舶抵达口岸前已经办妥进口岸手续的，船舶抵达后即可上下人员、装卸货物和其他物品。"},{"i":10,"n":"第十条","txt":"海关对船舶实施电讯检疫。持有卫生证书的船舶，其船方或其代理人可以向海关申请电讯检疫。"},{"i":11,"n":"第十一条","txt":"海关对来自动植物疫区的船舶和船舶装载的动植物、动植物产品及其他检疫物，可以在锚地实施检疫。"},{"i":12,"n":"第十二条","txt":"船方或其代理人应当在船舶驶离口岸前4小时内（船舶在口岸停泊时间不足4小时的，在抵达口岸时），到检查机关办理必要的出口岸手续。有关检查机关应当在《船舶出口岸手续联系单》上签注；船方或其代理人持《船舶出口岸手续联系单》和港务监督机构要求的其他证件、资料，到港务监督机构申请领取出口岸许可证。"},{"i":13,"n":"第十三条","txt":"船舶领取出口岸许可证后，情况发生变化或者24小时内未能驶离口岸的，船方或其代理人应当报告港务监督机构，由港务监督机构商其他检查机关决定是否重新办理出口岸手续。"},{"i":14,"n":"第十四条","txt":"定航线、定船员并在24小时内往返一个或者一个以上航次的船舶，船方或其代理人可以向港务监督机构书面申请办理定期进出口岸手续。受理申请的港务监督机构商其他检查机关审查批准后，签发有效期不超过7天的定期出口岸许可证，在许可证有效期内对该船舶免办进口岸手续。"},{"i":15,"n":"第十五条","txt":"检查机关及其工作人员必须秉公执法，恪尽职守，及时实施检查和办理船舶进出口岸的申请。"},{"i":16,"n":"第十六条","txt":"本办法下列用语的含义："},{"i":17,"n":"第十七条","txt":"本办法自发布之日起施行。经国务院批准，1961年10月24日由交通部、对外贸易部、公安部、卫生部发布的《进出口船舶联合检查通则》同时废止。"}],"chengshishenghuowuzhuodeliulangqitaorenyuanjiuzhuga35404":[{"i":1,"n":"第一条","txt":"为了对在城市生活无着的流浪、乞讨人员（以下简称流浪乞讨人员）实行救助，保障其基本生活权益，完善社会救助制度，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上城市人民政府应当根据需要设立流浪乞讨人员救助站。救助站对流浪乞讨人员的救助是一项临时性社会救助措施。"},{"i":3,"n":"第三条","txt":"县级以上城市人民政府应当采取积极措施及时救助流浪乞讨人员，并应当将救助工作所需经费列入财政预算，予以保障。"},{"i":4,"n":"第四条","txt":"县级以上人民政府民政部门负责流浪乞讨人员的救助工作，并对救助站进行指导、监督。"},{"i":5,"n":"第五条","txt":"公安机关和其他有关行政机关的工作人员在执行职务时发现流浪乞讨人员的，应当告知其向救助站求助；对其中的残疾人、未成年人、老年人和行动不便的其他人员，还应当引导、护送到救助站。"},{"i":6,"n":"第六条","txt":"向救助站求助的流浪乞讨人员，应当如实提供本人的姓名等基本情况并将随身携带物品在救助站登记，向救助站提出求助需求。"},{"i":7,"n":"第七条","txt":"救助站应当根据受助人员的需要提供下列救助："},{"i":8,"n":"第八条","txt":"救助站为受助人员提供的住处，应当按性别分室住宿，女性受助人员应当由女性工作人员管理。"},{"i":9,"n":"第九条","txt":"救助站应当保障受助人员在站内的人身安全和随身携带物品的安全，维护站内秩序。"},{"i":10,"n":"第十条","txt":"救助站不得向受助人员、其亲属或者所在单位收取费用，不得以任何借口组织受助人员从事生产劳动。"},{"i":11,"n":"第十一条","txt":"救助站应当劝导受助人员返回其住所地或者所在单位，不得限制受助人员离开救助站。救助站对受助的残疾人、未成年人、老年人应当给予照顾；对查明住址的，及时通知其亲属或者所在单位领回；对无家可归的，由其户籍所在地人民政府妥善安置。"},{"i":12,"n":"第十二条","txt":"受助人员住所地的县级人民政府应当采取措施，帮助受助人员解决生产、生活困难，教育遗弃残疾人、未成年人、老年人的近亲属或者其他监护人履行抚养、赡养义务。"},{"i":13,"n":"第十三条","txt":"救助站应当建立、健全站内管理的各项制度，实行规范化管理。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府民政部门应当加强对救助站工作人员的教育、培训和监督。"},{"i":15,"n":"第十五条","txt":"救助站不履行救助职责的，求助人员可以向当地民政部门举报；民政部门经查证属实的，应当责令救助站及时提供救助，并对直接责任人员依法给予纪律处分。"},{"i":16,"n":"第十六条","txt":"受助人员应当遵守法律法规。受助人员违反法律法规的，应当依法处理。"},{"i":17,"n":"第十七条","txt":"本办法的实施细则由国务院民政部门制定。"},{"i":18,"n":"第十八条","txt":"本办法自2003年8月1日起施行。1982年5月12日国务院发布的《城市流浪乞讨人员收容遣送办法》同时废止。"}],"waiguorenzaishouyangzinvdengjibanfa":[{"i":1,"n":"第一条","txt":"为了规范涉外收养登记行为，根据《中华人民共和国民法典》（以下简称民法典），制定本办法。"},{"i":2,"n":"第二条","txt":"外国人在中华人民共和国境内收养子女（以下简称外国人在华收养子女），应当依照本办法办理登记。"},{"i":3,"n":"第三条","txt":"外国人在华收养子女，应当符合中国有关收养法律的规定，并应当符合收养人所在国有关收养法律的规定；因收养人所在国法律的规定与中国法律的规定不一致而产生的问题，由两国政府有关部门协商处理。"},{"i":4,"n":"第四条","txt":"外国人在华收养子女，应当通过所在国政府或者政府委托的收养组织（以下简称外国收养组织）向中国政府委托的收养组织（以下简称中国收养组织）转交收养申请并提交收养人的家庭情况报告和证明。"},{"i":5,"n":"第五条","txt":"送养人应当向省、自治区、直辖市人民政府民政部门提交本人的居民户口簿和居民身份证（社会福利机构作送养人的，应当提交其负责人的身份证件）、被收养人的户籍证明等情况证明，并根据不同情况提交下列有关证明材料："},{"i":6,"n":"第六条","txt":"省、自治区、直辖市人民政府民政部门应当对送养人提交的证件和证明材料进行审查，对查找不到生父母的弃婴和儿童公告查找其生父母；认为被收养人、送养人符合民法典规定条件的，将符合民法典规定的被收养人、送养人名单通知中国收养组织，同时转交下列证件和证明材料："},{"i":7,"n":"第七条","txt":"中国收养组织对外国收养人的收养申请和有关证明进行审查后，应当在省、自治区、直辖市人民政府民政部门报送的符合民法典规定条件的被收养人中，参照外国收养人的意愿，选择适当的被收养人，并将该被收养人及其送养人的有关情况通过外国政府或者外国收养组织送交外国收养人。外国收养人同意收养的，中国收养组织向其发出来华收养子女通知书，同时通知有关的省、自治区、直辖市人民政府民政部门向送养人发出被收养人已被同意收养的通知。"},{"i":8,"n":"第八条","txt":"外国人来华收养子女，应当亲自来华办理登记手续。夫妻共同收养的，应当共同来华办理收养手续；一方因故不能来华的，应当书面委托另一方。委托书应当经所在国公证和认证。中华人民共和国缔结或者参加的国际条约另有规定的，按照国际条约规定的证明手续办理。"},{"i":9,"n":"第九条","txt":"外国人来华收养子女，应当与送养人订立书面收养协议。协议一式三份，收养人、送养人各执一份，办理收养登记手续时收养登记机关收存一份。"},{"i":10,"n":"第十条","txt":"收养关系当事人办理收养登记时，应当填写外国人来华收养子女登记申请书并提交收养协议，同时分别提供有关材料。"},{"i":11,"n":"第十一条","txt":"收养登记机关收到外国人来华收养子女登记申请书和收养人、被收养人及其送养人的有关材料后，应当自次日起7日内进行审查，对符合本办法第十条规定的，为当事人办理收养登记，发给收养登记证书。收养关系自登记之日起成立。"},{"i":12,"n":"第十二条","txt":"收养关系当事人办理收养登记后，各方或者一方要求办理收养公证的，应当到收养登记地的具有办理涉外公证资格的公证机构办理收养公证。"},{"i":13,"n":"第十三条","txt":"被收养人出境前，收养人应当凭收养登记证书到收养登记地的公安机关为被收养人办理出境手续。"},{"i":14,"n":"第十四条","txt":"外国人在华收养子女，应当向登记机关交纳登记费。登记费的收费标准按照国家有关规定执行。"},{"i":15,"n":"第十五条","txt":"中国收养组织的活动受国务院民政部门监督。"},{"i":16,"n":"第十六条","txt":"本办法自发布之日起施行。1993年11月3日国务院批准，1993年11月10日司法部、民政部发布的《外国人在中华人民共和国收养子女实施办法》同时废止。"}],"waiguorenlaihuadengshanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对外国人在中国境内登山的管理，有组织地进行国际登山交流，促进我国登山事业发展，制定本办法。"},{"i":2,"n":"第二条","txt":"外国人在中国境内攀登下列对外开放的山峰以及附带在山峰区域内进行科学考察、测绘活动，适用本办法："},{"i":3,"n":"第三条","txt":"外国人在中国境内进行登山活动，应当遵守中国的法律；外国人的正当权益，受中国法律保护。"},{"i":4,"n":"第四条","txt":"对外国人在中国境内登山的管理，实行统一领导，分级负责的原则。"},{"i":5,"n":"第五条","txt":"对外开放山峰由中华人民共和国国家体育运动委员会（以下简称国家体委）和公安部公布。"},{"i":6,"n":"第六条","txt":"外国人来华登山，可以自行组成团队，也可以由外国团队和中国团队组成联合团队。"},{"i":7,"n":"第七条","txt":"外国人来华登山，应当向国家体委提出书面申请。"},{"i":8,"n":"第八条","txt":"国家体委收到外国团队或者中外联合团队的登山申请后，应当在六十日内作出是否批准的决定，并以书面形式通知外国团队或者中外联合团队、代理申请事宜的省、自治区登山协会和登山活动所在省、自治区体委。"},{"i":9,"n":"第九条","txt":"外国团队接到国家体委批准的登山通知后，应当按照通知要求缴纳注册费，并与通知中指定的单位签订登山议定书。"},{"i":10,"n":"第十条","txt":"议定书报送国家体委备案后，不得任意变更。如需要变更，应当经签订议定书的中外双方协商确认；如果变更攀登的季节、路线或者山峰，应当重新报国家体委审批。"},{"i":11,"n":"第十一条","txt":"外国团队应当在入境的一个月前，将在中国境内登山的经费按预算全额汇寄中方签约单位，并按照国家体委的通知在中国驻外使（领）馆办理签证。"},{"i":12,"n":"第十二条","txt":"外国团队在登山前应当为随队的中国公民办理有关保险事项，并根据国家体委的要求落实保护山区自然环境的各项措施。"},{"i":13,"n":"第十三条","txt":"外国人登山，应当遵守下列规定："},{"i":14,"n":"第十四条","txt":"外国人在登山活动结束后，应当以团队为单位写出总结报告书。"},{"i":15,"n":"第十五条","txt":"外国人在我国境内登顶成功，由国家体委确认后，发给其登顶证明书。"},{"i":16,"n":"第十六条","txt":"外国人在我国境内登山期间，必须有我国联络人员陪同。联络人员由中方签约单位指定，其职责是："},{"i":17,"n":"第十七条","txt":"外国人登山，需要我国公民提供服务，由我国联络人员办理。"},{"i":18,"n":"第十八条","txt":"外国团队应当为随队的中国公民提供医疗、急救以及必要的宿营、炊事用具。"},{"i":19,"n":"第十九条","txt":"登山附带科学考察和测绘的，应当在办理登山申请的同时，向国家体委申报科学考察和测绘计划，由国家体委分别转国家科学技术委员会或者国家测绘局审批。"},{"i":20,"n":"第二十条","txt":"外国团队、中外联合团队登山附带科学考察的，应当通过中方签约单位向国家科学技术委员会提供下列样品和资料："},{"i":21,"n":"第二十一条","txt":"外国人携带登山所需物资入境，按“特准进口物品”和“暂时进口物品”分别申报。经海关核准后，办理税收、担保手续。"},{"i":22,"n":"第二十二条","txt":"登山物资中合理数量的专用食品、急救药品、防寒衣物、燃料等消耗性物品，可以特准免税入境；超过合理数量的，应当纳税。"},{"i":23,"n":"第二十三条","txt":"外国团队、中外联合团队登山时采集的标本、样品、化石以及制作的音像资料，经有关部门检验许可后，方可携带出境。"},{"i":24,"n":"第二十四条","txt":"外国人来华登山，违反本办法第十二条、第十三条、第十八条、第十九条、第二十条规定或者未经国家体委批准擅自登山的，国家体委或者省、自治区体委视情节轻重，可以分别给予警告、五千元至五万元的罚款以及停止登山活动等处罚。"},{"i":25,"n":"第二十五条","txt":"当事人对行政处罚决定不服的，可以依照中国有关法律的规定先申请行政复议。当事人对复议决定不服的，可以依照中国有关法律的规定提起行政诉讼。当事人在规定的期限内不申请复议和不提起行政诉讼，逾期又不履行处罚决定的，作出处罚决定的行政机关可以申请人民法院强制执行。"},{"i":26,"n":"第二十六条","txt":"台湾、香港、澳门同胞回大陆登山，参照执行本办法的规定。"},{"i":27,"n":"第二十七条","txt":"本办法由国家体育运动委员会解释。"},{"i":28,"n":"第二十八条","txt":"本办法自发布之日起施行。"}],"duichuxucunkuanlixisuodezhengshougerensuodeshuides2d7db9":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国个人所得税法》第十二条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"从中华人民共和国境内的储蓄机构取得人民币、外币储蓄存款利息所得的个人，应当依照本办法缴纳个人所得税。"},{"i":3,"n":"第三条","txt":"对储蓄存款利息所得征收个人所得税的计税依据为纳税人取得的人民币、外币储蓄存款利息所得。"},{"i":4,"n":"第四条","txt":"对储蓄存款利息所得征收个人所得税，减按5%的比例税率执行。减征幅度的调整由国务院决定。"},{"i":5,"n":"第五条","txt":"对个人取得的教育储蓄存款利息所得以及国务院财政部门确定的其他专项储蓄存款或者储蓄性专项基金存款的利息所得，免征个人所得税。"},{"i":6,"n":"第六条","txt":"对储蓄存款利息所得，按照每次取得的利息所得额计征个人所得税。"},{"i":7,"n":"第七条","txt":"对储蓄存款利息所得征收个人所得税，以结付利息的储蓄机构为扣缴义务人，实行代扣代缴。"},{"i":8,"n":"第八条","txt":"扣缴义务人在向储户结付利息时，依法代扣代缴税款。"},{"i":9,"n":"第九条","txt":"扣缴义务人每月代扣的税款，应当在次月7日内缴入中央国库，并向当地主管税务机关报送代扣代缴税款报告表；代扣的税款为外币的，应当折合成人民币缴入中央国库。"},{"i":10,"n":"第十条","txt":"对扣缴义务人按照所扣缴的税款，付给2%的手续费。"},{"i":11,"n":"第十一条","txt":"税务机关应当加强对扣缴义务人代扣代缴税款情况的监督和检查，扣缴义务人应当积极予以配合，如实反映情况，提供有关资料，不得拒绝、隐瞒。"},{"i":12,"n":"第十二条","txt":"对储蓄存款利息所得征收的个人所得税，由国家税务局依照《中华人民共和国税收征收管理法》、《中华人民共和国个人所得税法》及本办法的规定负责征收管理。"},{"i":13,"n":"第十三条","txt":"本办法所称储蓄机构，是指经国务院银行业监督管理机构批准的商业银行、城市信用合作社和农村信用合作社等吸收公众存款的金融机构。"},{"i":14,"n":"第十四条","txt":"储蓄存款在1999年10月31日前孳生的利息所得，不征收个人所得税；储蓄存款在1999年11月1日至2007年8月14日孳生的利息所得，按照20%的比例税率征收个人所得税；储蓄存款在2007年8月15日后孳生的利息所得，按照5%的比例税率征收个人所得税。"},{"i":15,"n":"第十五条","txt":"本办法自1999年11月1日起施行。"}],"duiwaishiyongguohuituandebanfa":[{"i":1,"n":"第一条","txt":"为了在对外活动中正确使用中华人民共和国国徽图案，根据《中华人民共和国国徽法》（以下简称国徽法），制定本办法。"},{"i":2,"n":"第二条","txt":"外事活动和国家驻外使馆、领馆以及其他外交代表机构对外使用国徽图案，适用本办法。"},{"i":3,"n":"第三条","txt":"为全国人民代表大会常务委员会、国务院、中央军事委员会、国家监察委员会、最高人民法院、最高人民检察院印制的外交文书和对外使用的信封、信笺，应当印有国徽图案。"},{"i":4,"n":"第四条","txt":"外交部以及国家驻外使馆、领馆和其他外交代表机构使用的外交文书和对外使用的信封、信笺，应当印有国徽图案。"},{"i":5,"n":"第五条","txt":"国防部使用的外交文书和对外使用的信封、信笺，国防部部长使用的外交文书和以职务名义对外使用的信封、信笺、请柬、贺卡、赠礼卡等，以及以国防部名义对外举行的建军节招待会请柬等，根据需要可以印有国徽图案。"},{"i":6,"n":"第六条","txt":"中央人民政府驻香港特别行政区有关机构、中央人民政府驻澳门特别行政区有关机构使用的外交文书和对外使用的信封、信笺，以及上述机构的正职负责人使用的外交文书和以职务名义对外使用的信封、信笺、请柬、贺卡、赠礼卡等，根据需要可以印有国徽图案。"},{"i":7,"n":"第七条","txt":"以省、自治区、直辖市人民政府名义对外举行的国庆招待会请柬等，根据需要可以印有国徽图案。"},{"i":8,"n":"第八条","txt":"下列机构对外使用的印章可以刻有国徽图案："},{"i":9,"n":"第九条","txt":"下列证件、文书等应当印有国徽图案或者印有带国徽图案的印章："},{"i":10,"n":"第十条","txt":"以中华人民共和国、中华人民共和国政府或者中华人民共和国政府部门名义缔结的条约、协定，可以加封带有国徽图案的火漆印；上述条约、协定的批准书、核准书、接受书、加入书以及条约夹的封面，应当印有国徽图案。"},{"i":11,"n":"第十一条","txt":"国家体育、技能竞赛代表团、队参加国际体育比赛、技能竞赛时，可以按照有关规定在其人员的服装上使用国徽图案。"},{"i":12,"n":"第十二条","txt":"标示国界线的界桩、界碑和标示领海基点方位的标志碑以及其他用于显示国家主权的标志物可以使用国徽图案。"},{"i":13,"n":"第十三条","txt":"外交部具体负责指导对外使用国徽图案有关工作。"},{"i":14,"n":"第十四条","txt":"本办法自公布之日起施行。"}],"guangbodiantaidianshitaibofangluyinzhipinzhifubaoc0bdef4":[{"i":1,"n":"第一条","txt":"为了保障著作权人依法行使广播权，方便广播电台、电视台播放录音制品，根据《中华人民共和国著作权法》（以下称著作权法）第四十四条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"广播电台、电视台可以就播放已经发表的音乐作品向著作权人支付报酬的方式、数额等有关事项与管理相关权利的著作权集体管理组织进行约定。"},{"i":3,"n":"第三条","txt":"本办法所称播放，是指广播电台、电视台以无线或者有线的方式进行的首播、重播和转播。"},{"i":4,"n":"第四条","txt":"广播电台、电视台播放录音制品，可以与管理相关权利的著作权集体管理组织约定每年向著作权人支付固定数额的报酬；没有就固定数额进行约定或者约定不成的，广播电台、电视台与管理相关权利的著作权集体管理组织可以以下列方式之一为基础，协商向著作权人支付报酬："},{"i":5,"n":"第五条","txt":"以本办法第四条第（一）项规定方式确定向著作权人支付报酬的数额的，自本办法施行之日起5年内，按照下列付酬标准协商支付报酬的数额："},{"i":6,"n":"第六条","txt":"以本办法第四条第（一）项规定方式确定向著作权人支付报酬的数额的，自本办法施行届满5年之日起，按照下列付酬标准协商支付报酬的数额："},{"i":7,"n":"第七条","txt":"以本办法第四条第（二）项规定的方式确定向著作权人支付报酬的数额的，按照下列付酬标准协商支付报酬的数额："},{"i":8,"n":"第八条","txt":"广播电台、电视台播放录音制品，未能依照本办法第四条的规定与管理相关权利的著作权集体管理组织约定支付报酬的固定数额，也未能协商确定应支付报酬的，应当依照本办法第四条第（一）项规定的方式和第五条、第六条规定的标准，确定向管理相关权利的著作权集体管理组织支付报酬的数额。"},{"i":9,"n":"第九条","txt":"广播电台、电视台转播其他广播电台、电视台播放的录音制品的，其播放录音制品的时间按照实际播放时间的10%计算。"},{"i":10,"n":"第十条","txt":"中部地区的广播电台、电视台依照本办法规定方式向著作权人支付报酬的数额，自本办法施行之日起5年内，按照依据本办法规定计算出的数额的50%计算。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府财政部门将本级人民政府设立的广播电台、电视台播放录音制品向著作权人支付报酬的支出作为核定其收支的因素，根据本地区财政情况综合考虑，统筹安排。"},{"i":12,"n":"第十二条","txt":"广播电台、电视台向著作权人支付报酬，以年度为结算期。"},{"i":13,"n":"第十三条","txt":"广播电台、电视台播放录音制品，未向管理相关权利的著作权集体管理组织会员以外的著作权人支付报酬的，应当按照本办法第十二条的规定将应支付的报酬送交管理相关权利的著作权集体管理组织；管理相关权利的著作权集体管理组织应当向著作权人转付。"},{"i":14,"n":"第十四条","txt":"著作权集体管理组织向著作权人转付报酬，除本办法已有规定外，适用《著作权集体管理条例》的有关规定。"},{"i":15,"n":"第十五条","txt":"广播电台、电视台依照本办法规定将应当向著作权人支付的报酬交给著作权集体管理组织后，对著作权集体管理组织与著作权人之间的纠纷不承担责任。"},{"i":16,"n":"第十六条","txt":"广播电台、电视台与著作权人或者著作权集体管理组织因依照本办法规定支付报酬产生纠纷的，可以依法向人民法院提起民事诉讼，或者根据双方达成的书面仲裁协议向仲裁机构申请仲裁。"},{"i":17,"n":"第十七条","txt":"本办法自2010年1月1日起施行。"}],"feijiujinshushougouyezhianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对废旧金属收购业的治安管理，保护合法经营，预防和打击违法犯罪活动，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称废旧金属，是指生产性废旧金属和非生产性废旧金属。生产性废旧金属和非生产性废旧金属的具体分类由公安部会同有关部门规定。"},{"i":3,"n":"第三条","txt":"生产性废旧金属，按照国务院有关规定由有权经营生产性废旧金属收购业的企业收购。收购废旧金属的其他企业和个体工商户只能收购非生产性废旧金属，不得收购生产性废旧金属。"},{"i":4,"n":"第四条","txt":"收购废旧金属的企业和个体工商户，应当在取得营业执照后15日内向所在地县级人民政府公安机关备案。"},{"i":5,"n":"第五条","txt":"收购废旧金属的企业应当有固定的经营场所。收购废旧金属的个体工商户应当有所在地常住户口或者暂住户口。"},{"i":6,"n":"第六条","txt":"在铁路、矿区、油田、港口、机场、施工工地、军事禁区和金属冶炼加工企业附近，不得设点收购废旧金属。"},{"i":7,"n":"第七条","txt":"收购废旧金属的企业在收购生产性废旧金属时，应当查验出售单位开具的证明，对出售单位的名称和经办人的姓名、住址、身份证号码以及物品的名称、数量、规格、新旧程度等如实进行登记。"},{"i":8,"n":"第八条","txt":"收购废旧金属的企业和个体工商户不得收购下列金属物品："},{"i":9,"n":"第九条","txt":"收购废旧金属的企业和个体工商户发现有出售公安机关通报寻查的赃物或者有赃物嫌疑的物品的，应当立即报告公安机关。"},{"i":10,"n":"第十条","txt":"公安机关应当对收购废旧金属的企业和个体工商户进行治安业务指导和检查。收购企业和个体工商户应当协助公安人员查处违法犯罪分子，据实反映情况，不得知情不报或者隐瞒包庇。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，由公安机关给予相应处罚："},{"i":12,"n":"第十二条","txt":"当事人对公安机关作出的具体行政行为不服的，可以自得知该具体行政行为之日起15日内向上一级公安机关申请复议；对复议决定不服的，可以自接到复议决定通知之日起15日内向人民法院提起诉讼。"},{"i":13,"n":"第十三条","txt":"对严格执行本办法，协助公安机关查获违法犯罪分子，作出显著成绩的单位和个人，由公安机关给予表彰或者奖励。"},{"i":14,"n":"第十四条","txt":"本办法自发布之日起施行。"}],"baofeijidongchehuishouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范报废机动车回收活动，保护环境，促进循环经济发展，保障道路交通安全，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称报废机动车，是指根据《中华人民共和国道路交通安全法》的规定应当报废的机动车。"},{"i":3,"n":"第三条","txt":"国家鼓励特定领域的老旧机动车提前报废更新，具体办法由国务院有关部门另行制定。"},{"i":4,"n":"第四条","txt":"国务院负责报废机动车回收管理的部门主管全国报废机动车回收（含拆解，下同）监督管理工作，国务院公安、生态环境、工业和信息化、交通运输、市场监督管理等部门在各自的职责范围内负责报废机动车回收有关的监督管理工作。"},{"i":5,"n":"第五条","txt":"国家对报废机动车回收企业实行资质认定制度。未经资质认定，任何单位或者个人不得从事报废机动车回收活动。"},{"i":6,"n":"第六条","txt":"取得报废机动车回收资质认定，应当具备下列条件："},{"i":7,"n":"第七条","txt":"拟从事报废机动车回收活动的，应当向省、自治区、直辖市人民政府负责报废机动车回收管理的部门提出申请。省、自治区、直辖市人民政府负责报废机动车回收管理的部门应当依法进行审查，对符合条件的，颁发资质认定书；对不符合条件的，不予资质认定并书面说明理由。"},{"i":8,"n":"第八条","txt":"任何单位或者个人不得要求机动车所有人将报废机动车交售给指定的报废机动车回收企业。"},{"i":9,"n":"第九条","txt":"报废机动车回收企业对回收的报废机动车，应当向机动车所有人出具《报废机动车回收证明》，收回机动车登记证书、号牌、行驶证，并按照国家有关规定及时向公安机关交通管理部门办理注销登记，将注销证明转交机动车所有人。"},{"i":10,"n":"第十条","txt":"报废机动车回收企业对回收的报废机动车，应当逐车登记机动车的型号、号牌号码、发动机号码、车辆识别代号等信息；发现回收的报废机动车疑似赃物或者用于盗窃、抢劫等犯罪活动的犯罪工具的，应当及时向公安机关报告。"},{"i":11,"n":"第十一条","txt":"回收的报废机动车必须按照有关规定予以拆解；其中，回收的报废大型客车、货车等营运车辆和校车，应当在公安机关的监督下解体。"},{"i":12,"n":"第十二条","txt":"拆解的报废机动车“五大总成”具备再制造条件的，可以按照国家有关规定出售给具有再制造能力的企业经过再制造予以循环利用；不具备再制造条件的，应当作为废金属，交售给钢铁企业作为冶炼原料。"},{"i":13,"n":"第十三条","txt":"国务院负责报废机动车回收管理的部门应当建立报废机动车回收信息系统。报废机动车回收企业应当如实记录本企业回收的报废机动车“五大总成”等主要部件的数量、型号、流向等信息，并上传至报废机动车回收信息系统。"},{"i":14,"n":"第十四条","txt":"拆解报废机动车，应当遵守环境保护法律、法规和强制性标准，采取有效措施保护环境，不得造成环境污染。"},{"i":15,"n":"第十五条","txt":"禁止任何单位或者个人利用报废机动车“五大总成”和其他零部件拼装机动车，禁止拼装的机动车交易。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府负责报废机动车回收管理的部门应当加强对报废机动车回收企业的监督检查，建立和完善以随机抽查为重点的日常监督检查制度，公布抽查事项目录，明确抽查的依据、频次、方式、内容和程序，随机抽取被检查企业，随机选派检查人员。抽查情况和查处结果应当及时向社会公布。"},{"i":17,"n":"第十七条","txt":"县级以上地方人民政府负责报废机动车回收管理的部门应当向社会公布本部门的联系方式，方便公众举报违法行为。"},{"i":18,"n":"第十八条","txt":"负责报废机动车回收管理的部门在监督管理工作中发现不属于本部门处理权限的违法行为的，应当及时移交有权处理的部门；有权处理的部门应当及时依法调查处理，并将处理结果告知负责报废机动车回收管理的部门。"},{"i":19,"n":"第十九条","txt":"未取得资质认定，擅自从事报废机动车回收活动的，由负责报废机动车回收管理的部门没收非法回收的报废机动车、报废机动车“五大总成”和其他零部件，没收违法所得；违法所得在5万元以上的，并处违法所得2倍以上5倍以下的罚款；违法所得不足5万元或者没有违法所得的，并处5万元以上10万元以下的罚款。对负责报废机动车回收管理的部门没收非法回收的报废机动车、报废机动车“五大总成”和其他零部件，必要时有关主管部门应当予以配合。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，由公安机关依法给予治安管理处罚："},{"i":21,"n":"第二十一条","txt":"报废机动车回收企业有下列情形之一的，由负责报废机动车回收管理的部门责令改正，没收报废机动车“五大总成”和其他零部件，没收违法所得；违法所得在5万元以上的，并处违法所得2倍以上5倍以下的罚款；违法所得不足5万元或者没有违法所得的，并处5万元以上10万元以下的罚款；情节严重的，责令停业整顿直至由原发证部门吊销资质认定书："},{"i":22,"n":"第二十二条","txt":"报废机动车回收企业对回收的报废机动车，未按照国家有关规定及时向公安机关交通管理部门办理注销登记并将注销证明转交机动车所有人的，由负责报废机动车回收管理的部门责令改正，可以处1万元以上5万元以下的罚款。"},{"i":23,"n":"第二十三条","txt":"报废机动车回收企业未如实记录本企业回收的报废机动车“五大总成”等主要部件的数量、型号、流向等信息并上传至报废机动车回收信息系统的，由负责报废机动车回收管理的部门责令改正，并处1万元以上5万元以下的罚款；情节严重的，责令停业整顿。"},{"i":24,"n":"第二十四条","txt":"报废机动车回收企业违反环境保护法律、法规和强制性标准，污染环境的，由生态环境主管部门责令限期改正，并依法予以处罚；拒不改正或者逾期未改正的，由原发证部门吊销资质认定书。"},{"i":25,"n":"第二十五条","txt":"负责报废机动车回收管理的部门和其他有关部门的工作人员在监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"报废新能源机动车回收的特殊事项，另行制定管理规定。"},{"i":28,"n":"第二十八条","txt":"本办法自2019年6月1日起施行。2001年6月16日国务院公布的《报废汽车回收管理办法》同时废止。"}],"fangshexingyaopinguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强放射性药品的管理，根据《中华人民共和国药品管理法》（以下称《药品管理法》）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。"},{"i":3,"n":"第三条","txt":"凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。"},{"i":4,"n":"第四条","txt":"国务院药品监督管理部门负责全国放射性药品监督管理工作。国务院国防科技工业主管部门依据职责负责与放射性药品有关的管理工作。国务院环境保护主管部门负责与放射性药品有关的辐射安全与防护的监督管理工作。"},{"i":5,"n":"第五条","txt":"放射性新药的研制内容，包括工艺路线、质量标准、临床前药理及临床研究。研制单位在制订新药工艺路线的同时，必须研究该药的理化性能、纯度（包括核素纯度）及检验方法、药理、毒理、动物药代动力学、放射性比活度、剂量、剂型、稳定性等。"},{"i":6,"n":"第六条","txt":"研制单位研制的放射性新药，在进行临床试验或者验证前，应当向国务院药品监督管理部门提出申请，按规定报送资料及样品，经国务院药品监督管理部门审批同意后，在国务院药品监督管理部门指定的药物临床试验机构进行临床研究。"},{"i":7,"n":"第七条","txt":"研制单位在放射性新药临床研究结束后，向国务院药品监督管理部门提出申请，经国务院药品监督管理部门审核批准，发给新药证书。国务院药品监督管理部门在审核批准时，应当征求国务院国防科技工业主管部门的意见。"},{"i":8,"n":"第八条","txt":"放射性新药投入生产，需由生产单位或者取得放射性药品生产许可证的研制单位，凭新药证书（副本）向国务院药品监督管理部门提出生产该药的申请，并提供样品，由国务院药品监督管理部门审核发给批准文号。"},{"i":9,"n":"第九条","txt":"国家根据需要，对放射性药品的生产企业实行合理布局。"},{"i":10,"n":"第十条","txt":"开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续；开办放射性药品生产企业，经所在省、自治区、直辖市国防科技工业主管部门审查同意，所在省、自治区、直辖市药品监督管理部门审核批准后，由所在省、自治区、直辖市药品监督管理部门发给《放射性药品生产企业许可证》；开办放射性药品经营企业，经所在省、自治区、直辖市药品监督管理部门审核并征求所在省、自治区、直辖市国防科技工业主管部门意见后批准的，由所在省、自治区、直辖市药品监督管理部门发给《放射性药品经营企业许可证》。无许可证的生产、经营企业，一律不准生产、销售放射性药品。"},{"i":11,"n":"第十一条","txt":"《放射性药品生产企业许可证》、《放射性药品经营企业许可证》的有效期为5年，期满前6个月，放射性药品生产、经营企业应当分别向原发证的药品监督管理部门重新提出申请，按第十条审批程序批准后，换发新证。"},{"i":12,"n":"第十二条","txt":"放射性药品生产企业生产已有国家标准的放射性药品，必须经国务院药品监督管理部门征求国务院国防科技工业主管部门意见后审核批准，并发给批准文号。凡是改变国务院药品监督管理部门已批准的生产工艺路线和药品标准的，生产单位必须按原报批程序提出补充申请，经国务院药品监督管理部门批准后方能生产。"},{"i":13,"n":"第十三条","txt":"放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。"},{"i":14,"n":"第十四条","txt":"放射性药品生产、经营企业，必须建立质量检验机构，严格实行生产全过程的质量控制和检验。产品出厂前，须经质量检验。符合国家药品标准的产品方可出厂，不符合标准的产品一律不准出厂。"},{"i":15,"n":"第十五条","txt":"进口的放射性药品品种，必须符合我国的药品标准或者其他药用要求，并依照《药品管理法》的规定取得进口药品注册证书。"},{"i":16,"n":"第十六条","txt":"进口放射性药品，必须经国务院药品监督管理部门指定的药品检验机构抽样检验；检验合格的，方准进口。"},{"i":17,"n":"第十七条","txt":"放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。"},{"i":18,"n":"第十八条","txt":"放射性药品的运输，按国家运输、邮政等部门制订的有关规定执行。"},{"i":19,"n":"第十九条","txt":"医疗单位设置核医学科、室（同位素室），必须配备与其医疗任务相适应的并经核医学技术培训的技术人员。非核医学专业技术人员未经培训，不得从事放射性药品使用工作。"},{"i":20,"n":"第二十条","txt":"医疗单位使用放射性药品应当符合国家有关放射性同位素安全和防护的规定，具有与所使用放射性药品相适应的场所、设备、卫生环境和专用的仓储设施。"},{"i":21,"n":"第二十一条","txt":"医疗单位配制放射性制剂，应当符合《药品管理法》及其实施条例的相关规定。"},{"i":22,"n":"第二十二条","txt":"医疗单位负责对使用的放射性药品进行临床质量检验、收集药品不良反应等项工作，并定期向所在地药品监督管理、卫生行政部门报告。由省、自治区、直辖市药品监督管理、卫生行政部门汇总后分别报国务院药品监督管理、卫生行政部门。"},{"i":23,"n":"第二十三条","txt":"放射性药品使用后的废物（包括患者排出物），必须按国家有关规定妥善处置。"},{"i":24,"n":"第二十四条","txt":"放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。"},{"i":25,"n":"第二十五条","txt":"放射性药品的检验由国务院药品监督管理部门公布的药品检验机构承担。"},{"i":26,"n":"第二十六条","txt":"对违反本办法规定的单位或者个人，由县以上药品监督管理、卫生行政部门，按照《药品管理法》和有关法规的规定处罚。"},{"i":27,"n":"第二十七条","txt":"本办法自发布之日起施行。"}],"lvguanyezhianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保障旅馆业的正常经营和旅客的生命财物安全，维护社会治安，制定本办法。"},{"i":2,"n":"第二条","txt":"凡经营接待旅客住宿的旅馆、饭店、宾馆、招待所、客货栈、车马店、浴池等（以下统称旅馆），不论是国营、集体经营，还是合伙经营、个体经营、外商投资经营，不论是专营还是兼营，不论是常年经营，还是季节性经营，都必须遵守本办法。"},{"i":3,"n":"第三条","txt":"开办旅馆，要具备必要的防盗等安全设施。"},{"i":4,"n":"第四条","txt":"申请开办旅馆，应取得市场监管部门核发的营业执照，向当地公安机关申领特种行业许可证后，方准开业。"},{"i":5,"n":"第五条","txt":"经营旅馆，必须遵守国家的法律，建立各项安全管理制度，设置治安保卫组织或者指定安全保卫人员。"},{"i":6,"n":"第六条","txt":"旅馆接待旅客住宿必须登记。登记时，应当查验旅客的身份证件，按规定的项目如实登记。"},{"i":7,"n":"第七条","txt":"旅馆应当设置旅客财物保管箱、柜或者保管室、保险柜，指定专人负责保管工作。对旅客寄存的财物，要建立登记、领取和交接制度。"},{"i":8,"n":"第八条","txt":"旅馆对旅客遗留的物品，应当妥为保管，设法归还原主或揭示招领；经招领3个月后无人认领的，要登记造册，送当地公安机关按拾遗物品处理。对违禁物品和可疑物品，应当及时报告公安机关处理。"},{"i":9,"n":"第九条","txt":"旅馆工作人员发现违法犯罪分子，行迹可疑的人员和被公安机关通缉的罪犯，应当立即向当地公安机关报告，不得知情不报或隐瞒包庇。"},{"i":10,"n":"第十条","txt":"在旅馆内开办舞厅、音乐茶座等娱乐、服务场所的，除执行本办法有关规定外，还应当按照国家和当地政府的有关规定管理。"},{"i":11,"n":"第十一条","txt":"严禁旅客将易燃、易爆、剧毒、腐蚀性和放射性等危险物品带入旅馆。"},{"i":12,"n":"第十二条","txt":"旅馆内，严禁卖淫、嫖宿、赌博、吸毒、传播淫秽物品等违法犯罪活动。"},{"i":13,"n":"第十三条","txt":"旅馆内，不得酗酒滋事、大声喧哗，影响他人休息，旅客不得私自留客住宿或者转让床位。"},{"i":14,"n":"第十四条","txt":"公安机关对旅馆治安管理的职责是，指导、监督旅馆建立各项安全管理制度和落实安全防范措施，协助旅馆对工作人员进行安全业务知识的培训，依法惩办侵犯旅馆和旅客合法权益的违法犯罪分子。"},{"i":15,"n":"第十五条","txt":"违反本办法第四条规定开办旅馆的，公安机关可以酌情给予警告或者处以200元以下罚款；未经登记，私自开业的，公安机关应当协助工商行政管理部门依法处理。"},{"i":16,"n":"第十六条","txt":"旅馆工作人员违反本办法第九条规定的，公安机关可以酌情给予警告或者处以200元以下罚款；情节严重构成犯罪的，依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"违反本办法第六、十一、十二条规定的，依照《中华人民共和国治安管理处罚法》有关条款的规定，处罚有关人员；发生重大事故、造成严重后果构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"当事人对公安机关的行政处罚决定不服的，按照《中华人民共和国治安管理处罚法》第一百零二条的规定办理。"},{"i":19,"n":"第十九条","txt":"省、自治区、直辖市公安厅（局）可根据本办法制定实施细则，报请当地人民政府批准后施行，并报公安部备案。"},{"i":20,"n":"第二十条","txt":"本办法自公布之日起施行。1951年8月15日公布的《城市旅栈业暂行管理规则》同时废止。"}],"wuzhengwuzhaojingyingchachubanfa":[{"i":1,"n":"第一条","txt":"为了维护社会主义市场经济秩序，促进公平竞争，保护经营者和消费者的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"任何单位或者个人不得违反法律、法规、国务院决定的规定，从事无证无照经营。"},{"i":3,"n":"第三条","txt":"下列经营活动，不属于无证无照经营："},{"i":4,"n":"第四条","txt":"县级以上地方人民政府负责组织、协调本行政区域的无证无照经营查处工作，建立有关部门分工负责、协调配合的无证无照经营查处工作机制。"},{"i":5,"n":"第五条","txt":"经营者未依法取得许可从事经营活动的，由法律、法规、国务院决定规定的部门予以查处；法律、法规、国务院决定没有规定或者规定不明确的，由省、自治区、直辖市人民政府确定的部门予以查处。"},{"i":6,"n":"第六条","txt":"经营者未依法取得营业执照从事经营活动的，由履行工商行政管理职责的部门（以下称工商行政管理部门）予以查处。"},{"i":7,"n":"第七条","txt":"经营者未依法取得许可且未依法取得营业执照从事经营活动的，依照本办法第五条的规定予以查处。"},{"i":8,"n":"第八条","txt":"工商行政管理部门以及法律、法规、国务院决定规定的部门和省、自治区、直辖市人民政府确定的部门（以下统称查处部门）应当依法履行职责，密切协同配合，利用信息网络平台加强信息共享；发现不属于本部门查处职责的无证无照经营，应当及时通报有关部门。"},{"i":9,"n":"第九条","txt":"任何单位或者个人有权向查处部门举报无证无照经营。"},{"i":10,"n":"第十条","txt":"查处部门依法查处无证无照经营，应当坚持查处与引导相结合、处罚与教育相结合的原则，对具备办理证照的法定条件、经营者有继续经营意愿的，应当督促、引导其依法办理相应证照。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府工商行政管理部门对涉嫌无照经营进行查处，可以行使下列职权："},{"i":12,"n":"第十二条","txt":"从事无证经营的，由查处部门依照相关法律、法规的规定予以处罚。"},{"i":13,"n":"第十三条","txt":"从事无照经营的，由工商行政管理部门依照相关法律、行政法规的规定予以处罚。法律、行政法规对无照经营的处罚没有明确规定的，由工商行政管理部门责令停止违法行为，没收违法所得，并处1万元以下的罚款。"},{"i":14,"n":"第十四条","txt":"明知属于无照经营而为经营者提供经营场所，或者提供运输、保管、仓储等条件的，由工商行政管理部门责令停止违法行为，没收违法所得，可以处5000元以下的罚款。"},{"i":15,"n":"第十五条","txt":"任何单位或者个人从事无证无照经营的，由查处部门记入信用记录，并依照相关法律、法规的规定予以公示。"},{"i":16,"n":"第十六条","txt":"妨害查处部门查处无证无照经营，构成违反治安管理行为的，由公安机关依照《中华人民共和国治安管理处罚法》的规定予以处罚。"},{"i":17,"n":"第十七条","txt":"查处部门及其工作人员滥用职权、玩忽职守、徇私舞弊的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":18,"n":"第十八条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"本办法自2017年10月1日起施行。2003年1月6日国务院公布的《无照经营查处取缔办法》同时废止。"}],"youxiandianshiguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了加强有线电视的管理，宣传国家的法律和方针政策，传播科学文化知识，丰富人民的精神生活，促进社会主义物质文明和精神文明建设，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的有线电视，是指下列利用电缆或者光缆传送电视节目的公共电视传输系统："},{"i":3,"n":"第三条","txt":"国务院广播电视行政管理部门负责全国有线电视管理工作和有线电视事业发展规划。"},{"i":4,"n":"第四条","txt":"机关、部队、团体、企业事业单位，符合下列条件的，可以申请开办有线电视台："},{"i":5,"n":"第五条","txt":"单位或者个人设置共用天线系统，必须健全管理措施或者配备管理人员，必须使用省级以上广播电视行政管理部门根据国家有关技术标准认定合格的传输设备。"},{"i":6,"n":"第六条","txt":"开办有线电视台，必须经省级广播电视行政管理部门初步审查同意后，报国务院广播电视行政管理部门批准，由国务院广播电视行政管理部门发给《有线电视台许可证》。"},{"i":7,"n":"第七条","txt":"工程设计、安装单位承担有线电视台的工程设计、安装任务的，必须经省级广播电视行政管理部门批准，由省级广播电视行政管理部门发给《有线电视台设计（安装）许可证》。"},{"i":8,"n":"第八条","txt":"有线电视台、有线电视站工程竣工后，由省级广播电视行政管理部门组织或者委托有关单位验收。未经验收或者验收不合格的，不得投入使用。"},{"i":9,"n":"第九条","txt":"有线电视台、有线电视站播映的电视节目必须符合有关法律、法规和国家有关部门关于电视节目和录像制品的规定。严禁播映反动、淫秽以及妨碍国家安全和社会安定的自制电视节目或者录像片。"},{"i":10,"n":"第十条","txt":"有线电视台、有线电视站必须完整地直接接收、传送中央电视台和地方电视台的新闻和其他重要节目。"},{"i":11,"n":"第十一条","txt":"开办有线电视台、有线电视站的单位应当建立健全设备、片目、播映等管理制度，必须按月编制播映的节目单，经开办单位主管领导审核后，报县级广播电视行政管理部门备案。"},{"i":12,"n":"第十二条","txt":"已开办的有线电视台、有线电视站，因条件发生变化，不再继续开办的，应当在1个月内向审批机关报告，由审批机关注销。"},{"i":13,"n":"第十三条","txt":"行政区域性的有线电视台、有线电视站，由当地广播电视行政管理部门根据国务院广播电视行政管理部门的有关规定开办。"},{"i":14,"n":"第十四条","txt":"学校开办用于教学目的的有线电视，由有关教育行政管理部门参照本办法的规定审批、管理，并由审批机关抄学校所在地的县级以上广播电视行政管理部门备案。"},{"i":15,"n":"第十五条","txt":"县级以上地方各级广播电视行政管理部门负责对当地有线电视设施和有线电视播映活动进行监督检查，对违反本办法的行为，视情节轻重，给予相应的行政处罚："},{"i":16,"n":"第十六条","txt":"当事人对广播电视行政管理部门的行政处罚决定不服的，可以在收到处罚决定书之日起15日内，向作出行政处罚决定的机关的上一级机关申请复议。上一级广播电视行政管理部门应当在收到复议申请之日起1个月内作出复议决定。当事人对复议决定不服的，可以在接到复议决定之日起15日内向人民法院提起诉讼。当事人在规定的期限内不申请复议、也不向人民法院提起诉讼、又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。"},{"i":17,"n":"第十七条","txt":"对违反本办法，构成违反治安管理的行为，由公安机关依照《中华人民共和国治安管理处罚法》的规定予以处罚；情节严重构成犯罪的，由司法机关依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"用于国防、公安、国家安全业务的有线电视系统由中国人民解放军有关部门、公安部、国家安全部分别管理。"},{"i":19,"n":"第十九条","txt":"本办法由国务院广播电视行政管理部门负责解释。"},{"i":20,"n":"第二十条","txt":"本办法自发布之日起施行。"}],"chajianyoujianzhongjiadaiwaibihuowaibipiaojuzanxin583267":[{"i":1,"n":"第一条","txt":"为严格执行外汇管理，防止利用国内或国际邮件夹带外币或外币票据互相转让流通及私营外汇等情事，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称外币指一切外国币券，所称外币票据系指各种以外币支付之汇票、支票、旅行支票、期票及其他付款凭证等。"},{"i":3,"n":"第三条","txt":"本办法所指邮件之查检工作，应由各地海关或公安机关执行之；其查获外币及外币票据之存兑事宜，由中国人民银行总行授权各地中国银行办理之，无中国银行机构设立之地区则由人民银行办理之。"},{"i":4,"n":"第四条","txt":"在本国境内互寄或寄往国外之邮件中，如夹带外币一经查获，应报由司法机关一律全部没收之。"},{"i":5,"n":"第五条","txt":"在本国境内互寄或寄往国外之邮件中，如夹带外币票据一经查获，应由主管检查机关视其情节轻重，报由司法机关令其存兑，处以罚金或予以没收。"},{"i":6,"n":"第六条","txt":"由国外寄至国内邮件中，如夹带外币或外币票据，一经发现，可由各该邮局暂时代为保管，俟与收件人联系后，持向中国银行换取外汇存单或按牌价兑换人民币，予以发还。"},{"i":7,"n":"第七条","txt":"经主管检查机关查获应予没收之外币或外币票据，应交由各相关邮局，随时解送所在地之中国银行或人民银行，按牌价折合人民币，由中行或人行签发国库局抬头支票，由各该邮局送交当地国库换取收据，再由邮局将收据备函寄交寄件人（无中行或人行设立之地区，可由各相关邮局解送附近设有中行或人行地区之邮局代办解库手续，俟取得国库收据后，仍交由各相关邮局处理之）。"},{"i":8,"n":"第八条","txt":"所有经主管检查机关查获应予没收外币或外币票据之相关邮件，应由各该邮局于邮件内加盖“内装<span class=\"two-lines\"><span>外币</span><span>外币票据</span></span>已被主管机关查扣”戳记后，随时封发或投递，不得稽延积压，并由各该邮局通知寄件人。"},{"i":9,"n":"第九条","txt":"凡中国银行或国内经人民银行指定经营外汇业务之银行，基于正当外汇业务所开国外付款之票据，或国外银行所开国内中国银行及指定银行之票据，可不受本办法第五条及第六条条文之限制。"},{"i":10,"n":"第十条","txt":"凡查获应予没收之外币票据属于抬头人性质者，应由主管检查机关移送司法机关，勒令寄件人签妥空白背书或重开支票之手续。"},{"i":11,"n":"第十一条","txt":"凡无中国银行或人民银行机构设立之边远或乡村地区，其持有外币或外币票据拟寄递至附近地区中国银行或人民银行存兑者，经当地区级以上政府证明后，可不受本办法第四条及第五条条文之限制。"},{"i":12,"n":"第十二条","txt":"本办法自发布之日起实行。"}],"senlinheyeshengdongwuleixingziranbaohuquguanlibanf350bac":[{"i":1,"n":"第一条","txt":"自然保护区是保护自然环境和自然资源、拯救濒于灭绝的生物物种、进行科学研究的重要基地；对促进科学技术、生产建设、文化教育、卫生保健等事业的发展，具有重要意义。根据《中华人民共和国森林法》和有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"森林和野生动物类型自然保护区（以下简称自然保护区），按照本办法进行管理。"},{"i":3,"n":"第三条","txt":"自然保护区管理机构的主要任务：贯彻执行国家有关自然保护区的方针、政策和规定，加强管理，开展宣传教育，保护和发展珍贵稀有野生动植物资源，进行科学研究，探索自然演变规律和合理利用森林和动植物资源的途径，为社会主义建设服务。"},{"i":4,"n":"第四条","txt":"自然保护区分为国家自然保护区和地方自然保护区。国家自然保护区，由林业部或所在省、自治区、直辖市林业主管部门管理；地方自然保护区，由县级以上林业主管部门管理。"},{"i":5,"n":"第五条","txt":"具有下列条件之一者，可以建立自然保护区："},{"i":6,"n":"第六条","txt":"根据本办法第五条规定建立自然保护区，在科研上有重要价值，或者在国际上有一定影响的，报国务院批准，列为国家自然保护区；其他自然保护区，报省、自治区、直辖市人民政府批准，列为地方自然保护区。"},{"i":7,"n":"第七条","txt":"建立自然保护区要注意保护对象的完整性和最适宜的范围，考虑当地经济建设和群众生产生活的需要，尽可能避开群众的土地、山林；确实不能避开的，应当严格控制范围，并根据国家有关规定，合理解决群众的生产生活问题。"},{"i":8,"n":"第八条","txt":"自然保护区的解除和范围的调整，必须经原审批机关批准；未经批准不得改变自然保护区的性质和范围。"},{"i":9,"n":"第九条","txt":"自然保护区的管理机构属于事业单位。机构的设置和人员的配备，要注意精干。国家或地方自然保护区管理机构的人员编制、基建投资、事业经费等，经主管部门批准后，分别纳入国家和省、自治区、直辖市的计划，由林业部门统一安排。"},{"i":10,"n":"第十条","txt":"自然保护区管理机构，可以根据自然资源情况，将自然保护区分为核心区、实验区。核心区只供进行观测研究。实验区可以进行科学实验、教学实习、参观考察和驯化培育珍稀动植物等活动。"},{"i":11,"n":"第十一条","txt":"自然保护区的自然环境和自然资源，由自然保护区管理机构统一管理。未经林业部或省、自治区、直辖市林业主管部门批准，任何单位和个人不得进入自然保护区建立机构和修筑设施。"},{"i":12,"n":"第十二条","txt":"有条件的自然保护区，经林业部或省、自治区、直辖市林业主管部门批准，可以在指定的范围内开展旅游活动。"},{"i":13,"n":"第十三条","txt":"进入自然保护区从事科学研究、教学实习、参观考察、拍摄影片、登山等活动的单位和个人，必须经省、自治区、直辖市以上林业主管部门的同意。"},{"i":14,"n":"第十四条","txt":"自然保护区内的居民，应当遵守自然保护区的有关规定，固定生产生活活动范围，在不破坏自然资源的前提下，从事种植、养殖业，也可以承包自然保护区组织的劳务或保护管理任务，以增加经济收入。"},{"i":15,"n":"第十五条","txt":"自然保护区管理机构会同所在和毗邻的县、乡人民政府及有关单位，组成自然保护区联合保护委员会，制订保护公约，共同做好保护管理工作。"},{"i":16,"n":"第十六条","txt":"根据国家有关规定和需要，可以在自然保护区设立公安机构或者配备公安特派员，行政上受自然保护区管理机构领导，业务上受上级公安机关领导。"},{"i":17,"n":"第十七条","txt":"本办法自发布之日起施行。"}],"senlincaifagengxinguanlibanfa":[{"i":1,"n":"第一条","txt":"为合理采伐森林，及时更新采伐迹地，恢复和扩大森林资源，根据《中华人民共和国森林法》（以下简称森林法）及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"森林采伐更新要贯彻“以营林为基础，普遍护林，大力造林，采育结合，永续利用”的林业建设方针，执行森林经营方案，实行限额采伐，发挥森林的生态效益、经济效益和社会效益。"},{"i":3,"n":"第三条","txt":"全民、集体所有的森林、林木和个人所有的林木采伐更新，必须遵守本办法。"},{"i":4,"n":"第四条","txt":"森林采伐，包括主伐、抚育采伐、更新采伐和低产林改造。"},{"i":5,"n":"第五条","txt":"采伐林木按照森林法实施条例第三十条规定，申请林木采伐许可证时，除提交其他必备的文件外，国营企业事业单位和部队还应当提交有关主管部门核定的年度木材生产计划；农村集体、个人还应当提交基层林业站核定的年度采伐指标。上年度进行采伐的，应当提交上年度的更新验收合格证。"},{"i":6,"n":"第六条","txt":"林木采伐许可证的核发，按森林法及其实施条例的有关规定办理。授权核发林木采伐许可证，应当有书面文件。被授权核发林木采伐许可证的单位，应当配备熟悉业务的人员，并受授权单位监督。"},{"i":7,"n":"第七条","txt":"对用材林的成熟林和过熟林实行主伐。主要树种的主伐年龄，按《用材林主要树种主伐年龄表》的规定执行。定向培育的森林以及表内未列入树种的主伐年龄，由省、自治区、直辖市林业主管部门规定。"},{"i":8,"n":"第八条","txt":"用材林的主伐方式为择伐、皆伐和渐伐。"},{"i":9,"n":"第九条","txt":"对下列森林只准进行抚育和更新采伐："},{"i":10,"n":"第十条","txt":"防护林和特种用途林中的国防林、母树林、环境保护林、风景林的更新采伐技术规程，由林业部会同有关部门制定。"},{"i":11,"n":"第十一条","txt":"幼龄林、中龄林的抚育采伐，包括透光抚育、生长抚育、综合抚育；低产林的改造，包括局部改造和全面改造，其具体办法按照林业部发布的有关技术规程执行。"},{"i":12,"n":"第十二条","txt":"国营林业局和国营、集体林场的采伐作业，应当遵守下列规定："},{"i":13,"n":"第十三条","txt":"森林采伐后，核发林木采伐许可证的部门应当对采伐作业质量组织检查验收，签发采伐作业质量验收证明。验收证明格式由省、自治区、直辖市林业主管部门制定。"},{"i":14,"n":"第十四条","txt":"采伐林木的单位和个人，应当按照优先发展人工更新，人工更新、人工促进天然更新、天然更新相结合的原则，在采伐后的当年或者次年内必须完成更新造林任务。"},{"i":15,"n":"第十五条","txt":"更新质量必须达到以下标准："},{"i":16,"n":"第十六条","txt":"未更新的旧采伐迹地、火烧迹地、林中空地、水湿地等宜林荒山荒地，应当由森林经营单位制定规划，限期完成更新造林。"},{"i":17,"n":"第十七条","txt":"人工更新和造林应当执行林业部发布的有关造林规程，做到适地适树、细致整地、良种壮苗、密度合理、精心栽植、适时抚育。在立地条件好的地方，应当培育速生丰产林。"},{"i":18,"n":"第十八条","txt":"森林更新后，核发林木采伐许可证的部门应当组织更新单位对更新面积和质量进行检查验收，核发更新验收合格证。"},{"i":19,"n":"第十九条","txt":"有下列行为之一的，依照森林法第三十九条和森林法实施条例的有关规定处罚："},{"i":20,"n":"第二十条","txt":"盗伐、滥伐林木数量较大，不便计算补种株数的，可按盗伐、滥伐木材数量折算面积，并根据森林法第三十九条规定的处罚原则，责令限期营造相应面积的新林。"},{"i":21,"n":"第二十一条","txt":"无证采伐或者超过林木采伐许可证规定数量的木材，应当从下年度木材生产计划或者采伐指标中扣除。"},{"i":22,"n":"第二十二条","txt":"国营企业事业单位和集体所有制单位有下列行为之一，自检查之日起1个月内未纠正的，发放林木采伐许可证的部门有权收缴林木采伐许可证，中止其采伐，直到纠正为止："},{"i":23,"n":"第二十三条","txt":"采伐林木的单位和个人违反本办法第十四条、第十五条规定的，依照森林法第四十五条和森林法实施条例的有关规定处理。"},{"i":24,"n":"第二十四条","txt":"采伐林木的单位违反本办法有关规定的，对其主要负责人和直接责任人员，由所在单位或者上级主管机关给予行政处分。"},{"i":25,"n":"第二十五条","txt":"对国营企业事业单位所处罚款，从其自有资金或预算包干结余经费中开支。"},{"i":26,"n":"第二十六条","txt":"本办法由林业部负责解释。"},{"i":27,"n":"第二十七条","txt":"本办法自发布之日起施行。"}],"haiguanguanxianbiaozhishiyanghepeidaibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国海关关衔条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"海关工作人员佩带的关衔标志必须与所授予的关衔相符。"},{"i":3,"n":"第三条","txt":"海关关衔标志：海关总监、海关副总监关衔标志由橄榄叶环绕的海关关徽和五角星下衬五边形的星花组成；关务监督关衔标志由橄榄叶、星花和海关关徽组成；关务督察、关务督办、关务员关衔标志由横杠、星花和海关关徽组成。海关关衔标志为金色。"},{"i":4,"n":"第四条","txt":"关衔标志缀钉在肩章上，肩章为剑形，版面为黑色，分为硬肩章和软肩章。"},{"i":5,"n":"第五条","txt":"海关总监关衔标志为一枚橄榄叶环绕的海关关徽和三枚星花；海关副总监关衔标志为一枚橄榄叶环绕的海关关徽和二枚星花。"},{"i":6,"n":"第六条","txt":"海关工作人员晋升或者降低关衔的，由批准机关更换其关衔标志；取消或者不予保留关衔的，由批准机关收回其关衔标志。"},{"i":7,"n":"第七条","txt":"海关关衔标志由海关总署负责制作和管理。其他单位和个人不得制作、仿造、伪造、变造和买卖、使用关衔标志，也不得使用与关衔标志相类似的标志。"},{"i":8,"n":"第八条","txt":"本办法自公布之日起施行。"}],"yuyeziyuanzengzhibaohufeizhengshoushiyongbanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国渔业法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"凡在中华人民共和国的内水、滩涂、领海以及中华人民共和国管辖的其他海域采捕天然生长和人工增殖水生动植物的单位和个人，必须依照本办法缴纳渔业资源增殖保护费（以下简称“渔业资源费”）。"},{"i":3,"n":"第三条","txt":"渔业资源费的征收和使用，实行取之于渔、用之于渔的原则。"},{"i":4,"n":"第四条","txt":"渔业资源费由县级以上人民政府渔业行政主管部门及其授权单位依照批准发放捕捞许可证的权限征收。由国务院渔业行政主管部门批准发放捕捞许可证的，渔业资源费由国务院渔业行政主管部门所属的海区渔政监督管理机构（以下称“海区渔政监督管理机构”）征收。"},{"i":5,"n":"第五条","txt":"渔业资源费分为海洋渔业资源费和内陆水域渔业资源费。"},{"i":6,"n":"第六条","txt":"渔业资源费的具体征收标准，由省级人民政府渔业行政主管部门或者海区渔政监督管理机构，在本办法第五条确定的渔业资源费年征收金额幅度内，依照下列原则制定："},{"i":7,"n":"第七条","txt":"县级以上地方人民政府渔业行政主管部门或者海区渔政监督管理机构，根据本办法第六条规定的渔业资源费征收标准，依照作业单位的船只、功率和网具数量，确定应当缴纳的渔业资源费金额。"},{"i":8,"n":"第八条","txt":"持有广东省和香港、澳门地区双重户籍的流动渔船，由广东省人民政府渔业行政主管部门征收渔业资源费。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府渔业行政主管部门或者海区渔政监督管理机构，在批准发放捕捞许可证的同时征收渔业资源费，并在捕捞许可证上注明缴纳金额，加盖印章。"},{"i":10,"n":"第十条","txt":"渔业资源费列入当年生产成本。"},{"i":11,"n":"第十一条","txt":"省级人民政府渔业行政主管部门征收的渔业资源费（含市、县上缴部分，下同），实行按比例留成和上缴一部分统筹使用的办法。"},{"i":12,"n":"第十二条","txt":"渔业资源费用于渔业资源的增殖、保护，使用范围是："},{"i":13,"n":"第十三条","txt":"跨省、自治区、直辖市的大江、大河的人工增殖放流，由江河流经的省、自治区、直辖市人民政府渔业行政主管部门根据国务院渔业行政主管部门的统一规划，从其征收的内陆水域渔业资源费中提取经费。"},{"i":14,"n":"第十四条","txt":"渔业资源费按预算外资金管理。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府渔业行政主管部门以及渔业资源费的其他使用单位，应当在年初编制渔业资源费收支计划，在年终编制决算，报同级财政部门审批，并报上一级渔业行政主管部门备案。"},{"i":16,"n":"第十六条","txt":"各级财政、物价和审计部门，应当加强对渔业资源费征收使用工作的监督检查，对挪用、浪费渔业资源费的行为，应当依照国家有关规定查处。"},{"i":17,"n":"第十七条","txt":"本办法由国务院渔业行政主管部门会同财政、物价部门解释。"},{"i":18,"n":"第十八条","txt":"本办法自1989年1月1日起施行。"}],"xianyijunrenherenminwuzhuangjingchajuminshenfenzhe9186e2":[{"i":1,"n":"第一条","txt":"为了规范现役军人、人民武装警察居民身份证的申领和发放，依照《中华人民共和国居民身份证法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"现役军人、人民武装警察居民身份证的申领和发放，适用本办法。"},{"i":3,"n":"第三条","txt":"现役军人、人民武装警察居民身份证登记项目包括：姓名、性别、民族、出生日期、长期固定住址、公民身份号码、本人相片、证件的有效期和签发机关。"},{"i":4,"n":"第四条","txt":"现役军人、人民武装警察居民身份证登记项目内容，以本人档案记载内容和公安机关编制的公民身份号码为基础，由本人所在团级以上单位统一组织文字信息和人像信息的采集、录入、审核。"},{"i":5,"n":"第五条","txt":"现役军人、人民武装警察申请领取、换领、补领居民身份证，应当填写《现役军人、人民武装警察居民身份证申领登记表》，由本人所在团级以上单位向本人长期固定住址所在地的县级人民政府公安机关代为申请。"},{"i":6,"n":"第六条","txt":"现役军人、人民武装警察居民身份证由本人长期固定住址所在地的县级人民政府公安机关签发。"},{"i":7,"n":"第七条","txt":"现役军人、人民武装警察申请领取、换领、补领居民身份证的，公安机关应当依照《中华人民共和国居民身份证法》第十二条第一款的规定办理。"},{"i":8,"n":"第八条","txt":"现役军人、人民武装警察在服役前已经领取居民身份证，服役期间居民身份证仍在有效期内的，不再换领新证；但是，应当向其所在团级以上单位登记备案。"},{"i":9,"n":"第九条","txt":"现役军人、人民武装警察申请领取临时居民身份证的，由本人所在团级以上单位代为申请；公安机关应当依照《中华人民共和国临时居民身份证管理办法》的规定办理。"},{"i":10,"n":"第十条","txt":"军队、武装警察部队团级以上单位代现役军人、人民武装警察领取居民身份证、临时居民身份证后，应当及时发给本人。"},{"i":11,"n":"第十一条","txt":"现役军人、人民武装警察从事有关社会活动，需要证明公民身份的，凭居民身份证证明；执行任务、办理公务、享受抚恤优待等，需要证明现役军人或者人民武装警察身份的，凭军队、武装警察部队制发的身份证件证明。"},{"i":12,"n":"第十二条","txt":"军队、武装警察部队团级以上单位应当建立健全所属人员居民身份证的申领登记、备案等制度；在所属人员的本人档案中，应当载明其公民身份号码。"},{"i":13,"n":"第十三条","txt":"公安机关、军队、武装警察部队及其有关人员，在现役军人、人民武装警察居民身份证申领和发放工作中，对所涉及的国家秘密和知悉的个人信息，应当予以保密。"},{"i":14,"n":"第十四条","txt":"现役军人、人民武装警察有下列行为之一的，依照《中国人民解放军纪律条令》的有关规定，给予处分："},{"i":15,"n":"第十五条","txt":"现役军人、人民武装警察伪造、变造居民身份证的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"军队、武装警察部队有关人员在现役军人、人民武装警察居民身份证申领和发放工作中有下列行为之一的，依照《中国人民解放军纪律条令》的有关规定，给予处分；构成犯罪的，依法追究刑事责任："},{"i":17,"n":"第十七条","txt":"军队、武装警察部队管理的离休退休干部和待移交人民政府安置的离休退休干部、退休士官居民身份证的申领和发放，依照本办法执行。"},{"i":18,"n":"第十八条","txt":"本办法自2008年1月1日起施行。"}],"shehuijiuzhuzanxingbanfa":[{"i":1,"n":"第一条","txt":"为了加强社会救助，保障公民的基本生活，促进社会公平，维护社会和谐稳定，根据宪法，制定本办法。"},{"i":2,"n":"第二条","txt":"社会救助制度坚持托底线、救急难、可持续，与其他社会保障制度相衔接，社会救助水平与经济社会发展水平相适应。"},{"i":3,"n":"第三条","txt":"国务院民政部门统筹全国社会救助体系建设。国务院民政、应急管理、卫生健康、教育、住房城乡建设、人力资源社会保障、医疗保障等部门，按照各自职责负责相应的社会救助管理工作。"},{"i":4,"n":"第四条","txt":"乡镇人民政府、街道办事处负责有关社会救助的申请受理、调查审核，具体工作由社会救助经办机构或者经办人员承担。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当将社会救助纳入国民经济和社会发展规划，建立健全政府领导、民政部门牵头、有关部门配合、社会力量参与的社会救助工作协调机制，完善社会救助资金、物资保障机制，将政府安排的社会救助资金和社会救助工作经费纳入财政预算。"},{"i":6,"n":"第六条","txt":"县级以上人民政府应当按照国家统一规划建立社会救助管理信息系统，实现社会救助信息互联互通、资源共享。"},{"i":7,"n":"第七条","txt":"国家鼓励、支持社会力量参与社会救助。"},{"i":8,"n":"第八条","txt":"对在社会救助工作中作出显著成绩的单位、个人，按照国家有关规定给予表彰、奖励。"},{"i":9,"n":"第九条","txt":"国家对共同生活的家庭成员人均收入低于当地最低生活保障标准，且符合当地最低生活保障家庭财产状况规定的家庭，给予最低生活保障。"},{"i":10,"n":"第十条","txt":"最低生活保障标准，由省、自治区、直辖市或者设区的市级人民政府按照当地居民生活必需的费用确定、公布，并根据当地经济社会发展水平和物价变动情况适时调整。"},{"i":11,"n":"第十一条","txt":"申请最低生活保障，按照下列程序办理："},{"i":12,"n":"第十二条","txt":"对批准获得最低生活保障的家庭，县级人民政府民政部门按照共同生活的家庭成员人均收入低于当地最低生活保障标准的差额，按月发给最低生活保障金。"},{"i":13,"n":"第十三条","txt":"最低生活保障家庭的人口状况、收入状况、财产状况发生变化的，应当及时告知乡镇人民政府、街道办事处。"},{"i":14,"n":"第十四条","txt":"国家对无劳动能力、无生活来源且无法定赡养、抚养、扶养义务人，或者其法定赡养、抚养、扶养义务人无赡养、抚养、扶养能力的老年人、残疾人以及未满16周岁的未成年人，给予特困人员供养。"},{"i":15,"n":"第十五条","txt":"特困人员供养的内容包括："},{"i":16,"n":"第十六条","txt":"申请特困人员供养，由本人向户籍所在地的乡镇人民政府、街道办事处提出书面申请；本人申请有困难的，可以委托村民委员会、居民委员会代为提出申请。"},{"i":17,"n":"第十七条","txt":"乡镇人民政府、街道办事处应当及时了解掌握居民的生活情况，发现符合特困供养条件的人员，应当主动为其依法办理供养。"},{"i":18,"n":"第十八条","txt":"特困供养人员不再符合供养条件的，村民委员会、居民委员会或者供养服务机构应当告知乡镇人民政府、街道办事处，由乡镇人民政府、街道办事处审核并报县级人民政府民政部门核准后，终止供养并予以公示。"},{"i":19,"n":"第十九条","txt":"特困供养人员可以在当地的供养服务机构集中供养，也可以在家分散供养。特困供养人员可以自行选择供养形式。"},{"i":20,"n":"第二十条","txt":"国家建立健全自然灾害救助制度，对基本生活受到自然灾害严重影响的人员，提供生活救助。"},{"i":21,"n":"第二十一条","txt":"设区的市级以上人民政府和自然灾害多发、易发地区的县级人民政府应当根据自然灾害特点、居民人口数量和分布等情况，设立自然灾害救助物资储备库，保障自然灾害发生后救助物资的紧急供应。"},{"i":22,"n":"第二十二条","txt":"自然灾害发生后，县级以上人民政府或者人民政府的自然灾害救助应急综合协调机构应当根据情况紧急疏散、转移、安置受灾人员，及时为受灾人员提供必要的食品、饮用水、衣被、取暖、临时住所、医疗防疫等应急救助。"},{"i":23,"n":"第二十三条","txt":"灾情稳定后，受灾地区县级以上人民政府应当评估、核定并发布自然灾害损失情况。"},{"i":24,"n":"第二十四条","txt":"受灾地区人民政府应当在确保安全的前提下，对住房损毁严重的受灾人员进行过渡性安置。"},{"i":25,"n":"第二十五条","txt":"自然灾害危险消除后，受灾地区人民政府应急管理等部门应当及时核实本行政区域内居民住房恢复重建补助对象，并给予资金、物资等救助。"},{"i":26,"n":"第二十六条","txt":"自然灾害发生后，受灾地区人民政府应当为因当年冬寒或者次年春荒遇到生活困难的受灾人员提供基本生活救助。"},{"i":27,"n":"第二十七条","txt":"国家建立健全医疗救助制度，保障医疗救助对象获得基本医疗卫生服务。"},{"i":28,"n":"第二十八条","txt":"下列人员可以申请相关医疗救助："},{"i":29,"n":"第二十九条","txt":"医疗救助采取下列方式："},{"i":30,"n":"第三十条","txt":"申请医疗救助的，应当向乡镇人民政府、街道办事处提出，经审核、公示后，由县级人民政府医疗保障部门审批。最低生活保障家庭成员和特困供养人员的医疗救助，由县级人民政府医疗保障部门直接办理。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府应当建立健全医疗救助与基本医疗保险、大病保险相衔接的医疗费用结算机制，为医疗救助对象提供便捷服务。"},{"i":32,"n":"第三十二条","txt":"国家建立疾病应急救助制度，对需要急救但身份不明或者无力支付急救费用的急重危伤病患者给予救助。符合规定的急救费用由疾病应急救助基金支付。"},{"i":33,"n":"第三十三条","txt":"国家对在义务教育阶段就学的最低生活保障家庭成员、特困供养人员，给予教育救助。"},{"i":34,"n":"第三十四条","txt":"教育救助根据不同教育阶段需求，采取减免相关费用、发放助学金、给予生活补助、安排勤工助学等方式实施，保障教育救助对象基本学习、生活需求。"},{"i":35,"n":"第三十五条","txt":"教育救助标准，由省、自治区、直辖市人民政府根据经济社会发展水平和教育救助对象的基本学习、生活需求确定、公布。"},{"i":36,"n":"第三十六条","txt":"申请教育救助，应当按照国家有关规定向就读学校提出，按规定程序审核、确认后，由学校按照国家有关规定实施。"},{"i":37,"n":"第三十七条","txt":"国家对符合规定标准的住房困难的最低生活保障家庭、分散供养的特困人员，给予住房救助。"},{"i":38,"n":"第三十八条","txt":"住房救助通过配租公共租赁住房、发放住房租赁补贴、农村危房改造等方式实施。"},{"i":39,"n":"第三十九条","txt":"住房困难标准和救助标准，由县级以上地方人民政府根据本行政区域经济社会发展水平、住房价格水平等因素确定、公布。"},{"i":40,"n":"第四十条","txt":"城镇家庭申请住房救助的，应当经由乡镇人民政府、街道办事处或者直接向县级人民政府住房保障部门提出，经县级人民政府民政部门审核家庭收入、财产状况和县级人民政府住房保障部门审核家庭住房状况并公示后，对符合申请条件的申请人，由县级人民政府住房保障部门优先给予保障。"},{"i":41,"n":"第四十一条","txt":"各级人民政府按照国家规定通过财政投入、用地供应等措施为实施住房救助提供保障。"},{"i":42,"n":"第四十二条","txt":"国家对最低生活保障家庭中有劳动能力并处于失业状态的成员，通过贷款贴息、社会保险补贴、岗位补贴、培训补贴、费用减免、公益性岗位安置等办法，给予就业救助。"},{"i":43,"n":"第四十三条","txt":"最低生活保障家庭有劳动能力的成员均处于失业状态的，县级以上地方人民政府应当采取有针对性的措施，确保该家庭至少有一人就业。"},{"i":44,"n":"第四十四条","txt":"申请就业救助的，应当向住所地街道、社区公共就业服务机构提出，公共就业服务机构核实后予以登记，并免费提供就业岗位信息、职业介绍、职业指导等就业服务。"},{"i":45,"n":"第四十五条","txt":"最低生活保障家庭中有劳动能力但未就业的成员，应当接受人力资源社会保障等有关部门介绍的工作；无正当理由，连续3次拒绝接受介绍的与其健康状况、劳动能力等相适应的工作的，县级人民政府民政部门应当决定减发或者停发其本人的最低生活保障金。"},{"i":46,"n":"第四十六条","txt":"吸纳就业救助对象的用人单位，按照国家有关规定享受社会保险补贴、税收优惠、小额担保贷款等就业扶持政策。"},{"i":47,"n":"第四十七条","txt":"国家对因火灾、交通事故等意外事件，家庭成员突发重大疾病等原因，导致基本生活暂时出现严重困难的家庭，或者因生活必需支出突然增加超出家庭承受能力，导致基本生活暂时出现严重困难的最低生活保障家庭，以及遭遇其他特殊困难的家庭，给予临时救助。"},{"i":48,"n":"第四十八条","txt":"申请临时救助的，应当向乡镇人民政府、街道办事处提出，经审核、公示后，由县级人民政府民政部门审批；救助金额较小的，县级人民政府民政部门可以委托乡镇人民政府、街道办事处审批。情况紧急的，可以按照规定简化审批手续。"},{"i":49,"n":"第四十九条","txt":"临时救助的具体事项、标准，由县级以上地方人民政府确定、公布。"},{"i":50,"n":"第五十条","txt":"国家对生活无着的流浪、乞讨人员提供临时食宿、急病救治、协助返回等救助。"},{"i":51,"n":"第五十一条","txt":"公安机关和其他有关行政机关的工作人员在执行公务时发现流浪、乞讨人员的，应当告知其向救助管理机构求助。对其中的残疾人、未成年人、老年人和行动不便的其他人员，应当引导、护送到救助管理机构；对突发急病人员，应当立即通知急救机构进行救治。"},{"i":52,"n":"第五十二条","txt":"国家鼓励单位和个人等社会力量通过捐赠、设立帮扶项目、创办服务机构、提供志愿服务等方式，参与社会救助。"},{"i":53,"n":"第五十三条","txt":"社会力量参与社会救助，按照国家有关规定享受财政补贴、税收优惠、费用减免等政策。"},{"i":54,"n":"第五十四条","txt":"县级以上地方人民政府可以将社会救助中的具体服务事项通过委托、承包、采购等方式，向社会力量购买服务。"},{"i":55,"n":"第五十五条","txt":"县级以上地方人民政府应当发挥社会工作服务机构和社会工作者作用，为社会救助对象提供社会融入、能力提升、心理疏导等专业服务。"},{"i":56,"n":"第五十六条","txt":"社会救助管理部门及相关机构应当建立社会力量参与社会救助的机制和渠道，提供社会救助项目、需求信息，为社会力量参与社会救助创造条件、提供便利。"},{"i":57,"n":"第五十七条","txt":"县级以上人民政府及其社会救助管理部门应当加强对社会救助工作的监督检查，完善相关监督管理制度。"},{"i":58,"n":"第五十八条","txt":"申请或者已获得社会救助的家庭，应当按照规定如实申报家庭收入状况、财产状况。"},{"i":59,"n":"第五十九条","txt":"县级以上人民政府社会救助管理部门和乡镇人民政府、街道办事处在履行社会救助职责过程中，可以查阅、记录、复制与社会救助事项有关的资料，询问与社会救助事项有关的单位、个人，要求其对相关情况作出说明，提供相关证明材料。有关单位、个人应当如实提供。"},{"i":60,"n":"第六十条","txt":"申请社会救助，应当按照本办法的规定提出；申请人难以确定社会救助管理部门的，可以先向社会救助经办机构或者县级人民政府民政部门求助。社会救助经办机构或者县级人民政府民政部门接到求助后，应当及时办理或者转交其他社会救助管理部门办理。"},{"i":61,"n":"第六十一条","txt":"履行社会救助职责的工作人员对在社会救助工作中知悉的公民个人信息，除按照规定应当公示的信息外，应当予以保密。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府及其社会救助管理部门应当通过报刊、广播、电视、互联网等媒体，宣传社会救助法律、法规和政策。"},{"i":63,"n":"第六十三条","txt":"履行社会救助职责的工作人员行使职权，应当接受社会监督。"},{"i":64,"n":"第六十四条","txt":"县级以上人民政府财政部门、审计机关依法对社会救助资金、物资的筹集、分配、管理和使用实施监督。"},{"i":65,"n":"第六十五条","txt":"申请或者已获得社会救助的家庭或者人员，对社会救助管理部门作出的具体行政行为不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":66,"n":"第六十六条","txt":"违反本办法规定，有下列情形之一的，由上级行政机关或者监察机关责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":67,"n":"第六十七条","txt":"违反本办法规定，截留、挤占、挪用、私分社会救助资金、物资的，由有关部门责令追回；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":68,"n":"第六十八条","txt":"采取虚报、隐瞒、伪造等手段，骗取社会救助资金、物资或者服务的，由有关部门决定停止社会救助，责令退回非法获取的救助资金、物资，可以处非法获取的救助款额或者物资价值1倍以上3倍以下的罚款；构成违反治安管理行为的，依法给予治安管理处罚。"},{"i":69,"n":"第六十九条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":70,"n":"第七十条","txt":"本办法自2014年5月1日起施行。"}],"piaojuguanlishishibanfa":[{"i":1,"n":"第一条","txt":"为了加强票据管理，维护金融秩序，根据《中华人民共和国票据法》（以下简称票据法）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的票据管理，适用本办法。"},{"i":3,"n":"第三条","txt":"中国人民银行是票据的管理部门。"},{"i":4,"n":"第四条","txt":"票据当事人应当依法从事票据活动，行使票据权利，履行票据义务。"},{"i":5,"n":"第五条","txt":"票据当事人应当使用中国人民银行规定的统一格式的票据。"},{"i":6,"n":"第六条","txt":"银行汇票的出票人，为经中国人民银行批准办理银行汇票业务的银行。"},{"i":7,"n":"第七条","txt":"银行本票的出票人，为经中国人民银行批准办理银行本票业务的银行。"},{"i":8,"n":"第八条","txt":"商业汇票的出票人，为银行以外的企业和其他组织。"},{"i":9,"n":"第九条","txt":"承兑商业汇票的银行，必须具备下列条件："},{"i":10,"n":"第十条","txt":"向银行申请办理票据贴现的商业汇票的持票人，必须具备下列条件："},{"i":11,"n":"第十一条","txt":"支票的出票人，为在经中国人民银行批准办理支票存款业务的银行、城市信用合作社和农村信用合作社开立支票存款账户的企业、其他组织和个人。"},{"i":12,"n":"第十二条","txt":"票据法所称“保证人”，是指具有代为清偿票据债务能力的法人、其他组织或者个人。"},{"i":13,"n":"第十三条","txt":"银行汇票上的出票人的签章、银行承兑商业汇票的签章，为该银行的汇票专用章加其法定代表人或者其授权的代理人的签名或者盖章。"},{"i":14,"n":"第十四条","txt":"商业汇票上的出票人的签章，为该单位的财务专用章或者公章加其法定代表人或者其授权的代理人的签名或者盖章。"},{"i":15,"n":"第十五条","txt":"支票上的出票人的签章，出票人为单位的，为与该单位在银行预留签章一致的财务专用章或者公章加其法定代表人或者其授权的代理人的签名或者盖章；出票人为个人的，为与该个人在银行预留签章一致的签名或者盖章。"},{"i":16,"n":"第十六条","txt":"票据法所称“本名”，是指符合法律、行政法规以及国家有关规定的身份证件上的姓名。"},{"i":17,"n":"第十七条","txt":"出票人在票据上的签章不符合票据法和本办法规定的，票据无效；背书人、承兑人、保证人在票据上的签章不符合票据法和本办法规定的，其签章无效，但是不影响票据上其他签章的效力。"},{"i":18,"n":"第十八条","txt":"票据法所称“代理付款人”，是指根据付款人的委托，代其支付票据金额的银行、城市信用合作社和农村信用合作社。"},{"i":19,"n":"第十九条","txt":"票据法规定可以办理挂失止付的票据丧失的，失票人可以依照票据法的规定及时通知付款人或者代理付款人挂失止付。"},{"i":20,"n":"第二十条","txt":"付款人或者代理付款人收到挂失止付通知书，应当立即暂停支付。付款人或者代理付款人自收到挂失止付通知书之日起12日内没有收到人民法院的止付通知书的，自第13日起，挂失止付通知书失效。"},{"i":21,"n":"第二十一条","txt":"付款人或者代理付款人在收到挂失止付通知书前，已经依法向持票人付款的，不再接受挂失止付。"},{"i":22,"n":"第二十二条","txt":"申请人申请开立支票存款账户的，银行、城市信用合作社和农村信用合作社可以与申请人约定在支票上使用支付密码，作为支付支票金额的条件。"},{"i":23,"n":"第二十三条","txt":"保证人应当依照票据法的规定，在票据或者其粘单上记载保证事项。保证人为出票人、付款人、承兑人保证的，应当在票据的正面记载保证事项；保证人为背书人保证的，应当在票据的背面或者其粘单上记载保证事项。"},{"i":24,"n":"第二十四条","txt":"依法背书转让的票据，任何单位和个人不得冻结票据款项；但是，法律另有规定的除外。"},{"i":25,"n":"第二十五条","txt":"票据法第五十五条所称“签收”，是指持票人在票据的正面签章，表明持票人已经获得付款。"},{"i":26,"n":"第二十六条","txt":"通过委托收款银行或者通过票据交换系统向付款人提示付款的，持票人向银行提交票据日为提示付款日。"},{"i":27,"n":"第二十七条","txt":"票据法第六十二条所称“拒绝证明”应当包括下列事项："},{"i":28,"n":"第二十八条","txt":"票据法第六十三条规定的“其他有关证明”是指："},{"i":29,"n":"第二十九条","txt":"票据法第七十条第一款第（二）项、第七十一条第一款第（二）项规定的“利率”，是指中国人民银行规定的流动资金贷款利率。"},{"i":30,"n":"第三十条","txt":"有票据法第一百零二条所列行为之一，情节轻微，不构成犯罪的，由公安机关依法予以处罚。"},{"i":31,"n":"第三十一条","txt":"签发空头支票或者签发与其预留的签章不符的支票，不以骗取财物为目的的，由中国人民银行处以票面金额5%但不低于1000元的罚款；持票人有权要求出票人赔偿支票金额2%的赔偿金。"},{"i":32,"n":"第三十二条","txt":"金融机构的工作人员在票据业务中玩忽职守，对违反票据法和本办法规定的票据予以承兑、付款、保证或者贴现的，对直接负责的主管人员和其他直接责任人员给予警告、记过、撤职或者开除的处分；造成重大损失，构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"票据的付款人对见票即付或者到期的票据，故意压票、拖延支付的，由中国人民银行处以压票、拖延支付期间内每日票据金额0.7‰的罚款；对直接负责的主管人员和其他直接责任人员给予警告、记过、撤职或者开除的处分。"},{"i":34,"n":"第三十四条","txt":"违反中国人民银行规定，擅自印制票据的，由中国人民银行责令改正，处以1万元以上20万元以下的罚款；情节严重的，中国人民银行有权提请有关部门吊销其营业执照。"},{"i":35,"n":"第三十五条","txt":"票据的格式、联次、颜色、规格及防伪技术要求和印制，由中国人民银行规定。"},{"i":36,"n":"第三十六条","txt":"本办法自1997年10月1日起施行。"}],"dijietiaoyueguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范缔结条约工作程序，加强对缔结条约事务的管理，根据《中华人民共和国缔结条约程序法》（以下简称缔约程序法）和有关法律规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国务院或者国务院有关部门缔结条约、协定和其他具有条约、协定性质的文件（以下统称条约），办理相关事务，适用本办法。"},{"i":3,"n":"第三条","txt":"外交部在国务院领导下管理缔结条约的具体事务，指导、督促国务院有关部门依照法定程序办理缔结条约工作。"},{"i":4,"n":"第四条","txt":"除中华人民共和国宪法、法律和国务院另有授权外，地方各级政府无权缔结条约。"},{"i":5,"n":"第五条","txt":"下列条约，除法律另有规定外，应当以中华人民共和国名义缔结："},{"i":6,"n":"第六条","txt":"下列条约，应当以中华人民共和国政府名义缔结："},{"i":7,"n":"第七条","txt":"国务院各部、委员会、中国人民银行、审计署、具有行政管理职能的直属机构、根据法律规定或者国务院授权承担行政管理职能的国务院其他机构，可以就本部门职权范围内的事项，以中华人民共和国政府部门名义缔结条约。"},{"i":8,"n":"第八条","txt":"条约内容涉及政治、外交、经济、社会、安全等领域重大国家利益的，应当将条约草案及条约草案涉及的重大问题按照有关规定报告党中央。"},{"i":9,"n":"第九条","txt":"以中华人民共和国名义或者中华人民共和国政府名义谈判条约的，由外交部或者国务院有关部门会同外交部在启动谈判前不少于20个工作日报请国务院决定。"},{"i":10,"n":"第十条","txt":"以中华人民共和国政府部门名义谈判条约，有下列情形之一的，由国务院有关部门会同外交部在启动谈判前不少于20个工作日报请国务院决定："},{"i":11,"n":"第十一条","txt":"条约谈判中，对经国务院决定的条约中方草案所作改动有下列情形之一的，应当重新报请国务院决定："},{"i":12,"n":"第十二条","txt":"以中华人民共和国名义或者中华人民共和国政府名义签署条约，或者有本办法第十条规定情形之一的，应当由外交部或者国务院有关部门会同外交部在签署前不少于10个工作日报请国务院决定。"},{"i":13,"n":"第十三条","txt":"条约签署前，国务院有关部门法制机构应当从法律角度对条约进行审查。"},{"i":14,"n":"第十四条","txt":"下列情形，国务院有关部门应当在签署条约的请示中予以说明："},{"i":15,"n":"第十五条","txt":"条约的谈判代表或者签署代表需要出具全权证书的，国务院有关部门应当至少提前10个工作日书面通知外交部办理相关手续，并向外交部提供国务院同意委派该谈判代表或者签署代表的批件。"},{"i":16,"n":"第十六条","txt":"下列条约，应当由外交部或者国务院有关部门会同外交部自签署之日起180日内报请国务院审核，并建议提请全国人民代表大会常务委员会决定批准："},{"i":17,"n":"第十七条","txt":"下列条约，应当由外交部或者国务院有关部门会同外交部自签署之日起180日内报请国务院核准："},{"i":18,"n":"第十八条","txt":"加入本办法第十六条所列范围的多边条约，应当由外交部或者国务院有关部门会同外交部报请国务院审核，并建议提请全国人民代表大会常务委员会决定。"},{"i":19,"n":"第十九条","txt":"接受多边条约或者加入本办法第十七条所列范围的多边条约，应当由外交部或者国务院有关部门会同外交部报请国务院决定。"},{"i":20,"n":"第二十条","txt":"报请国务院审核并建议提请全国人民代表大会常务委员会决定批准或者加入条约的，应当由外交部或者国务院有关部门会同外交部向国务院报送请示，并附送国务院提请全国人民代表大会常务委员会决定批准或者加入该条约的议案说明、条约作准中文本及其电子文本或者中译本及其电子文本，以及国务院审核同意的条约谈判和签署请示。"},{"i":21,"n":"第二十一条","txt":"报请国务院核准、决定加入或者接受条约的，应当由外交部或者国务院有关部门会同外交部向国务院报送审核并建议核准、决定加入或者接受该条约的请示，并附送条约作准中文本及其电子文本或者中译本及其电子文本，以及国务院审核同意的条约谈判和签署请示。"},{"i":22,"n":"第二十二条","txt":"条约报送部门在将条约报请国务院审核前，应当对条约作准中文本或者中译本进行认真审核，确保内容及其文字表述准确、中外文本一致，格式符合规范要求。"},{"i":23,"n":"第二十三条","txt":"根据缔约程序法和有关规定，需要报国务院备案或者送外交部登记的条约，国务院有关部门应当自条约签署之日起90日内办理。"},{"i":24,"n":"第二十四条","txt":"根据本办法第十六条、第十七条、第十八条、第十九条规定报请国务院审核并建议提请全国人民代表大会常务委员会决定批准或者加入，或者报请国务院核准、决定加入或者接受的条约由司法部审查，提出法律意见。"},{"i":25,"n":"第二十五条","txt":"缔结多边条约，除本办法第二十七条规定的情形外，国务院有关部门应当在报请国务院审核并建议提请全国人民代表大会常务委员会决定批准或者加入前，或者报请国务院核准、决定加入或者接受前，通过外交部分别征询香港特别行政区政府、澳门特别行政区政府意见。多边条约规定缔约方不限于主权国家，且根据《中华人民共和国香港特别行政区基本法》和《中华人民共和国澳门特别行政区基本法》，香港特别行政区、澳门特别行政区有权单独签订的，可以不征询香港特别行政区政府、澳门特别行政区政府意见。"},{"i":26,"n":"第二十六条","txt":"根据本办法第二十五条规定，外交部征询香港特别行政区政府、澳门特别行政区政府意见的事项包括："},{"i":27,"n":"第二十七条","txt":"涉及外交、国防事务的条约，或者根据条约性质、规定应当适用于中华人民共和国全部领土的条约，国务院有关部门应当在报请国务院审核并建议提请全国人民代表大会常务委员会决定批准或者加入前，或者报请国务院核准、决定加入或者接受前，通过外交部通知香港特别行政区政府、澳门特别行政区政府条约将适用于香港特别行政区、澳门特别行政区。"},{"i":28,"n":"第二十八条","txt":"国务院有关部门应当自收到全国人民代表大会常务委员会批准或者加入条约的决定之日起或者自收到国务院核准、决定加入或者接受条约的批复之日起20个工作日内，书面通知外交部办理制作、交存或者交换批准书、核准书、加入书或者接受书的具体手续。国务院有关部门对于交存或者交换时机有特别安排的，应当作出说明。"},{"i":29,"n":"第二十九条","txt":"缔结双边条约，需要与缔约另一方相互通知已完成条约生效需要履行的国内法律程序的，国务院有关部门应当自完成批准、核准或者备案手续之日起20个工作日内或者在报送外交部登记时，书面通知外交部办理。"},{"i":30,"n":"第三十条","txt":"适用于香港特别行政区、澳门特别行政区的条约，国务院有关部门应当自条约对中华人民共和国生效的手续办理完毕之日起20个工作日内，将条约适用于香港特别行政区、澳门特别行政区的情况，通过外交部通知香港特别行政区政府、澳门特别行政区政府。"},{"i":31,"n":"第三十一条","txt":"条约扩展适用于香港特别行政区、澳门特别行政区的，国务院有关部门应当参照本办法第二十五条、第二十六条的规定通过外交部分别征询香港特别行政区政府、澳门特别行政区政府意见，并会同外交部提出建议，报请国务院决定。"},{"i":32,"n":"第三十二条","txt":"根据缔约程序法第十四条的规定保存条约签字正本的，国务院有关部门应当自条约签署之日起90日内将条约签字正本送外交部保存，并附送条约作准中文本或者中译本、作准外文本和相关电子文本。"},{"i":33,"n":"第三十三条","txt":"国务院核准、决定加入或者接受的条约或者向国务院备案的条约，应当及时由国务院公报予以公布。"},{"i":34,"n":"第三十四条","txt":"外交部应当编辑出版《中华人民共和国条约集》，并建设和维护数字化的条约数据库。"},{"i":35,"n":"第三十五条","txt":"撤回或者修改对条约作出的声明或者保留，依照作出声明或者保留的程序办理，但本办法第三十一条规定的情形除外。"},{"i":36,"n":"第三十六条","txt":"本办法自2023年1月1日起施行。"}],"xuzhihongquyunyongbuchangbanfa":[{"i":1,"n":"第一条","txt":"为了保障蓄滞洪区的正常运用，确保受洪水威胁的重点地区的防洪安全，合理补偿蓄滞洪区内居民因蓄滞洪遭受的损失，根据《中华人民共和国防洪法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国家蓄滞洪区。国家蓄滞洪区名录由国务院水行政主管部门根据国家确定的重要江河、湖泊流域的防洪规划拟订，报国务院批准后公布。"},{"i":3,"n":"第三条","txt":"蓄滞洪区运用补偿，遵循下列原则："},{"i":4,"n":"第四条","txt":"蓄滞洪区运用前，蓄滞洪区所在地地方各级人民政府应当组织有关部门和单位做好蓄滞洪区内人员、财产的转移和保护工作，尽量减少蓄滞洪造成的损失。"},{"i":5,"n":"第五条","txt":"国务院财政主管部门和水行政主管部门依照本办法的规定，负责全国蓄滞洪区运用补偿工作的组织实施和监督管理。"},{"i":6,"n":"第六条","txt":"国家鼓励、支持在蓄滞洪区推行洪水保险制度，鼓励保险机构根据蓄滞洪区运用后损失情况，开展洪水保险快速理赔和灾害应急预付赔款服务。"},{"i":7,"n":"第七条","txt":"任何组织和个人不得骗取、侵吞和挪用蓄滞洪区运用补偿资金。"},{"i":8,"n":"第八条","txt":"审计机关应当加强对蓄滞洪区运用补偿资金的管理和使用情况的审计监督。"},{"i":9,"n":"第九条","txt":"蓄滞洪区所在地地方各级人民政府有关部门应当充分运用现代信息技术手段，建立健全信息共享机制，提高蓄滞洪区运用补偿工作效率和水平。"},{"i":10,"n":"第十条","txt":"蓄滞洪区内具有常住户口的居民，依法直接从事种植、养殖的农业生产者，以及蓄滞洪区内住房的所有权人（以下统称区内居民），在蓄滞洪区运用后依照本办法的规定获得补偿。"},{"i":11,"n":"第十一条","txt":"蓄滞洪区运用后，对区内居民遭受的下列损失给予补偿："},{"i":12,"n":"第十二条","txt":"蓄滞洪区运用后造成的下列损失，不予补偿："},{"i":13,"n":"第十三条","txt":"蓄滞洪区运用后，对本办法第十一条规定范围内的损失实行分类定值补偿，补偿标准按照下列规定执行："},{"i":14,"n":"第十四条","txt":"已下达蓄滞洪转移命令，因情况变化未实施蓄滞洪造成损失的，给予适当补偿。"},{"i":15,"n":"第十五条","txt":"蓄滞洪区所在地县级人民政府应当组织有关部门和乡镇人民政府、街道办事处对区内居民的承包土地、流转土地、住房、农业生产机械和家庭主要耐用消费品逐户进行补偿登记，并由村民委员会、居民委员会张榜公布；在规定时间内无异议的，由县、乡、村分级建档立卡。"},{"i":16,"n":"第十六条","txt":"财产补偿登记已公布的区内居民的承包土地、流转土地、住房或者其他财产发生变更时，村民委员会、居民委员会应当于每年汛前汇总，并向乡镇人民政府、街道办事处提出变更登记申请，由乡镇人民政府、街道办事处核实登记后，报蓄滞洪区所在地县级人民政府指定的部门备案。"},{"i":17,"n":"第十七条","txt":"蓄滞洪区所在地县级人民政府应当及时将区内居民的承包土地、流转土地、住房、农业生产机械和家庭主要耐用消费品的财产补偿登记情况及变更登记情况汇总后抄报所在流域管理机构备案。流域管理机构应当根据每年汛期预报，对财产补偿登记及变更登记情况进行必要的抽查。"},{"i":18,"n":"第十八条","txt":"蓄滞洪区运用后，所在地省级人民政府或者其授权的主管部门应当及时组织对蓄滞洪区运用的淹没范围予以界定。"},{"i":19,"n":"第十九条","txt":"蓄滞洪区运用补偿资金由中央财政和蓄滞洪区所在地省级财政共同承担，中央财政承担补偿资金总额的70%。"},{"i":20,"n":"第二十条","txt":"蓄滞洪区所在地县级人民政府在补偿资金预算下达后，应当及时制定具体补偿方案，由乡镇人民政府、街道办事处逐户确定具体补偿金额，并由村民委员会、居民委员会张榜公布。"},{"i":21,"n":"第二十一条","txt":"蓄滞洪区运用后损失严重的，在补偿方案由国务院有关部门审查、核定前，蓄滞洪区所在地省级人民政府或者其授权的主管部门可以向国务院水行政主管部门、财政主管部门申请预先下达部分补偿资金预算，并及时组织将补偿资金支付至区内居民银行账户。预先下达的补偿资金在后期据实结算。"},{"i":22,"n":"第二十二条","txt":"补偿资金发放完毕后，蓄滞洪区所在地省级人民政府或者其授权的主管部门应当及时将补偿工作情况报国务院财政主管部门、水行政主管部门和应急管理部门。"},{"i":23,"n":"第二十三条","txt":"地方各级人民政府和县级以上人民政府有关部门及其工作人员，以及其他依法履行公职的人员，在蓄滞洪区运用补偿工作中滥用职权、玩忽职守、徇私舞弊，或者骗取、侵吞、挪用补偿资金的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":24,"n":"第二十四条","txt":"区内居民在财产补偿登记时弄虚作假，或者在蓄滞洪区运用补偿过程中谎报、虚报损失的，由县级人民政府责令改正，予以警告；多领、冒领补偿资金的，追回多领、冒领的资金。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"财产补偿登记、变更登记不得向区内居民收取任何费用，所需费用由蓄滞洪区所在地县级人民政府统筹解决。"},{"i":27,"n":"第二十七条","txt":"省级人民政府批准的防洪规划中确定的蓄滞洪区的运用补偿办法，由有关省级人民政府制定。"},{"i":28,"n":"第二十八条","txt":"本办法自公布之日起施行。2000年5月27日国务院发布的《蓄滞洪区运用补偿暂行办法》同时废止。"}],"jisuanjixinxiwangluoguojilianwanganquanbaohuguanli483215":[{"i":1,"n":"第一条","txt":"为了加强对计算机信息网络国际联网的安全保护，维护公共秩序和社会稳定，根据《中华人民共和国计算机信息系统安全保护条例》、《中华人民共和国计算机信息网络国际联网管理暂行规定》和其他法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的计算机信息网络国际联网安全保护管理，适用本办法。"},{"i":3,"n":"第三条","txt":"公安部计算机管理监察机构负责计算机信息网络国际联网的安全保护管理工作。"},{"i":4,"n":"第四条","txt":"任何单位和个人不得利用国际联网危害国家安全、泄露国家秘密，不得侵犯国家的、社会的、集体的利益和公民的合法权益，不得从事违法犯罪活动。"},{"i":5,"n":"第五条","txt":"任何单位和个人不得利用国际联网制作、复制、查阅和传播下列信息："},{"i":6,"n":"第六条","txt":"任何单位和个人不得从事下列危害计算机信息网络安全的活动："},{"i":7,"n":"第七条","txt":"用户的通信自由和通信秘密受法律保护。任何单位和个人不得违反法律规定，利用国际联网侵犯用户的通信自由和通信秘密。"},{"i":8,"n":"第八条","txt":"从事国际联网业务的单位和个人应当接受公安机关的安全监督、检查和指导，如实向公安机关提供有关安全保护的信息、资料及数据文件，协助公安机关查处通过国际联网的计算机信息网络的违法犯罪行为。"},{"i":9,"n":"第九条","txt":"国际出入口信道提供单位、互联单位的主管部门或者主管单位，应当依照法律和国家有关规定负责国际出入口信道、所属互联网络的安全保护管理工作。"},{"i":10,"n":"第十条","txt":"互联单位、接入单位及使用计算机信息网络国际联网的法人和其他组织应当履行下列安全保护职责："},{"i":11,"n":"第十一条","txt":"用户在接入单位办理入网手续时，应当填写用户备案表。备案表由公安部监制。"},{"i":12,"n":"第十二条","txt":"互联单位、接入单位、使用计算机信息网络国际联网的法人和其他组织（包括跨省、自治区、直辖市联网的单位和所属的分支机构），应当自网络正式联通之日起30日内，到所在地的省、自治区、直辖市人民政府公安机关指定的受理机关办理备案手续。"},{"i":13,"n":"第十三条","txt":"使用公用账号的注册者应当加强对公用账号的管理，建立账号使用登记制度。用户账号不得转借、转让。"},{"i":14,"n":"第十四条","txt":"涉及国家事务、经济建设、国防建设、尖端科学技术等重要领域的单位办理备案手续时，应当出具其行政主管部门的审批证明。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市公安厅（局），地（市）、县（市）公安局，应当有相应机构负责国际联网的安全保护管理工作。"},{"i":16,"n":"第十六条","txt":"公安机关计算机管理监察机构应当掌握互联单位、接入单位和用户的备案情况，建立备案档案，进行备案统计，并按照国家有关规定逐级上报。"},{"i":17,"n":"第十七条","txt":"公安机关计算机管理监察机构应当督促互联单位、接入单位及有关用户建立健全安全保护管理制度。监督、检查网络安全保护管理以及技术措施的落实情况。"},{"i":18,"n":"第十八条","txt":"公安机关计算机管理监察机构发现含有本办法第五条所列内容的地址、目录或者服务器时，应当通知有关单位关闭或者删除。"},{"i":19,"n":"第十九条","txt":"公安机关计算机管理监察机构应当负责追踪和查处通过计算机信息网络的违法行为和针对计算机信息网络的犯罪案件，对违反本办法第四条、第七条规定的违法犯罪行为，应当按照国家有关规定移送有关部门或者司法机关处理。"},{"i":20,"n":"第二十条","txt":"违反法律、行政法规，有本办法第五条、第六条所列行为之一的，由公安机关给予警告，有违法所得的，没收违法所得，对个人可以并处5000元以下的罚款，对单位可以并处1.5万元以下的罚款；情节严重的，并可以给予6个月以内停止联网、停机整顿的处罚，必要时可以建议原发证、审批机构吊销经营许可证或者取消联网资格；构成违反治安管理行为的，依照治安管理处罚法的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"有下列行为之一的，由公安机关责令限期改正，给予警告，有违法所得的，没收违法所得；在规定的限期内未改正的，对单位的主管负责人员和其他直接责任人员可以并处5000元以下的罚款，对单位可以并处1.5万元以下的罚款；情节严重的，并可以给予6个月以内的停止联网、停机整顿的处罚，必要时可以建议原发证、审批机构吊销经营许可证或者取消联网资格。"},{"i":22,"n":"第二十二条","txt":"违反本办法第四条、第七条规定的，依照有关法律、法规予以处罚。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十一条、第十二条规定，不履行备案职责的，由公安机关给予警告或者停机整顿不超过6个月的处罚。"},{"i":24,"n":"第二十四条","txt":"与香港特别行政区和台湾、澳门地区联网的计算机信息网络的安全保护管理，参照本办法执行。"},{"i":25,"n":"第二十五条","txt":"本办法自1997年12月30日起施行。"}],"zhengquanqihuotouzizixunguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了加强对证券、期货投资咨询活动的管理，保障投资者的合法权益和社会公共利益，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事证券、期货投资咨询业务，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"从事证券、期货投资咨询业务，必须依照本办法的规定，取得中国证监会的业务许可。未经中国证监会许可，任何机构和个人均不得从事本办法第二条所列各种形式证券、期货投资咨询业务。"},{"i":4,"n":"第四条","txt":"从事证券、期货投资咨询业务，必须遵守有关法律、法规、规章和中国证监会的有关规定，遵循客观、公正和诚实信用的原则。"},{"i":5,"n":"第五条","txt":"中国证监会及其授权的地方证券、期货监管部门（以下简称地方证管办(证监会）)负责对证券、期货投资咨询业务的监督管理，并负责本办法的实施。"},{"i":6,"n":"第六条","txt":"申请证券、期货投资咨询从业资格的机构，应当具备下列条件："},{"i":7,"n":"第七条","txt":"证券经营机构、期货经纪机构应当符合本办法第六条规定的条件，方可申请从事超出本机构范围的证券、期货投资咨询业务。"},{"i":8,"n":"第八条","txt":"申请证券、期货投资咨询从业资格的机构，按照下列程序审批："},{"i":9,"n":"第九条","txt":"申请证券、期货投资咨询从业资格的机构，应当提交下列文件："},{"i":10,"n":"第十条","txt":"证券、期货投资咨询机构的业务方式、业务场所、主要负责人以及具有证券、期货投资咨询从业资格的业务人员发生变化的，应当自发生变化之日起5个工作日内，向地方证管办（证监会）提出变更报告，办理变更手续。"},{"i":11,"n":"第十一条","txt":"证券、期货投资咨询机构应当于每年1月1日至4月30日期间向地方证管办（证监会）申请办理年检。办理年检时，应当提交下列文件："},{"i":12,"n":"第十二条","txt":"从事证券、期货投资咨询业务的人员，必须取得证券、期货投资咨询从业资格并加入一家有从业资格的证券、期货投资咨询机构后，方可从事证券、期货投资咨询业务。"},{"i":13,"n":"第十三条","txt":"证券、期货投资咨询人员申请取得证券、期货投资咨询从业资格，必须具备下列条件："},{"i":14,"n":"第十四条","txt":"证券、期货投资咨询人员申请取得证券、期货投资咨询从业资格，按照下列程序审批："},{"i":15,"n":"第十五条","txt":"证券、期货投资咨询人员申请取得证券、期货投资咨询从业资格，应当提交下列文件："},{"i":16,"n":"第十六条","txt":"取得证券、期货投资咨询从业资格的人员申请执业的，由所参加的证券、期货投资咨询机构向所在地地方证管办（证监会）提出申请，地方证管办（证监会）审核同意后，报中国证监会审批；准予执业的，由中国证监会颁发执业证书。"},{"i":17,"n":"第十七条","txt":"取得证券、期货投资咨询执业资格的人员，应当在所参加的证券、期货投资咨询机构年检时同时办理执业年检。取得证券、期货投资咨询从业资格，但是未在证券、期货投资咨询机构执业的，其从业资格自取得之日起满18个月后自动失效。"},{"i":18,"n":"第十八条","txt":"证券、期货投资咨询人员不得同时在两个或者两个以上的证券、期货投资咨询机构执业。"},{"i":19,"n":"第十九条","txt":"证券、期货投资咨询机构及其投资咨询人员，应当以行业公认的谨慎、诚实和勤勉尽责的态度，为投资人或者客户提供证券、期货投资咨询服务。"},{"i":20,"n":"第二十条","txt":"证券、期货投资咨询机构及其投资咨询人员，应当完整、客观、准确地运用有关信息、资料向投资人或者客户提供投资分析、预测和建议，不得断章取义地引用或者篡改有关信息、资料；引用有关信息、资料时，应当注明出处和著作权人。"},{"i":21,"n":"第二十一条","txt":"证券、期货投资咨询机构及其投资咨询人员，不得以虚假信息、市场传言或者内幕信息为依据向投资人或者客户提供投资分析、预测或建议。"},{"i":22,"n":"第二十二条","txt":"证券、期货投资咨询人员在报刊、电台、电视台或者其他传播媒体上发表投资咨询文章、报告或者意见时，必须注明所在证券、期货投资咨询机构的名称和个人真实姓名，并对投资风险作充分说明。证券、期货投资咨询机构向投资人或者客户提供的证券、期货投资咨询传真件必须注明机构名称、地址、联系电话和联系人姓名。"},{"i":23,"n":"第二十三条","txt":"证券、期货投资咨询机构与报刊、电台、电视台合办或者协办证券、期货投资咨询版面、节目或者与电信服务部门进行业务合作时，应当向地方证管办（证监会）备案，备案材料包括：合作内容、起止时间、版面安排或者节目时间段、项目负责人等，并加盖双方单位的印鉴。"},{"i":24,"n":"第二十四条","txt":"证券、期货投资咨询机构及其投资咨询人员，不得从事下列活动："},{"i":25,"n":"第二十五条","txt":"证券、期货投资咨询机构就同一问题向不同客户提供的投资分析、预测或者建议应当一致。"},{"i":26,"n":"第二十六条","txt":"证券经营机构、期货经纪机构编发的供本机构内部使用的证券、期货信息简报、快讯、动态以及信息系统等，只能限于本机构范围内使用，不得通过任何途径向社会公众提供。"},{"i":27,"n":"第二十七条","txt":"中国证监会和地方证管办（证监会）有权对证券、期货投资咨询机构和投资咨询人员的业务活动进行检查，被检查的证券、期货投资咨询机构及其投资咨询人员应当予以配合，不得干扰和阻碍。"},{"i":28,"n":"第二十八条","txt":"证券、期货投资咨询机构应当将其向投资人或者社会公众提供的投资咨询资料，自提供之日起保存2年。"},{"i":29,"n":"第二十九条","txt":"地方证管办（证监会）根据投资人或者社会公众的投诉或者举报，有权要求证券、期货投资咨询机构及其投资咨询人员说明情况并提供相关资料。"},{"i":30,"n":"第三十条","txt":"任何单位和个人发现证券、期货投资咨询机构、投资咨询人员或其他机构和个人有违反本办法规定的行为时，可以向地方证管办（证监会）投诉和举报。"},{"i":31,"n":"第三十一条","txt":"地方证管办（证监会）对违反本办法的行为，应当进行立案调查并将调查结果报中国证监会备案。"},{"i":32,"n":"第三十二条","txt":"未经中国证监会许可，擅自从事本办法第二条规定的证券、期货投资咨询业务的，由地方证管办（证监会）责令停止，并处没收违法所得和违法所得等值以下的罚款。"},{"i":33,"n":"第三十三条","txt":"证券、期货投资咨询机构有下列行为之一的，由地方证管办（证监会）处1万元以上，5万元以下的罚款；情节严重的，地方证管办（证监会）应当向中国证监会报告，由中国证监会作出暂停或者撤销其业务资格的处罚："},{"i":34,"n":"第三十四条","txt":"证券、期货投资咨询机构违反本办法第十八条、第十九条、第二十条、第二十一条、第二十二条、第二十三条、第二十四条、第二十五条、第二十八条规定的，由地方证管办（证监会）单处或者并处警告、没收违法所得、1万元以上10万元以下罚款；情节严重的，地方证管办（证监会）应当向中国证监会报告，由中国证监会作出暂停或者撤销业务资格的处罚；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"证券经营机构、期货经纪机构违反本办法第二十六条规定的，由地方证管办（证监会）责令改正，并处以警告或者1万元以上5万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"证券、期货投资咨询人员违反本办法第十八条、第十九条、第二十条、第二十一条、第二十二条、第二十四条的规定或者未按本办法规定向证券主管部门履行报告、年检义务的，由地方证管办（证监会）单处或者并处警告、没收违法所得、1万元以上3万元以下罚款；情节严重的，地方证管办（证监会）应当向中国证监会报告，由中国证监会作出暂停或者撤销其业务资格的处罚；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"中国证监会和地方证管办（证监会）的工作人员玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":38,"n":"第三十八条","txt":"本办法自1998年4月1日起施行。"}],"zhengquanjiaoyisuofengxianjijinguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为保障证券交易系统的安全运转，妥善管理和使用证券交易所风险基金，根据《中华人民共和国证券法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称证券交易所风险基金（以下简称“本基金”）是指用于弥补证券交易所重大经济损失，防范与证券交易所业务活动有关的重大风险事故，以保证证券交易活动正常进行而设立的专项基金。"},{"i":3,"n":"第三条","txt":"本基金来源："},{"i":4,"n":"第四条","txt":"每一个财政年度终了，本基金净资产达到或超过10亿元后，下一年度不再根据本办法第三条第（一）、（二）项提取资金。"},{"i":5,"n":"第五条","txt":"每一个财政年度终了，本基金净资产不足10亿元，下一年度应按本办法第三条第（一）、（二）项规定继续提取资金。"},{"i":6,"n":"第六条","txt":"中国证券监督管理委员会（以下简称“证监会”）会同财政部可以根据市场风险情况，适当调整本基金规模、资金提取和交纳方式、比例。"},{"i":7,"n":"第七条","txt":"本基金由证券交易所理事会管理。理事会应当指定机构，负责本基金的日常管理和使用。"},{"i":8,"n":"第八条","txt":"本基金应当以专户方式全部存入国有商业银行，存款利息全部转入基金专户。"},{"i":9,"n":"第九条","txt":"本基金资产与证券交易所资产分开列账。本基金应当下设分类账，分别记录按本办法第三条各项所形成的本基金资产、利息收入及对应的资产本息使用情况。"},{"i":10,"n":"第十条","txt":"本基金最低支付限额2000万元。"},{"i":11,"n":"第十一条","txt":"按本办法第三条第（四）项所提取的资金，应当在该条其他项资金支付完毕后才能动用。"},{"i":12,"n":"第十二条","txt":"证券交易所应当按照有关法律、法规的规定，建立和完善业务规则、内部管理制度及会员监管制度，最大限度地避免风险事故发生。"},{"i":13,"n":"第十三条","txt":"动用本基金后，证券交易所应当向有关责任方追偿，追偿款转入本基金；同时，应及时修订和完善业务规则、内部管理制度及会员监管制度。"},{"i":14,"n":"第十四条","txt":"经证监会批准，本基金作相应变更、清算时，由证监会会同财政部另行决定本基金剩余资产中应当上交财政和退还有关出资人的比例和数额。"},{"i":15,"n":"第十五条","txt":"本基金的财务核算与管理办法由财政部制定。"},{"i":16,"n":"第十六条","txt":"本办法由证监会负责解释。"},{"i":17,"n":"第十七条","txt":"本办法自颁布之日起施行。"}],"zhengquanqihuoxingzhengzhifadangshirenchengnuozhid99e147":[{"i":1,"n":"第一条","txt":"为了规范证券期货领域行政执法当事人承诺制度的实施，保护投资者合法权益，维护市场秩序，提高行政执法效能，根据《中华人民共和国证券法》（以下简称《证券法》）等法律，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称行政执法当事人承诺，是指国务院证券监督管理机构对涉嫌证券期货违法的单位或者个人进行调查期间，被调查的当事人承诺纠正涉嫌违法行为、赔偿有关投资者损失、消除损害或者不良影响并经国务院证券监督管理机构认可，当事人履行承诺后国务院证券监督管理机构终止案件调查的行政执法方式。"},{"i":3,"n":"第三条","txt":"行政执法当事人承诺制度的实施应当遵循公平、自愿、诚信原则，不得损害国家利益、社会公共利益和他人合法权益。"},{"i":4,"n":"第四条","txt":"国务院证券监督管理机构应当确定专门的内设部门负责行政执法当事人承诺工作，并将该内设部门与负责案件调查的内设部门分别设置。"},{"i":5,"n":"第五条","txt":"当事人自收到国务院证券监督管理机构案件调查法律文书之日至国务院证券监督管理机构作出行政处罚决定前，可以依照《证券法》等法律和本办法的规定，申请适用行政执法当事人承诺。国务院证券监督管理机构应当在送达当事人的案件调查法律文书中告知其有权依法申请适用行政执法当事人承诺。"},{"i":6,"n":"第六条","txt":"当事人申请适用行政执法当事人承诺，应当提交申请书以及相关申请材料。申请书应当载明下列事项："},{"i":7,"n":"第七条","txt":"有下列情形之一的，国务院证券监督管理机构对适用行政执法当事人承诺的申请不予受理："},{"i":8,"n":"第八条","txt":"国务院证券监督管理机构应当自收到当事人完整的申请材料之日起20个工作日内，作出受理或者不予受理的决定。决定受理的，发给受理通知书；决定不予受理的，应当书面通知当事人并说明理由。"},{"i":9,"n":"第九条","txt":"国务院证券监督管理机构受理申请后，在与当事人签署承诺认可协议前，不停止对案件事实的调查。"},{"i":10,"n":"第十条","txt":"国务院证券监督管理机构自受理申请之日起，可以根据当事人涉嫌违法行为造成的损失、损害或者不良影响等情况，就适用行政执法当事人承诺相关事项与当事人进行沟通协商。"},{"i":11,"n":"第十一条","txt":"国务院证券监督管理机构与当事人进行沟通协商的期限为6个月。经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以延长沟通协商的期限，但延长的期限最长不超过6个月。"},{"i":12,"n":"第十二条","txt":"国务院证券监督管理机构相关工作人员与案件有直接利害关系或者有其他关系，可能影响公正执法的，应当回避。"},{"i":13,"n":"第十三条","txt":"国务院证券监督管理机构经与当事人沟通协商，认可当事人作出的承诺的，应当与当事人签署承诺认可协议。承诺认可协议应当载明下列事项："},{"i":14,"n":"第十四条","txt":"国务院证券监督管理机构确定承诺金数额应当综合考虑下列因素："},{"i":15,"n":"第十五条","txt":"国务院证券监督管理机构与当事人签署承诺认可协议后，应当中止案件调查，向当事人出具中止调查决定书，并予以公告。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，国务院证券监督管理机构应当终止适用行政执法当事人承诺："},{"i":17,"n":"第十七条","txt":"国务院证券监督管理机构应当建立集体决策制度，讨论决定行政执法当事人承诺实施过程中的申请受理、签署承诺认可协议、中止或者终止案件调查等重大事项，并经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准后执行。"},{"i":18,"n":"第十八条","txt":"投资者因当事人涉嫌违法行为遭受损失的，可以向承诺金管理机构申请合理赔偿，也可以通过依法对当事人提起民事赔偿诉讼等其他途径获得赔偿。承诺金管理机构向投资者支付的赔偿总额不得超过涉及案件当事人实际交纳并用于赔偿的承诺金总额。投资者已通过其他途径获得赔偿的，不得就已获得赔偿的部分向承诺金管理机构申请赔偿。"},{"i":19,"n":"第十九条","txt":"当事人有下列情形之一的，由国务院证券监督管理机构记入证券期货市场诚信档案数据库，纳入全国信用信息共享平台，按照国家规定实施联合惩戒："},{"i":20,"n":"第二十条","txt":"国务院证券监督管理机构工作人员违反规定适用行政执法当事人承诺，或者泄露履行职责中知悉的商业秘密、个人隐私的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"本办法自2022年1月1日起施行。"}],"pingdingshouyurenminjingchajingxianshishibanfa":[],"susongfeiyongjiaonabanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国民事诉讼法》（以下简称民事诉讼法）和《中华人民共和国行政诉讼法》（以下简称行政诉讼法）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"当事人进行民事诉讼、行政诉讼，应当依照本办法交纳诉讼费用。"},{"i":3,"n":"第三条","txt":"在诉讼过程中不得违反本办法规定的范围和标准向当事人收取费用。"},{"i":4,"n":"第四条","txt":"国家对交纳诉讼费用确有困难的当事人提供司法救助，保障其依法行使诉讼权利，维护其合法权益。"},{"i":5,"n":"第五条","txt":"外国人、无国籍人、外国企业或者组织在人民法院进行诉讼，适用本办法。"},{"i":6,"n":"第六条","txt":"当事人应当向人民法院交纳的诉讼费用包括："},{"i":7,"n":"第七条","txt":"案件受理费包括："},{"i":8,"n":"第八条","txt":"下列案件不交纳案件受理费："},{"i":9,"n":"第九条","txt":"根据民事诉讼法和行政诉讼法规定的审判监督程序审理的案件，当事人不交纳案件受理费。但是，下列情形除外："},{"i":10,"n":"第十条","txt":"当事人依法向人民法院申请下列事项，应当交纳申请费："},{"i":11,"n":"第十一条","txt":"证人、鉴定人、翻译人员、理算人员在人民法院指定日期出庭发生的交通费、住宿费、生活费和误工补贴，由人民法院按照国家规定标准代为收取。"},{"i":12,"n":"第十二条","txt":"诉讼过程中因鉴定、公告、勘验、翻译、评估、拍卖、变卖、仓储、保管、运输、船舶监管等发生的依法应当由当事人负担的费用，人民法院根据谁主张、谁负担的原则，决定由当事人直接支付给有关机构或者单位，人民法院不得代收代付。"},{"i":13,"n":"第十三条","txt":"案件受理费分别按照下列标准交纳："},{"i":14,"n":"第十四条","txt":"申请费分别按照下列标准交纳："},{"i":15,"n":"第十五条","txt":"以调解方式结案或者当事人申请撤诉的，减半交纳案件受理费。"},{"i":16,"n":"第十六条","txt":"适用简易程序审理的案件减半交纳案件受理费。"},{"i":17,"n":"第十七条","txt":"对财产案件提起上诉的，按照不服一审判决部分的上诉请求数额交纳案件受理费。"},{"i":18,"n":"第十八条","txt":"被告提起反诉、有独立请求权的第三人提出与本案有关的诉讼请求，人民法院决定合并审理的，分别减半交纳案件受理费。"},{"i":19,"n":"第十九条","txt":"依照本办法第九条规定需要交纳案件受理费的再审案件，按照不服原判决部分的再审请求数额交纳案件受理费。"},{"i":20,"n":"第二十条","txt":"案件受理费由原告、有独立请求权的第三人、上诉人预交。被告提起反诉，依照本办法规定需要交纳案件受理费的，由被告预交。追索劳动报酬的案件可以不预交案件受理费。"},{"i":21,"n":"第二十一条","txt":"当事人在诉讼中变更诉讼请求数额，案件受理费依照下列规定处理："},{"i":22,"n":"第二十二条","txt":"原告自接到人民法院交纳诉讼费用通知次日起7日内交纳案件受理费；反诉案件由提起反诉的当事人自提起反诉次日起7日内交纳案件受理费。"},{"i":23,"n":"第二十三条","txt":"依照本办法第九条规定需要交纳案件受理费的再审案件，由申请再审的当事人预交。双方当事人都申请再审的，分别预交。"},{"i":24,"n":"第二十四条","txt":"依照民事诉讼法第三十六条、第三十七条、第三十八条、第三十九条规定移送、移交的案件，原受理人民法院应当将当事人预交的诉讼费用随案移交接收案件的人民法院。"},{"i":25,"n":"第二十五条","txt":"人民法院审理民事案件过程中发现涉嫌刑事犯罪并将案件移送有关部门处理的，当事人交纳的案件受理费予以退还；移送后民事案件需要继续审理的，当事人已交纳的案件受理费不予退还。"},{"i":26,"n":"第二十六条","txt":"中止诉讼、中止执行的案件，已交纳的案件受理费、申请费不予退还。中止诉讼、中止执行的原因消除，恢复诉讼、执行的，不再交纳案件受理费、申请费。"},{"i":27,"n":"第二十七条","txt":"第二审人民法院决定将案件发回重审的，应当退还上诉人已交纳的第二审案件受理费。"},{"i":28,"n":"第二十八条","txt":"依照民事诉讼法第一百三十七条规定终结诉讼的案件，依照本办法规定已交纳的案件受理费不予退还。"},{"i":29,"n":"第二十九条","txt":"诉讼费用由败诉方负担，胜诉方自愿承担的除外。"},{"i":30,"n":"第三十条","txt":"第二审人民法院改变第一审人民法院作出的判决、裁定的，应当相应变更第一审人民法院对诉讼费用负担的决定。"},{"i":31,"n":"第三十一条","txt":"经人民法院调解达成协议的案件，诉讼费用的负担由双方当事人协商解决；协商不成的，由人民法院决定。"},{"i":32,"n":"第三十二条","txt":"依照本办法第九条第（一）项、第（二）项的规定应当交纳案件受理费的再审案件，诉讼费用由申请再审的当事人负担；双方当事人都申请再审的，诉讼费用依照本办法第二十九条的规定负担。原审诉讼费用的负担由人民法院根据诉讼费用负担原则重新确定。"},{"i":33,"n":"第三十三条","txt":"离婚案件诉讼费用的负担由双方当事人协商解决；协商不成的，由人民法院决定。"},{"i":34,"n":"第三十四条","txt":"民事案件的原告或者上诉人申请撤诉，人民法院裁定准许的，案件受理费由原告或者上诉人负担。"},{"i":35,"n":"第三十五条","txt":"当事人在法庭调查终结后提出减少诉讼请求数额的，减少请求数额部分的案件受理费由变更诉讼请求的当事人负担。"},{"i":36,"n":"第三十六条","txt":"债务人对督促程序未提出异议的，申请费由债务人负担。债务人对督促程序提出异议致使督促程序终结的，申请费由申请人负担；申请人另行起诉的，可以将申请费列入诉讼请求。"},{"i":37,"n":"第三十七条","txt":"公示催告的申请费由申请人负担。"},{"i":38,"n":"第三十八条","txt":"本办法第十条第（一）项、第（八）项规定的申请费由被执行人负担。"},{"i":39,"n":"第三十九条","txt":"海事案件中的有关诉讼费用依照下列规定负担："},{"i":40,"n":"第四十条","txt":"当事人因自身原因未能在举证期限内举证，在二审或者再审期间提出新的证据致使诉讼费用增加的，增加的诉讼费用由该当事人负担。"},{"i":41,"n":"第四十一条","txt":"依照特别程序审理案件的公告费，由起诉人或者申请人负担。"},{"i":42,"n":"第四十二条","txt":"依法向人民法院申请破产的，诉讼费用依照有关法律规定从破产财产中拨付。"},{"i":43,"n":"第四十三条","txt":"当事人不得单独对人民法院关于诉讼费用的决定提起上诉。"},{"i":44,"n":"第四十四条","txt":"当事人交纳诉讼费用确有困难的，可以依照本办法向人民法院申请缓交、减交或者免交诉讼费用的司法救助。"},{"i":45,"n":"第四十五条","txt":"当事人申请司法救助，符合下列情形之一的，人民法院应当准予免交诉讼费用："},{"i":46,"n":"第四十六条","txt":"当事人申请司法救助，符合下列情形之一的，人民法院应当准予减交诉讼费用："},{"i":47,"n":"第四十七条","txt":"当事人申请司法救助，符合下列情形之一的，人民法院应当准予缓交诉讼费用："},{"i":48,"n":"第四十八条","txt":"当事人申请司法救助，应当在起诉或者上诉时提交书面申请、足以证明其确有经济困难的证明材料以及其他相关证明材料。"},{"i":49,"n":"第四十九条","txt":"当事人申请缓交诉讼费用经审查符合本办法第四十七条规定的，人民法院应当在决定立案之前作出准予缓交的决定。"},{"i":50,"n":"第五十条","txt":"人民法院对一方当事人提供司法救助，对方当事人败诉的，诉讼费用由对方当事人负担；对方当事人胜诉的，可以视申请司法救助的当事人的经济状况决定其减交、免交诉讼费用。"},{"i":51,"n":"第五十一条","txt":"人民法院准予当事人减交、免交诉讼费用的，应当在法律文书中载明。"},{"i":52,"n":"第五十二条","txt":"诉讼费用的交纳和收取制度应当公示。人民法院收取诉讼费用按照其财务隶属关系使用国务院财政部门或者省级人民政府财政部门印制的财政票据。案件受理费、申请费全额上缴财政，纳入预算，实行收支两条线管理。"},{"i":53,"n":"第五十三条","txt":"案件审结后，人民法院应当将诉讼费用的详细清单和当事人应当负担的数额书面通知当事人，同时在判决书、裁定书或者调解书中写明当事人各方应当负担的数额。"},{"i":54,"n":"第五十四条","txt":"价格主管部门、财政部门按照收费管理的职责分工，对诉讼费用进行管理和监督；对违反本办法规定的乱收费行为，依照法律、法规和国务院相关规定予以查处。"},{"i":55,"n":"第五十五条","txt":"诉讼费用以人民币为计算单位。以外币为计算单位的，依照人民法院决定受理案件之日国家公布的汇率换算成人民币计算交纳；上诉案件和申请再审案件的诉讼费用，按照第一审人民法院决定受理案件之日国家公布的汇率换算。"},{"i":56,"n":"第五十六条","txt":"本办法自2007年4月1日起施行。"}],"jinkouyingpianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对进口影片的管理，根据一九八〇年四月十四日中共中央、国务院、中央军委《关于制止滥放内部参考影片的通知》精神，特制订本办法。"},{"i":2,"n":"第二条","txt":"凡属从外国及港澳地区进口发行影片或试映拷贝（包括35毫米、16毫米、超8毫米、影片录相带和影片视盘等，以下统称影片）的业务，统一由中国电影发行放映公司（以下简称中影公司）经营管理。"},{"i":3,"n":"第三条","txt":"中国电影资料馆进口的资料影片（包括中国电影资料馆与外国电影资料馆互相选购、交换、赠送或通过其他途径购作资料的影片），属于非商业性影片，海关凭该馆填报的进口货物报关单核查免税放行。"},{"i":4,"n":"第四条","txt":"科学技术、工业、农业、教育、卫生、新闻、外贸、外事等单位，因业务需要进口的专业性纪录、科教影片，属于国务院系统的单位进口的，由国务院各部委（总局）审批；属于地方单位进口的，由省、自治区、直辖市人民政府审批。"},{"i":5,"n":"第五条","txt":"外国、港澳地区及台湾省的团体或个人运进给机关、团体、学校等单位的故事片，凡属国务院系统的单位接受的，须经文化部电影事业管理局审批；属地方单位接受的，须经省、自治区、直辖市文化局（电影局）审批，并抄送文化部电影事业管理局备案。"},{"i":6,"n":"第六条","txt":"对外国人和华侨、港澳及台湾省同胞等邮寄或者入境随身携带属于赠给我国个人作为业务参考的科教影片，海关应准许进口，并凭接受影片的个人填报的进口货物报关单及其所在单位的证明信件核查免税放行。属于赠给我国个人的故事影片，一般地不准进口，海关予以退运。如遇特殊情况，由文化部和海关总署研究处理。"},{"i":7,"n":"第七条","txt":"除香港长城、凤凰、新联三公司回内地拍片，由国务院港澳办公室同有关地区和有关单位直接联系外，凡属中外或我与港澳地区及台湾省的合作制片业务，统由中国电影合作制片公司管理。合拍影片的进口，由中国电影合作制片公司向海关办理进口报关手续；其中批准在全国发行的，则由中影公司按章向北京海关办理补税手续。"},{"i":8,"n":"第八条","txt":"对违反规定进口的或走私进口的影片，海关按有关规定处理；对没收的影片，凡有保留参考价值的可转送文化部电影事业管理局交中国电影资料馆保存。"},{"i":9,"n":"第九条","txt":"本办法自发布之日起施行。"}],"jinrongweifaxingweichufabanfa":[{"i":1,"n":"第一条","txt":"为了惩处金融违法行为，维护金融秩序，防范金融风险，制定本办法。"},{"i":2,"n":"第二条","txt":"金融机构违反国家有关金融管理的规定，有关法律、行政法规有处罚规定的，依照其规定给予处罚；有关法律、行政法规未作处罚规定或者有关行政法规的处罚规定与本办法不一致的，依照本办法给予处罚。"},{"i":3,"n":"第三条","txt":"本办法规定的行政处罚，由中国人民银行决定；但是本办法第二十四条、第二十五条规定的行政处罚，由国家外汇管理机关决定。"},{"i":4,"n":"第四条","txt":"金融机构的工作人员离开该金融机构工作后，被发现在该金融机构工作期间违反国家有关金融管理规定的，仍然应当依法追究责任。"},{"i":5,"n":"第五条","txt":"金融机构设立、合并、撤销分支机构或者代表机构的，应当经中国人民银行批准。"},{"i":6,"n":"第六条","txt":"金融机构有下列情形之一的，应当经中国人民银行批准："},{"i":7,"n":"第七条","txt":"金融机构变更股东、转让股权或者调整股权结构的，应当经中国人民银行批准；涉及国有股权变动的，并应当按照规定经财政部门批准。"},{"i":8,"n":"第八条","txt":"金融机构不得虚假出资或者抽逃出资。"},{"i":9,"n":"第九条","txt":"金融机构不得超出中国人民银行批准的业务范围从事金融业务活动。"},{"i":10,"n":"第十条","txt":"金融机构的代表机构不得经营金融业务。"},{"i":11,"n":"第十一条","txt":"金融机构不得以下列方式从事帐外经营行为："},{"i":12,"n":"第十二条","txt":"金融机构不得提供虚假的或者隐瞒重要事实的财务会计报告、统计报告。"},{"i":13,"n":"第十三条","txt":"金融机构不得出具与事实不符的信用证、保函、票据、存单、资信证明等金融票证。"},{"i":14,"n":"第十四条","txt":"金融机构对违反票据法规定的票据，不得承兑、贴现、付款或者保证。"},{"i":15,"n":"第十五条","txt":"金融机构办理存款业务，不得有下列行为："},{"i":16,"n":"第十六条","txt":"金融机构办理贷款业务，不得有下列行为："},{"i":17,"n":"第十七条","txt":"金融机构从事拆借活动，不得有下列行为："},{"i":18,"n":"第十八条","txt":"金融机构不得违反国家规定从事证券、期货或者其他衍生金融工具交易，不得为证券、期货或者其他衍生金融工具交易提供信贷资金或者担保，不得违反国家规定从事非自用不动产、股权、实业等投资活动。"},{"i":19,"n":"第十九条","txt":"金融机构应当遵守中国人民银行有关现金管理的规定，不得允许单位或者个人超限额提取现金。"},{"i":20,"n":"第二十条","txt":"金融机构应当遵守中国人民银行有关信用卡管理的规定，不得违反规定对持卡人透支或者帮助持卡人利用信用卡套取现金。"},{"i":21,"n":"第二十一条","txt":"金融机构应当遵守中国人民银行有关资产负债比例管理的规定。"},{"i":22,"n":"第二十二条","txt":"金融机构不得占压财政存款或者资金。"},{"i":23,"n":"第二十三条","txt":"金融机构应当依法协助税务机关、海关办理对纳税人存款的冻结、扣划。"},{"i":24,"n":"第二十四条","txt":"经营外汇业务的金融机构应当遵守国家外汇管理规定。"},{"i":25,"n":"第二十五条","txt":"经营外汇业务的金融机构，不得有下列行为："},{"i":26,"n":"第二十六条","txt":"商业银行不得为证券、期货交易资金清算透支或者为新股申购透支。"},{"i":27,"n":"第二十七条","txt":"财务公司不得有下列行为："},{"i":28,"n":"第二十八条","txt":"信托投资公司不得以办理委托、信托业务名义吸收公众存款、发放贷款，不得违反国家规定办理委托、信托业务。"},{"i":29,"n":"第二十九条","txt":"金融机构缴纳的罚款和被没收的违法所得，不得列入该金融机构的成本、费用。"},{"i":30,"n":"第三十条","txt":"对中国人民银行所属从事金融业务的机构的金融违法行为的处罚，适用本办法。"},{"i":31,"n":"第三十一条","txt":"对证券违法行为的处罚，依照国家有关证券管理的法律、行政法规执行，不适用本办法。"},{"i":32,"n":"第三十二条","txt":"本办法自发布之日起施行。"}],"shiyanzhuanyingbanfa":[{"i":1,"n":"第一条","txt":"为了加强对食盐的管理，保障食盐科学加碘工作的有效实施，确保食盐质量安全和供应安全，保护公民的身体健康，制定本办法。"},{"i":2,"n":"第二条","txt":"国家实行食盐专营管理。"},{"i":3,"n":"第三条","txt":"本办法适用于中华人民共和国境内的食盐生产、销售和储备活动。"},{"i":4,"n":"第四条","txt":"国务院盐业主管部门主管全国盐业工作，负责管理全国食盐专营工作。县级以上地方人民政府确定的盐业主管部门负责管理本行政区域的食盐专营工作。"},{"i":5,"n":"第五条","txt":"盐业主管部门应当加强对工业用盐等非食用盐的管理，防止非食用盐流入食盐市场。"},{"i":6,"n":"第六条","txt":"国务院盐业主管部门应当会同有关部门加强对食盐生产、批发企业及其董事、监事、高级管理人员的信用管理，建立健全信用信息记录、公示制度，提高食盐行业信用水平。"},{"i":7,"n":"第七条","txt":"依法成立的盐业行业组织依照法律、行政法规和章程，保护企业合法权益，加强行业自律，促进企业守法、诚信经营，引导企业公平竞争。"},{"i":8,"n":"第八条","txt":"国家实行食盐定点生产制度。非食盐定点生产企业不得生产食盐。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市人民政府盐业主管部门按照统一规划、合理布局的要求审批确定食盐定点生产企业，颁发食盐定点生产企业证书，及时向社会公布食盐定点生产企业名单，并报国务院盐业主管部门备案。"},{"i":10,"n":"第十条","txt":"食盐定点生产企业和非食用盐生产企业应当建立生产销售记录制度，如实记录并保存相关凭证。记录和凭证保存期限不得少于2年。"},{"i":11,"n":"第十一条","txt":"禁止利用井矿盐卤水熬制食盐。"},{"i":12,"n":"第十二条","txt":"国家实行食盐定点批发制度。非食盐定点批发企业不得经营食盐批发业务。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府盐业主管部门按照统一规划、合理布局的要求审批确定食盐定点批发企业，颁发食盐定点批发企业证书，及时向社会公布食盐定点批发企业名单，并报国务院盐业主管部门备案。"},{"i":14,"n":"第十四条","txt":"食盐定点批发企业应当从食盐定点生产企业或者其他食盐定点批发企业购进食盐，在国家规定的范围内销售。"},{"i":15,"n":"第十五条","txt":"食盐定点批发企业应当建立采购销售记录制度，如实记录并保存相关凭证。记录和凭证保存期限不得少于2年。"},{"i":16,"n":"第十六条","txt":"食盐零售单位应当从食盐定点批发企业购进食盐。"},{"i":17,"n":"第十七条","txt":"食盐价格由经营者自主确定。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府应当根据实际情况，采取必要措施，保障边远地区和民族地区的食盐供应。"},{"i":19,"n":"第十九条","txt":"禁止销售不符合食品安全标准的食盐。"},{"i":20,"n":"第二十条","txt":"省、自治区、直辖市人民政府盐业主管部门应当根据本行政区域食盐供需情况，建立健全食盐储备制度，承担政府食盐储备责任。"},{"i":21,"n":"第二十一条","txt":"食盐定点生产企业和食盐定点批发企业应当按照食盐储备制度要求，承担企业食盐储备责任，保持食盐的合理库存。"},{"i":22,"n":"第二十二条","txt":"盐业主管部门应当会同有关部门制定食盐供应应急预案，在发生突发事件时协调、保障食盐供应。"},{"i":23,"n":"第二十三条","txt":"盐业主管部门依法履行监督检查职责，可以采取下列措施："},{"i":24,"n":"第二十四条","txt":"盐业主管部门、食盐质量安全监督管理部门应当各司其职，加强协作，相互配合，通过政务信息系统等实现信息共享，建立健全行政执法协作配合制度。"},{"i":25,"n":"第二十五条","txt":"盐业主管部门、食盐质量安全监督管理部门应当向社会公布本部门的联系方式，方便公众举报违法行为。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，由县级以上地方人民政府盐业主管部门予以取缔，没收违法生产经营的食盐和违法所得。违法生产经营的食盐货值金额不足1万元的，可以处5万元以下的罚款；货值金额1万元以上的，并处货值金额5倍以上10倍以下的罚款："},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，由县级以上地方人民政府盐业主管部门责令改正，处5000元以上5万元以下的罚款；情节严重的，责令停产停业整顿，直至吊销食盐定点生产、食盐定点批发企业证书："},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，由县级以上地方人民政府盐业主管部门责令改正，没收违法购进的食盐，可以处违法购进的食盐货值金额3倍以下的罚款："},{"i":29,"n":"第二十九条","txt":"未按照本办法第十条的规定作出标识的，由有关主管部门依据职责分工，责令改正，可以处5万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"经营者的行为违反本办法的规定同时违反《中华人民共和国食品安全法》的，由县级以上地方人民政府食盐质量安全监督管理部门依照《中华人民共和国食品安全法》进行处罚。"},{"i":31,"n":"第三十一条","txt":"食盐定点生产企业、食盐定点批发企业违反本办法的规定，被处以吊销食盐定点生产、食盐定点批发企业证书行政处罚的，其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起5年内不得从事食盐生产经营管理活动，不得担任食盐定点生产企业、食盐定点批发企业的董事、监事或者高级管理人员。"},{"i":32,"n":"第三十二条","txt":"违反本办法的规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"盐业主管部门以及其他有关部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":34,"n":"第三十四条","txt":"除本办法的规定外，食盐质量安全监督管理、食盐加碘工作还应当依照有关法律、行政法规的规定执行。"},{"i":35,"n":"第三十五条","txt":"渔业、畜牧用盐管理办法，由国务院盐业主管部门会同国务院农业行政主管部门另行制定。"},{"i":36,"n":"第三十六条","txt":"本办法自公布之日起施行。1990年3月2日国务院发布的《盐业管理条例》同时废止。"}]};
